/// Maximum top-level operations plus nested rename rows in one submission.
pub const MAX_LOCAL_MUTATION_ROWS: usize = 1024;
/// Maximum managed-path references retained by one submission.
pub const MAX_LOCAL_MUTATION_REFERENCED_PATHS: usize = 512;
/// Maximum aggregate UTF-8 bytes in every referenced managed path.
pub const MAX_LOCAL_MUTATION_PATH_BYTES: usize = 256 * 1024;
/// Maximum aggregate UTF-8 bytes in names, content, preambles, and order keys.
pub const MAX_LOCAL_MUTATION_TEXT_BYTES: usize = 1024 * 1024;
/// The public boundary uses the materialization's proven row cap. Every query
/// validates this before it is placed on the actor queue.
pub const MAX_SYNC_RUNTIME_QUERY_ROWS: usize = MAX_MATERIALIZATION_QUERY_ROWS;
/// Bound aggregate request retention independently of any individual SQLite
/// predicate. This also bounds multi-field requests such as property filters.
pub const MAX_SYNC_RUNTIME_QUERY_BYTES: usize = MAX_MATERIALIZATION_QUERY_BYTES;
/// A whole-page editor save can require both content and membership operations
/// for every retained block plus one preamble operation.
pub const MAX_SYNC_EDITOR_BLOCKS: usize = (MAX_LOCAL_MUTATION_ROWS - 2) / 2;
/// Existing application pages are read as bounded SQLite projections. Their
/// size is independent of the number of operations an eventual edit emits.
pub const MAX_SYNC_APPLICATION_PAGE_BLOCKS: usize = MAX_MATERIALIZATION_QUERY_ROWS - 1;
/// Deep outlines are rejected before actor enqueue and are traversed
/// iteratively on both sides of the actor boundary.
pub const MAX_SYNC_EDITOR_DEPTH: usize = 128;
/// Temporary keys are request-local labels, not durable identities.
pub const MAX_SYNC_EDITOR_TEMP_KEY_BYTES: usize = 256;
/// Aggregate retained editor request bytes, independently of per-field caps.
pub const MAX_SYNC_EDITOR_REQUEST_BYTES: usize = MAX_LOCAL_MUTATION_TEXT_BYTES;
const MAX_SYNC_APPLICATION_RESULT_BYTES: usize = 32 * 1024 * 1024;
const MAX_SYNC_APPLICATION_RESULT_ROWS: usize = 20_000;
/// Application-page block IDs without external Logseq identity are deliberately
/// outside UUID syntax so the frontend cannot mistake sparse storage identity
/// for a portable block reference.
pub const SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX: &str = "sparse-v2:";
const MAX_EDITOR_SETTLE_TURNS: usize = 64;

