/// Explicit paths for one already-enrolled local runtime.
///
/// No path is inspected for `LegacyDefault`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncRuntimeOpenRequest {
    pub profile: SyncStorageProfile,
    pub graph_root: PathBuf,
    pub enrollment_root: PathBuf,
    pub archive_root: PathBuf,
    pub receipt_root: PathBuf,
    pub database_path: PathBuf,
    pub application_runtime_root: PathBuf,
    pub migration_backup_root: PathBuf,
    pub provider_root: PathBuf,
    pub provider_journal_root: PathBuf,
}

/// Every caller-provided identity bound into one explicit local activation.
///
/// The public API never generates these values: callers persist them alongside
/// the activation request and pass the same values again to resume an
/// interrupted `ShadowImport` or `VerifiedLocal` attempt.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncLocalActivationIdentities {
    pub workspace_id: WorkspaceId,
    pub lineage_digest: LineageDigest,
    pub catalog_document_id: DocumentId,
    pub endpoint_id: ProjectionEndpointId,
    pub device_id: DeviceId,
    pub preparation_id: Uuid,
    pub session_id: SessionId,
}

/// Explicit opt-in input for the bounded local sparse-oplog activation path.
///
/// `archive_root` must be exactly `<graph>/.tine-sync/v2`: it is the only
/// activation artifact permitted inside the graph. Every other supplied path
/// is checked before use and must remain outside the graph's canonical root.
/// No normal startup path constructs this request or calls the activation API.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncLocalActivationRequest {
    pub graph_root: PathBuf,
    pub archive_root: PathBuf,
    pub enrollment_root: PathBuf,
    pub receipt_root: PathBuf,
    pub database_path: PathBuf,
    pub application_runtime_root: PathBuf,
    pub migration_backup_root: PathBuf,
    pub capture_root: PathBuf,
    pub preparation_root: PathBuf,
    pub provider_root: PathBuf,
    pub provider_journal_root: PathBuf,
    pub identities: SyncLocalActivationIdentities,
}

/// The only durable activation states the public composition can resume.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncLocalActivationStage {
    Absent,
    ShadowImport,
    VerifiedLocal,
    LocalActive,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct SyncSharedEnrollmentDescriptor {
    encoded: Vec<u8>,
    pub workspace_id: WorkspaceId,
    pub lineage_digest: LineageDigest,
    pub catalog_document_id: DocumentId,
    pub descriptor_digest: String,
}

/// Structural provider-prefix state observed before cold descriptor discovery.
/// `Partial` is retryable honest file-sync delivery; `Refused` is an unsafe or
/// ambiguous shape and deliberately carries no storage authority.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncSharedProviderColdPrefix {
    Partial,
    ReadyForDescriptorInspection,
    Refused,
}

pub fn inspect_shared_provider_cold_prefix(
    provider_root: &Path,
) -> Result<SyncSharedProviderColdPrefix, String> {
    match inspect_cold_shared_provider_prefix(provider_root).map_err(display)? {
        ColdSharedProviderPrefix::Partial => Ok(SyncSharedProviderColdPrefix::Partial),
        ColdSharedProviderPrefix::ReadyForDescriptorInspection => {
            Ok(SyncSharedProviderColdPrefix::ReadyForDescriptorInspection)
        }
        ColdSharedProviderPrefix::Refused => Ok(SyncSharedProviderColdPrefix::Refused),
    }
}

impl SyncSharedEnrollmentDescriptor {
    fn from_core(descriptor: SharedEnrollmentDescriptorV1) -> Result<Self, String> {
        Ok(Self {
            encoded: descriptor.encode().map_err(display)?,
            workspace_id: descriptor.workspace_id(),
            lineage_digest: descriptor.lineage_digest(),
            catalog_document_id: descriptor.catalog_document_id(),
            descriptor_digest: descriptor.digest().map_err(display)?.to_string(),
        })
    }

    fn decode(&self) -> Result<SharedEnrollmentDescriptorV1, String> {
        SharedEnrollmentDescriptorV1::decode(&self.encoded).map_err(display)
    }
}

pub fn inspect_shared_enrollment(
    provider_root: &Path,
) -> Result<Option<SyncSharedEnrollmentDescriptor>, String> {
    inspect_shared_provider_descriptor(provider_root)
        .map_err(display)?
        .map(|bytes| SharedEnrollmentDescriptorV1::decode(&bytes).map_err(display))
        .transpose()?
        .map(SyncSharedEnrollmentDescriptor::from_core)
        .transpose()
}

pub fn inspect_shared_enrollment_for_cold_discovery(
    provider_root: &Path,
) -> Result<Option<SyncSharedEnrollmentDescriptor>, String> {
    // The canonical descriptor carries the authority.  Sibling provider
    // artifacts are not authority and can legitimately be present while a
    // filesystem sync is settling (temporary files, conflict copies, or newer
    // append-only namespaces), so cold discovery must not require the
    // enrollment directory to contain literally one entry.
    let Some(bytes) = inspect_shared_provider_descriptor(provider_root).map_err(display)? else {
        return Ok(None);
    };
    // File-sync providers may expose the canonical filename before its final
    // bytes arrive.  Only decoding/record-validation failures are therefore a
    // retryable partial arrival.  Filesystem validation failures are local
    // platform errors and must remain visible to the caller instead of being
    // mislabeled as an unfinished sync.
    let Ok(descriptor) = SharedEnrollmentDescriptorV1::decode(&bytes) else {
        return Ok(None);
    };
    match SyncSharedEnrollmentDescriptor::from_core(descriptor) {
        Ok(descriptor) => Ok(Some(descriptor)),
        Err(_) => Ok(None),
    }
}

