/// Bound public request validation as well as actor intake. A batch above the
/// count cap is already known to require a full scan, so only inspect a fixed
/// prefix. The result is exact while it remains within the byte cap; once the
/// cap is crossed it is merely a bounded overflow witness.
fn bounded_watcher_path_bytes(observations: &[SyncWatcherObservation]) -> usize {
    let mut path_bytes = 0_usize;
    for observation in observations.iter().take(MAX_WATCHER_OBSERVATIONS) {
        path_bytes = path_bytes.saturating_add(observation.retained_path_bytes());
        if path_bytes > MAX_WATCHER_PATH_BYTES {
            break;
        }
    }
    path_bytes
}

fn validate_local_mutation_request(
    transaction: OperationTransaction,
) -> Result<OperationTransaction, SyncLocalMutationRequestError> {
    let size = bounded_local_mutation_size(&transaction);
    if local_size_exceeded(size) {
        return Err(SyncLocalMutationRequestError::RequestTooLarge(size));
    }
    if transaction.operations.iter().any(|operation| {
        matches!(
            operation,
            SemanticOperation::ReconcileExternalPageState { .. }
        )
    }) {
        return Err(SyncLocalMutationRequestError::InvalidTransaction);
    }
    OperationTransaction::new(transaction.operations)
        .map_err(|_| SyncLocalMutationRequestError::InvalidTransaction)
}

fn bounded_local_mutation_size(transaction: &OperationTransaction) -> SyncLocalMutationRequestSize {
    let mut size = SyncLocalMutationRequestSize {
        rows: 0,
        referenced_paths: 0,
        path_bytes: 0,
        text_bytes: 0,
    };
    for operation in transaction
        .operations
        .iter()
        .take(MAX_LOCAL_MUTATION_ROWS + 1)
    {
        charge_local_row(&mut size);
        match operation {
            SemanticOperation::CreatePage { name, path, .. }
            | SemanticOperation::ReconcileExternalPageState { name, path, .. } => {
                charge_local_text(&mut size, name.as_str().len());
                charge_local_path(&mut size, path);
            }
            SemanticOperation::EditPagePath { path, .. } => {
                charge_local_path(&mut size, path);
            }
            SemanticOperation::SetPagePreamble { preamble, .. } => {
                charge_local_text(&mut size, preamble.as_ref().map_or(0, String::len));
            }
            SemanticOperation::CreateBlock { order, content, .. } => {
                charge_local_text(&mut size, order.len());
                charge_local_text(&mut size, content.len());
            }
            SemanticOperation::EditBlockContent { content, .. } => {
                charge_local_text(&mut size, content.len());
            }
            SemanticOperation::MoveSubtree { order, .. }
            | SemanticOperation::ReorderBlock { order, .. } => {
                charge_local_text(&mut size, order.len());
            }
            SemanticOperation::RenamePagesAndRewriteReferrers {
                page_changes,
                block_rewrites,
                page_preamble_rewrites,
            } => {
                for change in page_changes {
                    charge_local_row(&mut size);
                    charge_local_text(&mut size, change.new_name.as_str().len());
                    charge_local_path(&mut size, &change.new_path);
                    if size.rows > MAX_LOCAL_MUTATION_ROWS {
                        break;
                    }
                }
                if size.rows <= MAX_LOCAL_MUTATION_ROWS {
                    for rewrite in block_rewrites {
                        charge_local_row(&mut size);
                        charge_local_text(&mut size, rewrite.new_content.len());
                        if size.rows > MAX_LOCAL_MUTATION_ROWS {
                            break;
                        }
                    }
                }
                if size.rows <= MAX_LOCAL_MUTATION_ROWS {
                    for rewrite in page_preamble_rewrites {
                        charge_local_row(&mut size);
                        charge_local_text(
                            &mut size,
                            rewrite.new_preamble.as_ref().map_or(0, String::len),
                        );
                        if size.rows > MAX_LOCAL_MUTATION_ROWS {
                            break;
                        }
                    }
                }
            }
            SemanticOperation::SetPageKind { .. }
            | SemanticOperation::MutateBlockLogseqIdentity { .. }
            | SemanticOperation::DeleteSubtree { .. }
            | SemanticOperation::DeletePage { .. } => {}
        }
        if local_size_exceeded(size) {
            break;
        }
    }
    if transaction.operations.len() > MAX_LOCAL_MUTATION_ROWS {
        size.rows = MAX_LOCAL_MUTATION_ROWS + 1;
    }
    size
}

fn charge_local_row(size: &mut SyncLocalMutationRequestSize) {
    size.rows = bounded_charge(size.rows, 1, MAX_LOCAL_MUTATION_ROWS);
}

fn charge_local_path(size: &mut SyncLocalMutationRequestSize, path: &ManagedPath) {
    size.referenced_paths = bounded_charge(
        size.referenced_paths,
        1,
        MAX_LOCAL_MUTATION_REFERENCED_PATHS,
    );
    size.path_bytes = bounded_charge(
        size.path_bytes,
        path.as_str().len(),
        MAX_LOCAL_MUTATION_PATH_BYTES,
    );
}

fn charge_local_text(size: &mut SyncLocalMutationRequestSize, bytes: usize) {
    size.text_bytes = bounded_charge(size.text_bytes, bytes, MAX_LOCAL_MUTATION_TEXT_BYTES);
}

fn bounded_charge(current: usize, charge: usize, limit: usize) -> usize {
    current.saturating_add(charge).min(limit.saturating_add(1))
}

fn local_size_exceeded(size: SyncLocalMutationRequestSize) -> bool {
    size.rows > MAX_LOCAL_MUTATION_ROWS
        || size.referenced_paths > MAX_LOCAL_MUTATION_REFERENCED_PATHS
        || size.path_bytes > MAX_LOCAL_MUTATION_PATH_BYTES
        || size.text_bytes > MAX_LOCAL_MUTATION_TEXT_BYTES
}

fn map_local_actor_error(_: SyncRuntimeRequestError) -> SyncLocalMutationRequestError {
    SyncLocalMutationRequestError::ActorUnavailable
}

fn map_editor_actor_error(_: SyncRuntimeRequestError) -> SyncEditorRequestError {
    SyncEditorRequestError::ActorUnavailable
}

fn map_application_actor_error(_: SyncRuntimeRequestError) -> SyncApplicationPageRequestError {
    SyncApplicationPageRequestError::ActorUnavailable
}

fn check_query_limit(limit: usize, request_bytes: usize) -> Result<(), SyncRuntimeRequestError> {
    if limit == 0 || limit > MAX_SYNC_RUNTIME_QUERY_ROWS {
        return Err(SyncRuntimeRequestError::QueryTooLarge {
            limit,
            request_bytes,
        });
    }
    Ok(())
}

fn validate_query_request(
    request: &SyncRuntimeQueryRequest,
) -> Result<(), SyncRuntimeRequestError> {
    let mut bytes = 0_usize;
    let mut add = |value: &str| {
        bytes = bytes.saturating_add(value.len());
    };
    let limit = match request {
        SyncRuntimeQueryRequest::ResolvePage { path, name, .. } => {
            add(path);
            add(name);
            1
        }
        SyncRuntimeQueryRequest::ResolvePageByName { name, .. } => {
            add(name);
            2
        }
        SyncRuntimeQueryRequest::ListPages { limit, .. }
        | SyncRuntimeQueryRequest::Search { limit, .. }
        | SyncRuntimeQueryRequest::PropertiesForOwner { limit, .. }
        | SyncRuntimeQueryRequest::PropertiesNamed { limit, .. }
        | SyncRuntimeQueryRequest::Tags { limit, .. }
        | SyncRuntimeQueryRequest::Tasks { limit, .. }
        | SyncRuntimeQueryRequest::ReferencesToPageName { limit, .. }
        | SyncRuntimeQueryRequest::ReferencesToLogseqUuid { limit, .. } => {
            match request {
                SyncRuntimeQueryRequest::Search { query, .. } => add(query),
                SyncRuntimeQueryRequest::PropertiesNamed { name, value, .. } => {
                    add(name);
                    if let Some(value) = value {
                        add(value);
                    }
                }
                SyncRuntimeQueryRequest::Tags { tag, .. } => add(tag),
                SyncRuntimeQueryRequest::Tasks { marker, .. } => {
                    if let Some(marker) = marker {
                        add(marker);
                    }
                }
                SyncRuntimeQueryRequest::ReferencesToPageName { name, .. } => add(name),
                SyncRuntimeQueryRequest::ReferencesToLogseqUuid { logseq_uuid, .. } => {
                    add(logseq_uuid)
                }
                SyncRuntimeQueryRequest::ListPages { .. } => {}
                SyncRuntimeQueryRequest::PropertiesForOwner { owner, .. } => match owner {
                    SyncEntityId::Page(id) | SyncEntityId::Block(id) => add(id),
                },
                _ => unreachable!("all query request variants are covered"),
            }
            *limit
        }
        SyncRuntimeQueryRequest::LoadPage {
            page_id,
            block_limit,
        } => {
            add(page_id);
            *block_limit
        }
    };
    if bytes > MAX_SYNC_RUNTIME_QUERY_BYTES {
        return Err(SyncRuntimeRequestError::QueryTooLarge {
            limit,
            request_bytes: bytes,
        });
    }
    check_query_limit(limit, bytes)
}

/// Compose the already-proven inactive primitives without exposing any of
/// their proof-bearing capabilities outside this module.  Every operation
/// before the final actor open is explicitly requested by
/// `SyncLocalActivationRequest`; normal graph startup cannot reach here.
/// The one private, process-local activation handoff. It carries every
/// capability that was proven while building the inactive bootstrap and then
/// promoted under the same workspace lease. It is deliberately move-only and
/// private to this module: a fresh process cannot construct it from durable
/// state, a failed proof never reaches it, and its graph, archive, SQLite,
/// receipt, enrollment, and binding-generation facts remain inseparable until
/// the actor accepts ownership.
struct SameProcessActivationHandoff {
    graph: Graph,
    receipts: ProjectionReceiptStore,
    authority: LocalActiveAuthority,
    runtime: PromotedLocalRuntime,
    baseline: ReconciliationBaseline,
    enrollment_root: EnrollmentApplicationRoot,
    binding: EnrollmentBindingV1,
    session_id: SessionId,
    promotion_session_id: SessionId,
    promoted_state_digest: ContentDigest,
}

fn activate_non_active_local(
    request: SyncLocalActivationRequest,
    graph: Graph,
    existing_binding: Option<EnrollmentBindingV1>,
    progress: &mut dyn FnMut(SyncLocalActivationProgress),
) -> Result<SameProcessActivationHandoff, String> {
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::PrivateSetup,
    });
    prepare_activation_private_paths(&request)
        .map_err(|error| format!("prepare private activation paths: {error}"))?;
    let enrollment = EnrollmentApplicationRoot::open_explicit_private(&request.enrollment_root)
        .map_err(|error| format!("open private enrollment state: {error}"))?;
    let application_runtime_root =
        ApplicationRuntimeRoot::open_explicit_private(&request.application_runtime_root)
            .map_err(|error| format!("open private application runtime: {error}"))?;

    let endpoint = ProjectionEndpointBinding::enroll_graph(
        &graph,
        request.identities.endpoint_id,
        request.identities.device_id,
    )
    .map_err(|error| format!("identify graph projection endpoint: {error}"))?;
    let receipts = match existing_binding.as_ref() {
        Some(binding) => ProjectionReceiptStore::open_existing_for_endpoint(
            &request.receipt_root,
            binding.workspace_id(),
            endpoint,
            binding.receipt_store_id(),
        )
        .map_err(|error| format!("open existing private projection receipts: {error}"))?,
        None => open_reconstructible_activation_receipts(&request, endpoint)?,
    };

    // Capture precedes every graph-local sparse archive write. The capture is
    // read-only and revalidated internally before bootstrap authoring.
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::SourceCapture,
    });
    let capture = graph
        .capture_inactive_bootstrap_sources(&request.capture_root)
        .map_err(display)?;
    let source_inventory_digest =
        ContentDigest::from_bytes(*capture.inventory_description().sha256());
    let graph_resource_id = graph.canonical_resource_id().map_err(display)?;
    let graph_text_scope_binding = graph.graph_text_scope_binding().map_err(display)?;
    let reservation = if existing_binding.is_none() {
        Some(
            begin_or_resume_local_activation_reservation(
                &enrollment,
                LocalActivationReservationBindingV1::new(
                    local_activation_identity(&request, graph_resource_id),
                    receipts.store_id(),
                    graph_text_scope_binding,
                    source_inventory_digest,
                ),
            )
            .map_err(|error| format!("publish pre-enrollment reservation: {error}"))?,
        )
    } else {
        None
    };
    activation_cut("before_archive_creation")?;

    prepare_object_store_parent_nofollow(&request.archive_root)
        .map_err(|error| format!("prepare private archive root: {error}"))?;
    let archive = ObjectStore::open(&request.archive_root, request.identities.workspace_id)
        .map_err(|error| format!("open private bootstrap archive: {error}"))?;
    let binding = match existing_binding {
        Some(binding) => {
            archive
                .validate_enrolled_archive_resource_id(binding.archive_resource_id())
                .map_err(display)?;
            binding
        }
        None => {
            let archive_resource_id = archive
                .provision_or_resume_local_activation_archive_resource_id(
                    reservation
                        .as_ref()
                        .expect("absent enrollment must have an activation reservation")
                        .archive_instance_id(),
                )
                .map_err(display)?;
            EnrollmentBindingV1::new(
                request.identities.workspace_id,
                request.identities.lineage_digest,
                request.identities.catalog_document_id,
                request.identities.endpoint_id,
                request.identities.device_id,
                graph_resource_id,
                receipts.store_id(),
                archive_resource_id,
                graph_text_scope_binding,
            )
            .map_err(display)?
        }
    };
    if !identities_match_binding(&request.identities, &binding) {
        return Err("explicit activation identities do not match the enrollment binding".into());
    }
    drop(archive);
    activation_cut("after_archive_claim_before_enrollment_head")?;

    let preparation_id = PreparationId::from_uuid(request.identities.preparation_id);
    begin_or_resume_shadow_import(
        &enrollment,
        binding.clone(),
        preparation_id,
        source_inventory_digest,
    )
    .map_err(|error| format!("create reconstructible initial enrollment: {error}"))?;
    activation_cut("after_shadow_import")?;

    let authoring_store =
        ObjectStore::open(&request.archive_root, binding.workspace_id()).map_err(display)?;
    let authoring_capability = authoring_store
        .bootstrap_authoring_capability()
        .map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::BootstrapImportPreparation,
    });
    let mut prepared = prepare_inactive_bootstrap_import_with_progress(
        &graph,
        capture,
        binding.workspace_id(),
        binding.lineage_digest(),
        binding.catalog_document_id(),
        ReferenceCatalogPolicyV1::default(),
        &authoring_capability,
        &request.preparation_root,
        |detail| progress(detail.into()),
    )
    .map_err(display)?;
    drop(authoring_capability);
    drop(authoring_store);

    let storage_binding = ProjectionStorageBinding {
        endpoint,
        receipt_store_id: receipts.store_id(),
    };
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::ImmutablePublicationInstall,
    });
    let verified = publish_install_verify_inactive_bootstrap(
        &prepared,
        ObjectStore::open(&request.archive_root, binding.workspace_id()).map_err(display)?,
        storage_binding,
    )
    .map_err(display)?;
    let accepted_authority = retain_inactive_bootstrap_accepted_authority(
        &prepared,
        &verified,
        ObjectStore::open(&request.archive_root, binding.workspace_id()).map_err(display)?,
    )
    .map_err(display)?;

    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::BackupProof,
    });
    let backup_root =
        MigrationBackupRoot::open(&request.migration_backup_root, &request.graph_root)
            .map_err(display)?;
    let source_backup =
        verify_migration_source_backup(&backup_root, &prepared, &verified).map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::SqliteOpenBuild,
    });
    // The uninterrupted same-process path consumes the one-shot terminal
    // construction capability here. Taking it also means a later resumed or
    // restarted activation cannot see it, so that run rebuilds from the archive.
    let terminal_construction = prepared.take_terminal_construction_material();
    let inactive = InactiveBootstrapRuntimeSession::open(
        &request.archive_root,
        binding.workspace_id(),
        &request.database_path,
        &application_runtime_root,
        &accepted_authority,
        terminal_construction,
    )
    .map_err(display)?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::ShadowReconstructionByteVerification,
    });
    let shadow = verify_inactive_bootstrap_shadow_projection(
        &graph,
        &backup_root,
        &prepared,
        &verified,
        &source_backup,
        &accepted_authority,
        inactive.sqlite_proof(),
    )
    .map_err(display)?;
    #[cfg(test)]
    LAST_ACTIVATION_CONSTRUCTION_INSTRUMENTATION.with(|slot| {
        *slot.borrow_mut() = Some(ActivationConstructionInstrumentation {
            preparation: prepared.instrumentation().clone(),
            publication: verified.instrumentation().clone(),
            backup: source_backup.instrumentation().clone(),
            sqlite: inactive.sqlite_proof().bootstrap_rebuild(),
            shadow: shadow.instrumentation().clone(),
        });
    });
    let proofs = VerifiedLocalProofSet {
        graph: &graph,
        roots: &backup_root,
        prepared: &prepared,
        verified_publication: &verified,
        source_backup: &source_backup,
        accepted_authority: &accepted_authority,
        sqlite: inactive.projection(),
        sqlite_projection: inactive.sqlite_proof(),
        shadow_projection: &shadow,
    };
    let verified_local = compose_verified_local_retaining_validation(
        &enrollment,
        binding.clone(),
        preparation_id,
        &proofs,
    )
    .map_err(display)?;
    activation_cut("after_verified_local")?;
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::PromotionReceiptConfirmation,
    });
    let local_runtime = LocalActiveRuntime {
        engine: accepted_authority.accepted_engine(),
        projection: inactive.projection(),
    };
    let authority = activate_verified_local_with_retained_validation(
        &enrollment,
        verified_local,
        request.identities.session_id,
        &proofs,
        &local_runtime,
    )
    .map_err(display)?;
    let sealed =
        seal_local_runtime_promotion(&authority, &proofs, &local_runtime).map_err(display)?;
    drop(local_runtime);
    drop(proofs);

    let promoted_open = PromotedRuntimeOpen {
        graph: &graph,
        receipts: &receipts,
        archive_root: &request.archive_root,
        database_path: &request.database_path,
        application_runtime_root: &application_runtime_root,
        graph_root: &request.graph_root,
        migration_backup_root: &request.migration_backup_root,
    };
    let promoted = inactive
        .promote(sealed, &authority, &promoted_open)
        .map_err(|refusal| {
            let (_returned_lease, error) = refusal.into_parts();
            error.to_string()
        })?;

    // The actor receives this exact baseline and the retained promoted runtime
    // below. Opening it here makes reconciliation a proven prerequisite while
    // avoiding a second database, archive, engine, or receipt-store open in
    // the uninterrupted activation transaction.
    progress(SyncLocalActivationProgress::Phase {
        phase: SyncLocalActivationPhase::ReconciliationBaselineActorOpen,
    });
    let baseline =
        open_reconciliation_baseline_with_runtime(&application_runtime_root, &graph, &binding)?;
    let promotion_session_id = promoted.promotion_session_id();
    let promoted_state_digest = promoted.promoted_state_digest().map_err(display)?;
    if authority.binding() != &binding
        || authority.session_id() != request.identities.session_id
        || promotion_session_id != request.identities.session_id
    {
        return Err(
            "same-process activation handoff binding changed after LocalActive proof".into(),
        );
    }
    Ok(SameProcessActivationHandoff {
        graph,
        receipts,
        authority,
        runtime: promoted,
        baseline,
        enrollment_root: enrollment,
        binding,
        session_id: request.identities.session_id,
        promotion_session_id,
        promoted_state_digest,
    })
}

fn open_reconstructible_activation_receipts(
    request: &SyncLocalActivationRequest,
    endpoint: ProjectionEndpointBinding,
) -> Result<ProjectionReceiptStore, String> {
    let first = ProjectionReceiptStore::open_for_endpoint(
        &request.receipt_root,
        request.identities.workspace_id,
        endpoint,
    );
    match first {
        Ok(receipts) => Ok(receipts),
        Err(first_error) => {
            #[cfg(target_os = "android")]
            {
                // No enrollment binding exists yet, so Markdown/Org is still
                // the sole authority and this receipt tree cannot contain a
                // promoted mutation. Older Android candidates may have left a
                // partially initialized tree whose directory handles or modes
                // the current app UID cannot reuse. Preserve one diagnostic
                // copy, then prove that ordinary creation can start cleanly.
                archive_pre_promotion_receipts(&request.receipt_root).map_err(|error| {
                    format!(
                        "archive reconstructible pre-promotion receipt state failed: {error}; initial receipt setup failure: {first_error}"
                    )
                })?;
                return ProjectionReceiptStore::open_for_endpoint(
                    &request.receipt_root,
                    request.identities.workspace_id,
                    endpoint,
                )
                .map_err(|retry_error| {
                    format!(
                        "clean Android receipt rebuild failed: {retry_error}; initial receipt setup failure: {first_error}"
                    )
                });
            }

            #[cfg(not(target_os = "android"))]
            Err(format!("create private projection receipts: {first_error}"))
        }
    }
}

#[cfg(any(test, target_os = "android"))]
fn archive_pre_promotion_receipts(receipt_root: &Path) -> Result<(), String> {
    let metadata = match fs::symlink_metadata(receipt_root) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => {
            return Err(format!("inspect {}: {error}", receipt_root.display()));
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!(
            "{} is not a real private directory",
            receipt_root.display()
        ));
    }
    let name = receipt_root
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| "private receipt root has no UTF-8 filename".to_owned())?;
    // Never traverse or remove a prior failed tree here. The whole reason for
    // taking this path is that an older Android build may have created a
    // receipt tree whose descendants this app can no longer open. Reusing one
    // fixed diagnostic name made that inaccessible residue a permanent gate:
    // every retry failed while deleting the *previous* diagnostic before the
    // current reconstructible tree could be moved aside and rebuilt.
    let archived = receipt_root.with_file_name(format!(
        "{name}.pre-promotion-failed.{}",
        Uuid::new_v4().simple()
    ));
    fs::rename(receipt_root, &archived).map_err(|error| {
        format!(
            "move {} to {}: {error}",
            receipt_root.display(),
            archived.display()
        )
    })
}

fn activation_open_runtime(request: SyncLocalActivationRequest) -> SyncLocalActivationResult {
    let session_id = request.identities.session_id;
    let opened = SyncRuntimeHandle::open_with_session(
        SyncRuntimeOpenRequest {
            profile: SyncStorageProfile::ExperimentalLocal,
            graph_root: request.graph_root,
            enrollment_root: request.enrollment_root,
            archive_root: request.archive_root,
            receipt_root: request.receipt_root,
            database_path: request.database_path,
            application_runtime_root: request.application_runtime_root,
            migration_backup_root: request.migration_backup_root,
            provider_root: request.provider_root,
            provider_journal_root: request.provider_journal_root,
        },
        session_id,
        |_| {},
    );
    match opened {
        SyncRuntimeOpenResult {
            status: SyncRuntimeOpenStatus::Active,
            handle: Some(handle),
        } => SyncLocalActivationResult {
            status: SyncLocalActivationStatus::Active,
            handle: Some(handle),
        },
        SyncRuntimeOpenResult { status, .. } => activation_retryable(
            SyncLocalActivationStage::LocalActive,
            format!("LocalActive runtime reopen refused after proof: {status:?}"),
        ),
    }
}

fn activation_open_same_process_runtime(
    request: SyncLocalActivationRequest,
    handoff: SameProcessActivationHandoff,
) -> SyncLocalActivationResult {
    let opened = SyncRuntimeHandle::open_from_same_process_activation(
        SyncRuntimeOpenRequest {
            profile: SyncStorageProfile::ExperimentalLocal,
            graph_root: request.graph_root,
            enrollment_root: request.enrollment_root,
            archive_root: request.archive_root,
            receipt_root: request.receipt_root,
            database_path: request.database_path,
            application_runtime_root: request.application_runtime_root,
            migration_backup_root: request.migration_backup_root,
            provider_root: request.provider_root,
            provider_journal_root: request.provider_journal_root,
        },
        handoff,
    );
    match opened {
        SyncRuntimeOpenResult {
            status: SyncRuntimeOpenStatus::Active,
            handle: Some(handle),
        } => SyncLocalActivationResult {
            status: SyncLocalActivationStatus::Active,
            handle: Some(handle),
        },
        SyncRuntimeOpenResult { status, .. } => activation_retryable(
            SyncLocalActivationStage::LocalActive,
            format!("same-process LocalActive handoff refused after proof: {status:?}"),
        ),
    }
}

fn activation_failure_after(
    request: &SyncLocalActivationRequest,
    graph_resource_id: crate::oplog::CanonicalGraphResourceId,
    fallback_stage: SyncLocalActivationStage,
    detail: String,
) -> SyncLocalActivationResult {
    let reservation = match inspect_local_activation_reservation_at(&request.enrollment_root) {
        Ok(reservation) => reservation,
        Err(error) => return activation_enrollment_failure(fallback_stage, error),
    };
    let matching_reservation = reservation.as_ref().is_some_and(|reservation| {
        reservation.identity() == &local_activation_identity(request, graph_resource_id)
    });
    match discover_startup(&DiscoveryRequest {
        profile: StartupStorageProfile::ExperimentalSparse,
        graph_resource_id,
        runtime_root: &request.enrollment_root,
        archive_root: &request.archive_root,
    }) {
        DiscoveryClassification::Blocked(advisory) => activation_blocked(advisory.reason_code),
        DiscoveryClassification::ExistingNonActive(advisory) => activation_retryable(
            match advisory.stage {
                NonActiveStage::ShadowImport => SyncLocalActivationStage::ShadowImport,
                NonActiveStage::VerifiedLocal => SyncLocalActivationStage::VerifiedLocal,
            },
            detail,
        ),
        DiscoveryClassification::ExistingLocalActive(_) => {
            activation_retryable(SyncLocalActivationStage::LocalActive, detail)
        }
        DiscoveryClassification::Retryable(_, retry_detail) => activation_retryable(
            fallback_stage,
            retain_activation_failure_detail(detail, retry_detail),
        ),
        DiscoveryClassification::UnsupportedOrIncompatible(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::UnsupportedOrIncompatible {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::CorruptOrUnreadable(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::CorruptOrUnreadable {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::AmbiguousOrForeignResidue(
            AmbiguousEvidence::ArchiveResidue,
            _,
        ) if matching_reservation => activation_retryable(fallback_stage, detail),
        DiscoveryClassification::AmbiguousOrForeignResidue(evidence, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::AmbiguousOrForeignResidue {
                    evidence: map_ambiguous_evidence(evidence),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::Absent | DiscoveryClassification::LegacyDefault => {
            activation_retryable(fallback_stage, detail)
        }
    }
}

fn retain_activation_failure_detail(detail: String, retry_detail: String) -> String {
    format!("{detail}; storage rediscovery: {retry_detail}")
}

fn activation_retryable(
    durable_stage: SyncLocalActivationStage,
    detail: String,
) -> SyncLocalActivationResult {
    SyncLocalActivationResult {
        status: SyncLocalActivationStatus::Retryable {
            durable_stage,
            detail,
        },
        handle: None,
    }
}

fn activation_enrollment_failure(
    durable_stage: SyncLocalActivationStage,
    error: EnrollmentError,
) -> SyncLocalActivationResult {
    match classify_enrollment_error(error) {
        DiscoveryClassification::Retryable(_, detail) => {
            activation_retryable(durable_stage, detail)
        }
        DiscoveryClassification::UnsupportedOrIncompatible(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::UnsupportedOrIncompatible {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::CorruptOrUnreadable(component, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::CorruptOrUnreadable {
                    component: map_component(component),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::AmbiguousOrForeignResidue(evidence, scenario) => {
            SyncLocalActivationResult {
                status: SyncLocalActivationStatus::AmbiguousOrForeignResidue {
                    evidence: map_ambiguous_evidence(evidence),
                    scenario,
                },
                handle: None,
            }
        }
        DiscoveryClassification::LegacyDefault
        | DiscoveryClassification::Absent
        | DiscoveryClassification::ExistingLocalActive(_)
        | DiscoveryClassification::ExistingNonActive(_)
        | DiscoveryClassification::Blocked(_) => {
            unreachable!("an enrollment error classifier returned a non-error state")
        }
    }
}

fn activation_blocked(reason_code: impl Into<String>) -> SyncLocalActivationResult {
    SyncLocalActivationResult {
        status: SyncLocalActivationStatus::Blocked {
            reason_code: reason_code.into(),
        },
        handle: None,
    }
}

fn identities_match_binding(
    identities: &SyncLocalActivationIdentities,
    binding: &EnrollmentBindingV1,
) -> bool {
    identities.workspace_id == binding.workspace_id()
        && identities.lineage_digest == binding.lineage_digest()
        && identities.catalog_document_id == binding.catalog_document_id()
        && identities.endpoint_id == binding.endpoint_id()
        && identities.device_id == binding.device_id()
}

fn local_activation_identity(
    request: &SyncLocalActivationRequest,
    graph_resource_id: crate::oplog::CanonicalGraphResourceId,
) -> LocalActivationIdentityV1 {
    LocalActivationIdentityV1::new(
        request.identities.workspace_id,
        request.identities.lineage_digest,
        request.identities.catalog_document_id,
        request.identities.endpoint_id,
        request.identities.device_id,
        graph_resource_id,
        PreparationId::from_uuid(request.identities.preparation_id),
        request.identities.session_id,
    )
}

fn ensure_reconciliation_baseline(
    request: &SyncLocalActivationRequest,
    graph: &Graph,
    binding: &EnrollmentBindingV1,
) -> Result<(), String> {
    let runtime = ApplicationRuntimeRoot::open_explicit_private(&request.application_runtime_root)
        .map_err(display)?;
    ensure_reconciliation_baseline_with_runtime(&runtime, graph, binding)
}

fn ensure_reconciliation_baseline_with_runtime(
    runtime: &ApplicationRuntimeRoot,
    graph: &Graph,
    binding: &EnrollmentBindingV1,
) -> Result<(), String> {
    drop(open_reconciliation_baseline_with_runtime(
        runtime, graph, binding,
    )?);
    Ok(())
}

fn open_reconciliation_baseline_with_runtime(
    runtime: &ApplicationRuntimeRoot,
    graph: &Graph,
    binding: &EnrollmentBindingV1,
) -> Result<ReconciliationBaseline, String> {
    let trusted = TrustedPrivateApplicationRuntimeRoot::from_application_runtime_root(runtime);
    let baseline_binding = ReconciliationBaselineBinding::new(
        binding.workspace_id(),
        binding.endpoint_id(),
        graph.canonical_resource_id().map_err(display)?,
        graph.graph_text_scope_binding().map_err(display)?,
    )
    .map_err(display)?;
    ReconciliationBaseline::open_or_rebuild(&trusted, baseline_binding).map_err(display)
}

struct ApplicationBlockRef<'a> {
    block: &'a BlockDto,
    parent: Option<usize>,
    depth: usize,
}

fn flatten_application_blocks(blocks: &[BlockDto]) -> Vec<ApplicationBlockRef<'_>> {
    let mut output = Vec::new();
    let mut stack = blocks
        .iter()
        .rev()
        .map(|block| (block, None, 1_usize))
        .collect::<Vec<_>>();
    while let Some((block, parent, depth)) = stack.pop() {
        let index = output.len();
        output.push(ApplicationBlockRef {
            block,
            parent,
            depth,
        });
        stack.extend(
            block
                .children
                .iter()
                .rev()
                .map(|child| (child, Some(index), depth.saturating_add(1))),
        );
    }
    output
}

fn flatten_application_blocks_bounded(
    blocks: &[BlockDto],
    block_limit: usize,
) -> Result<Vec<ApplicationBlockRef<'_>>, SyncApplicationPageRequestError> {
    if blocks.len() > block_limit {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                blocks: block_limit + 1,
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    let mut output = Vec::with_capacity(blocks.len());
    let mut stack = blocks
        .iter()
        .rev()
        .map(|block| (block, None, 1_usize))
        .collect::<Vec<_>>();
    let mut max_depth = 0_usize;
    while let Some((block, parent, depth)) = stack.pop() {
        max_depth = max_depth.max(depth);
        if output.len() == block_limit || depth > MAX_SYNC_EDITOR_DEPTH {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: output.len().saturating_add(1),
                    depth: max_depth,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        let retained_after_current = output.len().saturating_add(stack.len()).saturating_add(1);
        if block.children.len() > block_limit.saturating_sub(retained_after_current) {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: block_limit + 1,
                    depth: max_depth,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        let index = output.len();
        output.push(ApplicationBlockRef {
            block,
            parent,
            depth,
        });
        stack.extend(
            block
                .children
                .iter()
                .rev()
                .map(|child| (child, Some(index), depth.saturating_add(1))),
        );
    }
    Ok(output)
}

fn validate_application_load_request(
    request: &SyncApplicationPageLoadRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    match &request.page {
        SyncApplicationPageSelector::Logical { name, .. } => {
            if name.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        text_bytes: MAX_SYNC_EDITOR_REQUEST_BYTES + 1,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidName,
                )
            })?;
        }
        SyncApplicationPageSelector::ExactPath { path } => {
            if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        text_bytes: MAX_SYNC_EDITOR_REQUEST_BYTES.min(path.len()),
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            ManagedPath::parse(path.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidPath,
                )
            })?;
        }
    }
    Ok(())
}

fn validate_application_navigation_request(
    request: &SyncApplicationNavigationRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if let SyncApplicationNavigationRequest::BacklinkFilterContext { name, targets } = request {
        let text_bytes = name
            .len()
            .checked_add(
                targets
                    .iter()
                    .map(|target| target.page.len().saturating_add(target.block_id.len()))
                    .try_fold(0_usize, usize::checked_add)
                    .unwrap_or(usize::MAX),
            )
            .unwrap_or(usize::MAX);
        if targets.len() > MAX_SYNC_APPLICATION_RESULT_ROWS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: targets.len(),
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::PropertyFacets {
        hidden_properties,
        max_items,
        max_bytes,
        ..
    } = request
    {
        let text_bytes = hidden_properties
            .iter()
            .map(String::len)
            .try_fold(0_usize, usize::checked_add)
            .unwrap_or(usize::MAX);
        if hidden_properties.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
            || *max_items == 0
            || *max_items > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: hidden_properties.len().max(*max_items),
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::ExportQuerySubtrees {
        specs,
        max_queries,
        max_roots,
        max_nodes,
        max_bytes,
    } = request
    {
        let text_bytes = specs
            .iter()
            .map(|spec| spec.key.len().saturating_add(spec.query.len()))
            .try_fold(0_usize, usize::checked_add)
            .unwrap_or(usize::MAX);
        if specs.len() > MAX_SYNC_APPLICATION_RESULT_ROWS
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
            || *max_queries == 0
            || *max_queries > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_roots == 0
            || *max_roots > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_nodes == 0
            || *max_nodes > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: specs.len().max(*max_nodes),
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::AdvancedQuery {
        query,
        current_page,
        max_rows,
        max_bytes,
    } = request
    {
        let text_bytes = query
            .len()
            .saturating_add(current_page.as_ref().map_or(0, String::len));
        if !crate::query::query_source_within_limit(query)
            || !crate::query::query_nesting_within_limit(query)
            || *max_rows == 0
            || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
            || *max_bytes == 0
            || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: *max_rows,
                    text_bytes: text_bytes.max(*max_bytes),
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::GraphSearch {
        source,
        page_limit,
        block_limit,
        lane,
        scope,
        ..
    } = request
    {
        let rows = page_limit.saturating_add(*block_limit);
        let text_bytes = source
            .len()
            .saturating_add(lane.as_ref().map_or(0, String::len))
            .saturating_add(scope.as_ref().map_or(0, |scope| {
                scope
                    .name
                    .len()
                    .saturating_add(scope.path.as_ref().map_or(0, String::len))
            }));
        if rows > MAX_SYNC_APPLICATION_RESULT_ROWS || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: rows,
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    if let SyncApplicationNavigationRequest::BlockSearch { query, limit, lane } = request {
        let text_bytes = query
            .len()
            .saturating_add(lane.as_ref().map_or(0, String::len));
        if *limit > MAX_SYNC_APPLICATION_RESULT_ROWS || text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    blocks: *limit,
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    let (names, query, limit) = match request {
        SyncApplicationNavigationRequest::ReferencedPageNames { .. }
        | SyncApplicationNavigationRequest::PageAliases
        | SyncApplicationNavigationRequest::ListTemplates
        | SyncApplicationNavigationRequest::OrphanAssets => (&[][..], None, None),
        SyncApplicationNavigationRequest::PageIcons { names }
        | SyncApplicationNavigationRequest::ExistingPageNames { names } => {
            (names.as_slice(), None, None)
        }
        SyncApplicationNavigationRequest::QuickSwitch { query, limit } => {
            (&[][..], Some(query.as_str()), Some(*limit))
        }
        SyncApplicationNavigationRequest::ResolveBlocks { uuids } => {
            (uuids.as_slice(), None, Some(uuids.len()))
        }
        SyncApplicationNavigationRequest::PreviewBlock {
            uuid,
            max_nodes,
            max_bytes,
        } => {
            if *max_nodes == 0
                || *max_nodes > MAX_SYNC_APPLICATION_PAGE_BLOCKS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_nodes,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(uuid.as_str()), None)
        }
        SyncApplicationNavigationRequest::BlockReferenceCounts => (&[][..], None, None),
        SyncApplicationNavigationRequest::BlockReferrers {
            uuid,
            max_rows,
            max_bytes,
        } => {
            if *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(uuid.as_str()), None)
        }
        SyncApplicationNavigationRequest::Backlinks {
            name,
            max_rows,
            max_bytes,
        }
        | SyncApplicationNavigationRequest::UnlinkedReferences {
            name,
            max_rows,
            max_bytes,
        } => {
            if name.len() > MAX_MATERIALIZATION_QUERY_BYTES
                || *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: *max_bytes,
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(name.as_str()), None)
        }
        SyncApplicationNavigationRequest::SimpleQuery {
            query,
            max_rows,
            max_bytes,
        } => {
            if !crate::query::query_source_within_limit(query)
                || !crate::query::query_nesting_within_limit(query)
                || *max_rows == 0
                || *max_rows > MAX_SYNC_APPLICATION_RESULT_ROWS
                || *max_bytes == 0
                || *max_bytes > MAX_SYNC_APPLICATION_RESULT_BYTES
            {
                return Err(SyncApplicationPageRequestError::RequestTooLarge(
                    SyncEditorRequestSize {
                        blocks: *max_rows,
                        text_bytes: query.len().max(*max_bytes),
                        ..SyncEditorRequestSize::default()
                    },
                ));
            }
            (&[][..], Some(query.as_str()), None)
        }
        SyncApplicationNavigationRequest::BacklinkFilterContext { .. } => unreachable!(),
        SyncApplicationNavigationRequest::PropertyFacets { .. } => unreachable!(),
        SyncApplicationNavigationRequest::GraphSearch { .. }
        | SyncApplicationNavigationRequest::BlockSearch { .. }
        | SyncApplicationNavigationRequest::AdvancedQuery { .. }
        | SyncApplicationNavigationRequest::ExportQuerySubtrees { .. } => unreachable!(),
    };
    if names.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                blocks: names.len(),
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    let text_bytes = names
        .iter()
        .map(String::len)
        .chain(query.into_iter().map(str::len))
        .try_fold(0_usize, usize::checked_add)
        .unwrap_or(usize::MAX);
    if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
        || limit.is_some_and(|limit| limit > MAX_MATERIALIZATION_QUERY_ROWS)
    {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                text_bytes,
                blocks: limit.unwrap_or_default(),
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    Ok(())
}

fn validate_application_save_request(
    request: &SyncApplicationPageSaveRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    let mut size = validate_application_page_bounds(&request.page)?;
    match &request.target {
        SyncApplicationPageSaveTarget::Existing { path, revision }
        | SyncApplicationPageSaveTarget::ResolveConflict {
            path,
            observed_revision: revision,
        } => {
            if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES {
                editor_charge_text(&mut size, path.len());
                return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
            }
            if ManagedPath::parse(path.clone()).is_err() {
                return Err(SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidPath,
                ));
            }
            editor_charge_text(&mut size, path.len());
            editor_charge_text(&mut size, revision.len());
        }
        SyncApplicationPageSaveTarget::New { name, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncApplicationPageRequestError::InvalidRequest(
                    SyncApplicationPageInvalidRequest::InvalidName,
                )
            })?;
            editor_charge_text(&mut size, name.len());
        }
    }
    if application_page_request_too_large(size) {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn validate_application_move_request(
    request: &SyncApplicationMoveSubtreesRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if Uuid::parse_str(&request.episode_id).is_err() || request.roots.is_empty() {
        return Err(SyncApplicationPageRequestError::InvalidRequest(
            SyncApplicationPageInvalidRequest::MalformedPage,
        ));
    }
    for path in [&request.source_path, &request.destination_path] {
        if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES || ManagedPath::parse(path.clone()).is_err() {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
    }
    let mut size = SyncEditorRequestSize {
        blocks: request.roots.len().min(MAX_SYNC_EDITOR_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    for value in [
        request.episode_id.as_str(),
        request.source_path.as_str(),
        request.source_revision.as_str(),
        request.destination_path.as_str(),
        request.destination_revision.as_str(),
    ] {
        editor_charge_text(&mut size, value.len());
    }
    for root in request.roots.iter().take(MAX_SYNC_EDITOR_BLOCKS + 1) {
        editor_charge_text(&mut size, root.identity.len());
        if let Some(rewrite) = &root.raw_rewrite {
            editor_charge_text(&mut size, rewrite.expected_raw.len());
            editor_charge_text(&mut size, rewrite.desired_raw.len());
        }
    }
    if let SyncApplicationMovePlacement::Child {
        parent_identity, ..
    } = &request.placement
    {
        editor_charge_text(&mut size, parent_identity.len());
    }
    if request.roots.len() > MAX_SYNC_EDITOR_BLOCKS || application_page_request_too_large(size) {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn application_move_request_digest(
    request: &SyncApplicationMoveSubtreesRequest,
) -> Result<ContentDigest, SyncApplicationPageRequestError> {
    // Admission is binding-generation evidence, not move semantics. Excluding
    // it lets an exact already-authored episode resolve after native limits
    // change while every identity, revision, placement, and rewrite remains
    // byte-for-byte bound.
    let bytes = postcard::to_allocvec(&(
        b"tine/application-move-request/v2".as_slice(),
        request.episode_id.as_str(),
        request.source_path.as_str(),
        request.source_revision.as_str(),
        request.destination_path.as_str(),
        request.destination_revision.as_str(),
        &request.roots,
        &request.placement,
    ))
    .map_err(|_| SyncApplicationPageRequestError::ActorRefusedAt("move_episode_digest"))?;
    Ok(ContentDigest::of(&bytes))
}

fn validate_application_graph_mutation_request(
    request: &SyncApplicationGraphMutationRequest,
) -> Result<(), SyncApplicationPageRequestError> {
    if let SyncApplicationGraphMutationRequest::TrashJournalFile { name } = request {
        if name.is_empty()
            || name.contains('/')
            || name.contains('\\')
            || name.len() > MAX_LOCAL_MUTATION_PATH_BYTES
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
        return Ok(());
    }
    if let SyncApplicationGraphMutationRequest::ResolveSyncConflict {
        winner_path,
        conflict_path,
        decisions,
        base_revision,
        conflict_revision,
        pre_choice,
    } = request
    {
        if decisions.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS
            || ManagedPath::parse(winner_path.clone()).is_err()
            || ManagedPath::parse(conflict_path.clone()).is_err()
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
        let text_bytes = [
            winner_path.len(),
            conflict_path.len(),
            base_revision.len(),
            conflict_revision.len(),
            pre_choice.len(),
        ]
        .into_iter()
        .chain(
            decisions
                .iter()
                .flat_map(|(key, value)| [key.len(), value.len()]),
        )
        .try_fold(0_usize, usize::checked_add)
        .unwrap_or(usize::MAX);
        if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(
                SyncEditorRequestSize {
                    text_bytes,
                    ..SyncEditorRequestSize::default()
                },
            ));
        }
        return Ok(());
    }
    let (names, paths): (Vec<&str>, Vec<&str>) = match request {
        SyncApplicationGraphMutationRequest::RenamePage {
            old,
            new,
            expected_path,
        } => (
            vec![old.as_str(), new.as_str()],
            expected_path.as_deref().into_iter().collect(),
        ),
        SyncApplicationGraphMutationRequest::DeletePage {
            name,
            expected_path,
            ..
        } => (
            vec![name.as_str()],
            expected_path.as_deref().into_iter().collect(),
        ),
        SyncApplicationGraphMutationRequest::MergePages {
            source_path,
            destination_path,
            rename_from,
            rename_to,
        } => (
            rename_from
                .iter()
                .chain(rename_to.iter())
                .map(String::as_str)
                .collect(),
            vec![source_path.as_str(), destination_path.as_str()],
        ),
        SyncApplicationGraphMutationRequest::RenameFileToPage { path, new_name } => {
            (vec![new_name.as_str()], vec![path.as_str()])
        }
        SyncApplicationGraphMutationRequest::TrashJournalFile { .. } => unreachable!(),
        SyncApplicationGraphMutationRequest::ResolveSyncConflict { .. } => unreachable!(),
    };
    let text_bytes = names
        .iter()
        .chain(paths.iter())
        .try_fold(0_usize, |total, value| total.checked_add(value.len()))
        .unwrap_or(usize::MAX);
    if text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(
            SyncEditorRequestSize {
                text_bytes,
                ..SyncEditorRequestSize::default()
            },
        ));
    }
    for name in names {
        LogicalPageName::parse(name.to_owned()).map_err(|_| {
            SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidName,
            )
        })?;
    }
    for path in paths {
        if path.len() > MAX_LOCAL_MUTATION_PATH_BYTES
            || ManagedPath::parse(path.to_owned()).is_err()
        {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::InvalidPath,
            ));
        }
    }
    Ok(())
}

fn validate_application_page_bounds(
    page: &PageDto,
) -> Result<SyncEditorRequestSize, SyncApplicationPageRequestError> {
    let flattened =
        flatten_application_blocks_bounded(&page.blocks, MAX_SYNC_APPLICATION_PAGE_BLOCKS)?;
    let mut size = SyncEditorRequestSize {
        blocks: flattened.len().min(MAX_SYNC_APPLICATION_PAGE_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    for value in [
        Some(page.name.as_str()),
        Some(page.title.as_str()),
        page.pre_block.as_deref(),
        page.rev.as_deref(),
        Some(page.path.as_str()),
    ]
    .into_iter()
    .flatten()
    {
        editor_charge_text(&mut size, value.len());
    }
    if flattened.len() > MAX_SYNC_APPLICATION_PAGE_BLOCKS {
        return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
    }
    let mut identities = HashSet::with_capacity(flattened.len());
    for item in flattened {
        size.depth = size.depth.max(item.depth);
        size.temporary_key_bytes = bounded_charge(
            size.temporary_key_bytes,
            item.block.id.len(),
            MAX_SYNC_EDITOR_REQUEST_BYTES,
        );
        if !identities.insert(item.block.id.as_str()) {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::DuplicateBlockId,
            ));
        }
        for value in [
            Some(item.block.id.as_str()),
            Some(item.block.raw.as_str()),
            item.block.marker.as_deref(),
            item.block.priority.as_deref(),
            item.block.scheduled.as_deref(),
            item.block.deadline.as_deref(),
        ]
        .into_iter()
        .flatten()
        {
            editor_charge_text(&mut size, value.len());
        }
        for value in &item.block.breadcrumb {
            editor_charge_text(&mut size, value.len());
        }
        for value in &item.block.tags {
            editor_charge_text(&mut size, value.len());
        }
        for (name, value) in &item.block.properties {
            editor_charge_text(&mut size, name.len());
            editor_charge_text(&mut size, value.len());
        }
        if item.block.page_property {
            return Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::MalformedPage,
            ));
        }
        if application_page_request_too_large(size) {
            return Err(SyncApplicationPageRequestError::RequestTooLarge(size));
        }
    }
    Ok(size)
}

fn validate_editor_load_request(
    request: &SyncEditorLoadRequest,
) -> Result<(), SyncEditorRequestError> {
    match &request.page {
        SyncEditorPageSelector::PageId { page_id } => {
            parse_editor_page_id(page_id)?;
            if page_id.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(editor_too_large(0, 0, 0, page_id.len()));
            }
        }
        SyncEditorPageSelector::Name { name, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidName)
            })?;
            if name.len() > MAX_SYNC_EDITOR_REQUEST_BYTES {
                return Err(editor_too_large(0, 0, 0, name.len()));
            }
        }
    }
    Ok(())
}

fn validate_editor_save_request(
    request: &SyncEditorSaveRequest,
) -> Result<(), SyncEditorRequestError> {
    let mut size = SyncEditorRequestSize {
        blocks: request.blocks.len().min(MAX_SYNC_EDITOR_BLOCKS + 1),
        ..SyncEditorRequestSize::default()
    };
    match &request.target {
        SyncEditorSaveTarget::Existing { page_id, revision } => {
            parse_editor_page_id(page_id)?;
            editor_charge_text(&mut size, page_id.len());
            editor_charge_text(&mut size, revision.len());
        }
        SyncEditorSaveTarget::New { name, revision, .. } => {
            LogicalPageName::parse(name.clone()).map_err(|_| {
                SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidName)
            })?;
            editor_charge_text(&mut size, name.len());
            editor_charge_text(&mut size, revision.len());
        }
    }
    editor_charge_text(&mut size, request.preamble.as_ref().map_or(0, String::len));
    if request.blocks.len() > MAX_SYNC_EDITOR_BLOCKS {
        return Err(SyncEditorRequestError::RequestTooLarge(size));
    }

    let mut indexes = HashMap::with_capacity(request.blocks.len());
    for (index, block) in request.blocks.iter().enumerate() {
        validate_editor_key(&block.key, &mut size)?;
        if indexes.insert(block.key.clone(), index).is_some() {
            return Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::DuplicateKey,
            ));
        }
        if let Some(parent) = &block.parent {
            validate_editor_key(parent, &mut size)?;
        }
        editor_charge_text(&mut size, block.content.len());
        if editor_request_too_large(size) {
            return Err(SyncEditorRequestError::RequestTooLarge(size));
        }
    }

    let mut children = vec![Vec::new(); request.blocks.len()];
    let mut indegree = vec![0_u8; request.blocks.len()];
    for (index, block) in request.blocks.iter().enumerate() {
        let Some(parent) = &block.parent else {
            continue;
        };
        let Some(parent_index) = indexes.get(parent).copied() else {
            return Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::UnknownParent,
            ));
        };
        children[parent_index].push(index);
        indegree[index] = 1;
    }
    let mut queue = VecDeque::new();
    let mut depths = vec![0_usize; request.blocks.len()];
    for (index, degree) in indegree.iter().enumerate() {
        if *degree == 0 {
            depths[index] = 1;
            queue.push_back(index);
        }
    }
    let mut visited = 0_usize;
    while let Some(index) = queue.pop_front() {
        visited += 1;
        size.depth = size.depth.max(depths[index]);
        if size.depth > MAX_SYNC_EDITOR_DEPTH {
            return Err(SyncEditorRequestError::RequestTooLarge(size));
        }
        for child in &children[index] {
            depths[*child] = depths[index].saturating_add(1);
            indegree[*child] -= 1;
            if indegree[*child] == 0 {
                queue.push_back(*child);
            }
        }
    }
    if visited != request.blocks.len() {
        return Err(SyncEditorRequestError::InvalidRequest(
            SyncEditorInvalidRequest::CyclicOutline,
        ));
    }
    if editor_request_too_large(size) {
        return Err(SyncEditorRequestError::RequestTooLarge(size));
    }
    Ok(())
}

fn validate_editor_key(
    key: &SyncEditorBlockKey,
    size: &mut SyncEditorRequestSize,
) -> Result<(), SyncEditorRequestError> {
    match key {
        SyncEditorBlockKey::Existing(id) => {
            parse_editor_block_id(id)?;
            editor_charge_text(size, id.len());
        }
        SyncEditorBlockKey::Temporary(key) => {
            if key.is_empty() {
                return Err(SyncEditorRequestError::InvalidRequest(
                    SyncEditorInvalidRequest::EmptyTemporaryKey,
                ));
            }
            if key
                .chars()
                .any(|character| matches!(character, '\0' | '\r' | '\n'))
            {
                return Err(SyncEditorRequestError::InvalidRequest(
                    SyncEditorInvalidRequest::InvalidTemporaryKey,
                ));
            }
            size.temporary_key_bytes = bounded_charge(
                size.temporary_key_bytes,
                key.len(),
                MAX_SYNC_EDITOR_REQUEST_BYTES,
            );
            editor_charge_text(size, key.len());
            if key.len() > MAX_SYNC_EDITOR_TEMP_KEY_BYTES {
                return Err(SyncEditorRequestError::RequestTooLarge(*size));
            }
        }
    }
    Ok(())
}

fn validate_activation_paths(
    request: &SyncLocalActivationRequest,
    graph_root: &Path,
) -> Result<(), String> {
    let canonical_graph = fs::canonicalize(graph_root)
        .map_err(|error| format!("cannot canonicalize graph root for activation: {error}"))?;
    let expected_provider = canonical_graph.join(".tine-sync").join("v2").join("shared");
    if normalize_absolute(&request.provider_root)? != expected_provider {
        return Err(
            "provider_root must be exactly the graph's .tine-sync/v2/shared namespace".into(),
        );
    }

    let private_paths = [
        (&request.archive_root, "archive_root"),
        (&request.enrollment_root, "enrollment_root"),
        (&request.receipt_root, "receipt_root"),
        (
            &request.application_runtime_root,
            "application_runtime_root",
        ),
        (&request.migration_backup_root, "migration_backup_root"),
        (&request.capture_root, "capture_root"),
        (&request.preparation_root, "preparation_root"),
        (&request.provider_journal_root, "provider_journal_root"),
    ];
    for (path, label) in private_paths {
        require_private_path_outside_graph(path, label, &canonical_graph)?;
    }
    let database_parent = request
        .database_path
        .parent()
        .ok_or_else(|| "database_path has no parent directory".to_owned())?;
    require_private_path_outside_graph(database_parent, "database_path", &canonical_graph)?;
    Ok(())
}

fn prepare_activation_private_paths(request: &SyncLocalActivationRequest) -> Result<(), String> {
    for path in [
        &request.capture_root,
        &request.preparation_root,
        &request.migration_backup_root,
    ] {
        fs::create_dir_all(path)
            .map_err(|error| format!("cannot create private activation directory: {error}"))?;
        let metadata = fs::symlink_metadata(path)
            .map_err(|error| format!("cannot inspect private activation directory: {error}"))?;
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            return Err("private activation path is not a real directory".into());
        }
    }
    let database_parent = request
        .database_path
        .parent()
        .ok_or_else(|| "database_path has no parent directory".to_owned())?;
    fs::create_dir_all(database_parent)
        .map_err(|error| format!("cannot create private database parent: {error}"))?;
    Ok(())
}

fn require_private_path_outside_graph(
    path: &Path,
    label: &str,
    graph_root: &Path,
) -> Result<(), String> {
    let normalized = normalize_absolute(path)?;
    if normalized == graph_root || normalized.starts_with(graph_root) {
        return Err(format!("{label} must be outside the graph root"));
    }
    let mut existing = normalized.clone();
    loop {
        match fs::symlink_metadata(&existing) {
            Ok(_) => break,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                if !existing.pop() {
                    return Err(format!("{label} has no existing ancestor"));
                }
            }
            Err(error) => {
                return Err(format!("cannot inspect {label} ancestor: {error}"));
            }
        }
    }
    let canonical_existing = fs::canonicalize(&existing)
        .map_err(|error| format!("cannot canonicalize {label} ancestor: {error}"))?;
    if canonical_existing == graph_root || canonical_existing.starts_with(graph_root) {
        return Err(format!("{label} resolves inside the graph root"));
    }
    Ok(())
}

fn normalize_absolute(path: &Path) -> Result<PathBuf, String> {
    let input = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .map_err(|error| format!("cannot determine current directory: {error}"))?
            .join(path)
    };
    let mut normalized = PathBuf::new();
    for component in input.components() {
        match component {
            Component::Prefix(prefix) => normalized.push(prefix.as_os_str()),
            Component::RootDir => normalized.push(component.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                if !normalized.pop() {
                    return Err("activation path escapes its root".into());
                }
            }
            Component::Normal(part) => normalized.push(part),
        }
    }
    Ok(normalized)
}

fn editor_charge_text(size: &mut SyncEditorRequestSize, bytes: usize) {
    size.text_bytes = bounded_charge(size.text_bytes, bytes, MAX_SYNC_EDITOR_REQUEST_BYTES);
}

fn editor_request_too_large(size: SyncEditorRequestSize) -> bool {
    size.blocks > MAX_SYNC_EDITOR_BLOCKS
        || size.depth > MAX_SYNC_EDITOR_DEPTH
        || size.text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
}

fn application_page_request_too_large(size: SyncEditorRequestSize) -> bool {
    size.blocks > MAX_SYNC_APPLICATION_PAGE_BLOCKS
        || size.depth > MAX_SYNC_EDITOR_DEPTH
        || size.text_bytes > MAX_SYNC_EDITOR_REQUEST_BYTES
}

fn editor_too_large(
    blocks: usize,
    depth: usize,
    temporary_key_bytes: usize,
    text_bytes: usize,
) -> SyncEditorRequestError {
    SyncEditorRequestError::RequestTooLarge(SyncEditorRequestSize {
        blocks,
        depth,
        temporary_key_bytes,
        text_bytes,
    })
}

fn parse_editor_page_id(value: &str) -> Result<PageId, SyncEditorRequestError> {
    uuid::Uuid::parse_str(value)
        .map(PageId::from_uuid)
        .map_err(|_| {
            SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidExistingId)
        })
}

fn parse_editor_block_id(value: &str) -> Result<BlockId, SyncEditorRequestError> {
    uuid::Uuid::parse_str(value)
        .map(BlockId::from_uuid)
        .map_err(|_| {
            SyncEditorRequestError::InvalidRequest(SyncEditorInvalidRequest::InvalidExistingId)
        })
}

fn refused(detail: String) -> SyncRuntimeOpenResult {
    SyncRuntimeOpenResult {
        status: SyncRuntimeOpenStatus::OpenRefused { detail },
        handle: None,
    }
}

fn map_discovery(classification: DiscoveryClassification) -> SyncRuntimeOpenStatus {
    match classification {
        DiscoveryClassification::LegacyDefault => SyncRuntimeOpenStatus::LegacyDefault,
        DiscoveryClassification::Absent => SyncRuntimeOpenStatus::Absent,
        DiscoveryClassification::ExistingLocalActive(_) => SyncRuntimeOpenStatus::Active,
        DiscoveryClassification::ExistingNonActive(advisory) => {
            SyncRuntimeOpenStatus::ExistingNonActive(match advisory.stage {
                NonActiveStage::ShadowImport => SyncNonActiveStage::ShadowImport,
                NonActiveStage::VerifiedLocal => SyncNonActiveStage::VerifiedLocal,
            })
        }
        DiscoveryClassification::Blocked(advisory) => SyncRuntimeOpenStatus::Blocked {
            reason_code: advisory.reason_code,
        },
        DiscoveryClassification::Retryable(_, detail) => {
            SyncRuntimeOpenStatus::OpenRefused { detail }
        }
        DiscoveryClassification::UnsupportedOrIncompatible(component, scenario) => {
            SyncRuntimeOpenStatus::UnsupportedOrIncompatible {
                component: map_component(component),
                scenario,
            }
        }
        DiscoveryClassification::CorruptOrUnreadable(component, scenario) => {
            SyncRuntimeOpenStatus::CorruptOrUnreadable {
                component: map_component(component),
                scenario,
            }
        }
        DiscoveryClassification::AmbiguousOrForeignResidue(evidence, scenario) => {
            SyncRuntimeOpenStatus::AmbiguousOrForeignResidue {
                evidence: map_ambiguous_evidence(evidence),
                scenario,
            }
        }
    }
}

fn shared_namespace_digest(workspace_id: WorkspaceId) -> ContentDigest {
    let mut hasher = Sha256::new();
    hasher.update(b"tine/shared-provider-namespace/v1\0");
    hasher.update(workspace_id.to_string().as_bytes());
    ContentDigest::from_bytes(hasher.finalize().into())
}

fn publish_manifest_recovery(
    provider: &mut SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    manifest: &OperationBatch,
    manifest_bytes: &[u8],
) -> Result<(), SyncRuntimeRequestError> {
    let link = SharedProviderManifestRecoveryLinkV1::new(
        descriptor.workspace_id(),
        descriptor.lineage_digest(),
        descriptor
            .digest()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?,
        manifest.batch_id(),
        manifest.author_device_id(),
        ContentDigest::of(manifest_bytes),
    )
    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    provider
        .publish_manifest_recovery(&link, manifest_bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))
}

fn publish_provider_object_exact(
    provider: &mut SharedProviderTransport,
    digest: ContentDigest,
    bytes: &[u8],
) -> Result<(), SyncRuntimeRequestError> {
    if ContentDigest::of(bytes) != digest {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "local provider object bytes do not match {digest}"
        )));
    }
    // Physical visibility is not publication completion. The transport owns
    // both the authenticated retry journal and the exact-existing durability
    // proof, including directory sync and same-file identity revalidation.
    provider
        .publish_object_exact(digest, bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))
}

fn publish_complete_archive(
    store: &ObjectStore,
    provider: &mut SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    publisher_device_id: DeviceId,
) -> Result<Vec<(String, SharedProviderPublicationIntentV1)>, SyncRuntimeRequestError> {
    let manifests = store
        .committed_manifests()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    for manifest in &manifests {
        for object in manifest.required_objects() {
            let bytes = store
                .read_object_bytes(object.content_digest())
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
            publish_provider_object_exact(provider, object.content_digest(), &bytes)?;
        }
    }
    let mut intents = Vec::with_capacity(manifests.len());
    for manifest in manifests {
        let manifest_bytes = manifest
            .encode()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        publish_manifest_recovery(provider, descriptor, &manifest, &manifest_bytes)?;
        let intent = SharedProviderPublicationIntentV1::new(
            descriptor.workspace_id(),
            descriptor.lineage_digest(),
            descriptor
                .digest()
                .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?,
            publisher_device_id,
            manifest.author_device_id(),
            manifest.batch_id(),
            ContentDigest::of(&manifest_bytes),
        )
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        let path = provider
            .publish_publication_intent(&intent)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        provider
            .publish_manifest(manifest.batch_id(), &manifest_bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        intents.push((path, intent));
    }
    Ok(intents)
}

fn publish_archive_batch(
    store: &ObjectStore,
    provider: &mut SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    publisher_device_id: DeviceId,
    batch_id: BatchId,
) -> Result<(String, SharedProviderPublicationIntentV1), SyncRuntimeRequestError> {
    let manifest = match store
        .inspect_batch(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    {
        crate::oplog::BatchInspection::Ready(batch) => batch.manifest().clone(),
        crate::oplog::BatchInspection::Absent => {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "durable outbound batch {batch_id} is absent"
            )));
        }
        crate::oplog::BatchInspection::Staged { .. } => {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "durable outbound batch {batch_id} is partial"
            )));
        }
    };
    for object in manifest.required_objects() {
        let bytes = store
            .read_object_bytes(object.content_digest())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        publish_provider_object_exact(provider, object.content_digest(), &bytes)?;
    }
    let manifest_bytes = store
        .read_manifest_bytes(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    provider_recovery_publication_cut(descriptor.workspace_id(), "before_recovery")?;
    publish_manifest_recovery(provider, descriptor, &manifest, &manifest_bytes)?;
    provider_recovery_publication_cut(
        descriptor.workspace_id(),
        "after_recovery_before_canonical",
    )?;
    let intent = SharedProviderPublicationIntentV1::new(
        descriptor.workspace_id(),
        descriptor.lineage_digest(),
        descriptor
            .digest()
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?,
        publisher_device_id,
        manifest.author_device_id(),
        batch_id,
        ContentDigest::of(&manifest_bytes),
    )
    .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let path = provider
        .publish_publication_intent(&intent)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    provider
        .publish_manifest(batch_id, &manifest_bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    Ok((path, intent))
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ProviderManifestIngress {
    Ready(OperationBatch),
    Incomplete(OperationBatch),
    Absent(BatchId),
}

fn provider_manifest_id(path: &str) -> Option<BatchId> {
    path.strip_prefix("manifests/")
        .and_then(|name| name.strip_suffix(".manifest"))
        .and_then(|value| Uuid::parse_str(value).ok())
        .map(BatchId::from_uuid)
}

fn provider_manifest_recovery_link_id(path: &str) -> Option<BatchId> {
    path.strip_prefix(&format!(
        "{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/"
    ))
    .and_then(|name| name.strip_suffix(".link"))
    .and_then(|value| Uuid::parse_str(value).ok())
    .map(BatchId::from_uuid)
}

fn provider_manifest_recovery_blob_digest(path: &str) -> Option<&str> {
    let digest = path
        .strip_prefix(&format!(
            "{SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE}/"
        ))
        .and_then(|name| name.strip_suffix(".manifest"))?;
    (digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)))
    .then_some(digest)
}

fn provider_frontier_head_path(path: &str) -> bool {
    let Some(name) = path
        .strip_prefix(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE)
        .and_then(|path| path.strip_prefix('/'))
        .and_then(|name| name.strip_suffix(".head"))
    else {
        return false;
    };
    let Some((device, digest)) = name.rsplit_once('-') else {
        return false;
    };
    Uuid::parse_str(device).is_ok()
        && digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn provider_publication_intent_path(path: &str) -> bool {
    let Some(name) = path
        .strip_prefix(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE)
        .and_then(|path| path.strip_prefix('/'))
        .and_then(|name| name.strip_suffix(".intent"))
    else {
        return false;
    };
    let Some((identity, digest)) = name.rsplit_once('-') else {
        return false;
    };
    if identity.len() != 73 || identity.as_bytes().get(36) != Some(&b'-') {
        return false;
    }
    Uuid::parse_str(&identity[..36]).is_ok()
        && Uuid::parse_str(&identity[37..]).is_ok()
        && digest.len() == 64
        && digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn canonical_generated_provider_conflict(path: &str) -> Option<String> {
    let (directory, filename) = path.rsplit_once('/')?;
    let (stem, extension) = filename.rsplit_once('.')?;
    let base = sync_conflict_base(stem)?;
    let canonical = format!("{directory}/{base}.{extension}");
    match (directory, extension) {
        ("objects", "object")
            if base.len() == 64
                && base
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)) =>
        {
            Some(canonical)
        }
        ("manifests", "manifest") if Uuid::parse_str(base).is_ok() => Some(canonical),
        ("enrollment", "json") if canonical == SHARED_ENROLLMENT_DESCRIPTOR_PATH => Some(canonical),
        (SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE, "head")
            if provider_frontier_head_path(&canonical) =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE, "intent")
            if provider_publication_intent_path(&canonical) =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE, "link")
            if provider_manifest_recovery_link_id(&canonical).is_some() =>
        {
            Some(canonical)
        }
        (SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE, "manifest")
            if provider_manifest_recovery_blob_digest(&canonical).is_some() =>
        {
            Some(canonical)
        }
        _ => None,
    }
}

fn reconcile_generated_provider_conflict(
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    path: &str,
) -> Result<bool, SyncRuntimeRequestError> {
    let Some(canonical) = canonical_generated_provider_conflict(path) else {
        return Ok(false);
    };
    if provider
        .read_exact(path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
        .is_none()
    {
        // Exact watcher paths report removals as well as creations. An already
        // absent conflict copy is settled work, not ambiguous evidence.
        return Ok(true);
    }
    let canonical_bytes = provider
        .read_exact(&canonical)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
        .ok_or_else(|| {
            SyncRuntimeRequestError::ActorRefused(format!(
                "provider conflict copy retained because canonical target is absent at {canonical}"
            ))
        })?;
    let canonical_valid = if let Some(digest) = canonical
        .strip_prefix("objects/")
        .and_then(|name| name.strip_suffix(".object"))
    {
        ContentDigest::of(&canonical_bytes).to_string() == digest
            && OperationObject::decode(&canonical_bytes).is_ok()
    } else if let Some(batch_id) = provider_manifest_id(&canonical) {
        OperationBatch::decode(&canonical_bytes)
            .map(|manifest| {
                manifest.batch_id() == batch_id
                    && manifest.workspace_id() == descriptor.workspace_id()
                    && manifest.lineage_digest() == descriptor.lineage_digest()
            })
            .unwrap_or(false)
    } else if canonical == SHARED_ENROLLMENT_DESCRIPTOR_PATH {
        SharedEnrollmentDescriptorV1::decode(&canonical_bytes)
            .map(|found| found == *descriptor)
            .unwrap_or(false)
    } else if provider_frontier_head_path(&canonical) {
        SharedProviderFrontierHeadV1::decode(&canonical, &canonical_bytes)
            .map(|head| {
                head.workspace_id() == descriptor.workspace_id()
                    && head.lineage_digest() == descriptor.lineage_digest()
                    && descriptor
                        .digest()
                        .is_ok_and(|digest| head.descriptor_digest() == digest)
            })
            .unwrap_or(false)
    } else if provider_publication_intent_path(&canonical) {
        SharedProviderPublicationIntentV1::decode(&canonical, &canonical_bytes)
            .map(|intent| {
                intent.workspace_id() == descriptor.workspace_id()
                    && intent.lineage_digest() == descriptor.lineage_digest()
                    && descriptor
                        .digest()
                        .is_ok_and(|digest| intent.descriptor_digest() == digest)
            })
            .unwrap_or(false)
    } else if let Some(batch_id) = provider_manifest_recovery_link_id(&canonical) {
        SharedProviderManifestRecoveryLinkV1::decode(&canonical, &canonical_bytes)
            .map(|link| {
                link.batch_id() == batch_id
                    && link.workspace_id() == descriptor.workspace_id()
                    && link.lineage_digest() == descriptor.lineage_digest()
                    && descriptor
                        .digest()
                        .is_ok_and(|digest| link.descriptor_digest() == digest)
            })
            .unwrap_or(false)
    } else if let Some(digest) = provider_manifest_recovery_blob_digest(&canonical) {
        OperationBatch::decode(&canonical_bytes)
            .map(|manifest| {
                ContentDigest::of(&canonical_bytes).to_string() == digest
                    && manifest.workspace_id() == descriptor.workspace_id()
                    && manifest.lineage_digest() == descriptor.lineage_digest()
            })
            .unwrap_or(false)
    } else {
        false
    };
    if !canonical_valid {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "provider conflict copy retained because canonical target is invalid at {canonical}"
        )));
    }
    provider
        .remove_identical_generated_conflict(path, &canonical)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    Ok(true)
}

fn load_provider_manifest_recovery_exact(
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    batch_id: BatchId,
) -> Result<Option<(OperationBatch, Vec<u8>)>, SyncRuntimeRequestError> {
    let link_path = format!("{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/{batch_id}.link");
    #[cfg(test)]
    {
        PROVIDER_TRAVERSAL_INSTRUMENTATION
            .lock()
            .unwrap()
            .entry(descriptor.workspace_id())
            .or_default()
            .recovery_links += 1;
    }
    let Some(link_bytes) = provider
        .read_exact(&link_path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    else {
        return Ok(None);
    };
    let link = SharedProviderManifestRecoveryLinkV1::decode(&link_path, &link_bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if link.batch_id() != batch_id
        || link.workspace_id() != descriptor.workspace_id()
        || link.lineage_digest() != descriptor.lineage_digest()
        || !descriptor
            .digest()
            .is_ok_and(|digest| link.descriptor_digest() == digest)
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "provider manifest recovery link is outside the active namespace at {link_path}"
        )));
    }
    let blob_path = link.blob_path();
    #[cfg(test)]
    {
        PROVIDER_TRAVERSAL_INSTRUMENTATION
            .lock()
            .unwrap()
            .entry(descriptor.workspace_id())
            .or_default()
            .recovery_blobs += 1;
    }
    let manifest_bytes = provider
        .read_exact(&blob_path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
        .ok_or_else(|| {
            SyncRuntimeRequestError::ActorRefused(format!(
                "provider manifest recovery blob is absent at {blob_path}"
            ))
        })?;
    let manifest = OperationBatch::decode(&manifest_bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if ContentDigest::of(&manifest_bytes) != link.manifest_digest()
        || manifest.batch_id() != batch_id
        || manifest.workspace_id() != descriptor.workspace_id()
        || manifest.lineage_digest() != descriptor.lineage_digest()
        || manifest.author_device_id() != link.manifest_author_device_id()
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "provider manifest recovery evidence conflicts for batch {batch_id}"
        )));
    }
    Ok(Some((manifest, manifest_bytes)))
}

fn recover_provider_manifest_exact(
    provider: &mut SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    batch_id: BatchId,
) -> Result<bool, SyncRuntimeRequestError> {
    let Some((_manifest, manifest_bytes)) =
        load_provider_manifest_recovery_exact(provider, descriptor, batch_id)?
    else {
        return Ok(false);
    };
    provider
        .publish_manifest(batch_id, &manifest_bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    Ok(true)
}

fn stage_provider_manifest_exact(
    store: &ObjectStore,
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    path: &str,
) -> Result<(ProviderManifestIngress, bool), SyncRuntimeRequestError> {
    let batch_id = provider_manifest_id(path).ok_or_else(|| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "unknown shared provider evidence retained at {path}"
        ))
    })?;
    let Some(bytes) = provider
        .read_exact(path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    else {
        return Ok((ProviderManifestIngress::Absent(batch_id), false));
    };
    let manifest = OperationBatch::decode(&bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if manifest.batch_id() != batch_id
        || path != format!("manifests/{}.manifest", manifest.batch_id())
        || manifest.workspace_id() != descriptor.workspace_id()
        || manifest.lineage_digest() != descriptor.lineage_digest()
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "conflicting provider manifest retained at {path}"
        )));
    }
    let ingress = descriptor
        .provider_ingress()
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    store
        .stage_shared_provider_manifest_bytes(&ingress, &bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let mut object_arrived = false;
    for object in manifest.required_objects() {
        let object_path = format!("objects/{}.object", object.content_digest());
        let Some(object_bytes) = provider
            .read_exact(&object_path)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
        else {
            return Ok((
                ProviderManifestIngress::Incomplete(manifest),
                object_arrived,
            ));
        };
        let digest = ContentDigest::of(&object_bytes);
        if digest != object.content_digest() {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "conflicting provider object retained at {object_path}"
            )));
        }
        let already_present = store
            .contains_object(digest)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        store
            .stage_object_bytes(&object_bytes)
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        object_arrived |= !already_present;
    }
    let ingress = match store
        .inspect_batch(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    {
        crate::oplog::BatchInspection::Ready(_) => ProviderManifestIngress::Ready(manifest),
        crate::oplog::BatchInspection::Staged { .. } => {
            ProviderManifestIngress::Incomplete(manifest)
        }
        crate::oplog::BatchInspection::Absent => ProviderManifestIngress::Incomplete(manifest),
    };
    Ok((ingress, object_arrived))
}

fn provider_manifest_present(
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    batch_id: BatchId,
) -> Result<bool, SyncRuntimeRequestError> {
    let path = format!("manifests/{batch_id}.manifest");
    let Some(bytes) = provider
        .read_exact(&path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    else {
        return Ok(false);
    };
    let manifest = OperationBatch::decode(&bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if manifest.batch_id() != batch_id
        || manifest.workspace_id() != descriptor.workspace_id()
        || manifest.lineage_digest() != descriptor.lineage_digest()
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "conflicting provider manifest retained at {path}"
        )));
    }
    Ok(true)
}

fn provider_manifest_recovery_link_present(
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    batch_id: BatchId,
) -> Result<bool, SyncRuntimeRequestError> {
    let path = format!("{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/{batch_id}.link");
    let Some(bytes) = provider
        .read_exact(&path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    else {
        return Ok(false);
    };
    let link = SharedProviderManifestRecoveryLinkV1::decode(&path, &bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if link.batch_id() != batch_id
        || link.workspace_id() != descriptor.workspace_id()
        || link.lineage_digest() != descriptor.lineage_digest()
        || !descriptor
            .digest()
            .is_ok_and(|digest| link.descriptor_digest() == digest)
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "provider manifest recovery link conflicts at {path}"
        )));
    }
    Ok(true)
}

fn load_provider_manifest_with_fingerprint(
    provider: &SharedProviderTransport,
    descriptor: &SharedEnrollmentDescriptorV1,
    batch_id: BatchId,
    expected_fingerprint: ContentDigest,
) -> Result<Option<(OperationBatch, Vec<u8>)>, SyncRuntimeRequestError> {
    let path = format!("manifests/{batch_id}.manifest");
    provider_accepted_audit_cut(descriptor.workspace_id(), batch_id, "provider_read")?;
    let Some(bytes) = provider
        .read_exact(&path)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?
    else {
        return Ok(None);
    };
    let manifest = OperationBatch::decode(&bytes)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    if manifest.batch_id() != batch_id
        || manifest.workspace_id() != descriptor.workspace_id()
        || manifest.lineage_digest() != descriptor.lineage_digest()
        || ContentDigest::of(&bytes) != expected_fingerprint
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "accepted provider manifest fingerprint conflicts at {path}"
        )));
    }
    Ok(Some((manifest, bytes)))
}

fn local_archive_manifest_digest(
    store: &ObjectStore,
    manifest: &OperationBatch,
) -> Result<ContentDigest, SyncRuntimeRequestError> {
    let mut hasher = Sha256::new();
    hasher.update(b"tine/joiner-local-archive-entry/v2\0");
    let bytes = store
        .read_manifest_bytes(manifest.batch_id())
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    hasher.update((bytes.len() as u64).to_be_bytes());
    hasher.update(&bytes);
    for object in manifest.required_objects() {
        let bytes = store
            .read_object_bytes(object.content_digest())
            .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
        hasher.update((bytes.len() as u64).to_be_bytes());
        hasher.update(&bytes);
    }
    Ok(ContentDigest::from_bytes(hasher.finalize().into()))
}

fn local_authorship_receipt_directory(provider_journal_root: &Path) -> Result<PathBuf, String> {
    provider_journal_root
        .parent()
        .map(|parent| parent.join(LOCAL_AUTHORSHIP_RECEIPT_NAMESPACE))
        .ok_or_else(|| "provider journal root has no private device directory".to_owned())
}

fn local_authorship_receipt_path(
    provider_journal_root: &Path,
    batch_id: BatchId,
) -> Result<PathBuf, String> {
    Ok(local_authorship_receipt_directory(provider_journal_root)?
        .join(format!("{batch_id}.receipt")))
}

fn inspect_local_authorship_receipt_directory(path: &Path) -> Result<bool, String> {
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => {
            return Err(format!(
                "cannot inspect private local-authorship receipt directory: {error}"
            ));
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err("private local-authorship receipt namespace has unsafe shape".into());
    }
    Ok(true)
}

fn load_local_authorship_receipt(
    provider_journal_root: &Path,
    batch_id: BatchId,
) -> Result<Option<LocalAuthorshipReceiptV1>, SyncRuntimeRequestError> {
    let directory = local_authorship_receipt_directory(provider_journal_root)
        .map_err(SyncRuntimeRequestError::ActorRefused)?;
    if !inspect_local_authorship_receipt_directory(&directory)
        .map_err(SyncRuntimeRequestError::ActorRefused)?
    {
        return Ok(None);
    }
    let path = local_authorship_receipt_path(provider_journal_root, batch_id)
        .map_err(SyncRuntimeRequestError::ActorRefused)?;
    let metadata = match fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(SyncRuntimeRequestError::ActorRefused(format!(
                "cannot inspect local-authorship receipt for {batch_id}: {error}"
            )));
        }
    };
    if metadata.file_type().is_symlink()
        || !metadata.is_file()
        || metadata.len() > MAX_LOCAL_AUTHORSHIP_RECEIPT_BYTES
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "local-authorship receipt for {batch_id} has unsafe shape"
        )));
    }
    let bytes = fs::read(&path).map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "cannot read local-authorship receipt for {batch_id}: {error}"
        ))
    })?;
    let receipt: LocalAuthorshipReceiptV1 = serde_json::from_slice(&bytes).map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "local-authorship receipt for {batch_id} is corrupt: {error}"
        ))
    })?;
    let canonical = serde_json::to_vec(&receipt).map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "cannot encode local-authorship receipt for {batch_id}: {error}"
        ))
    })?;
    if canonical != bytes
        || receipt.binding.schema_version != LOCAL_AUTHORSHIP_RECEIPT_SCHEMA_VERSION
        || receipt.binding.batch_id != batch_id
        || receipt.receipt_digest != receipt.binding.receipt_digest()?
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "local-authorship receipt for {batch_id} is noncanonical or fails its digest"
        )));
    }
    Ok(Some(receipt))
}

fn persist_local_authorship_receipt(
    provider_journal_root: &Path,
    receipt: &LocalAuthorshipReceiptV1,
) -> Result<(), SyncRuntimeRequestError> {
    let directory = local_authorship_receipt_directory(provider_journal_root)
        .map_err(SyncRuntimeRequestError::ActorRefused)?;
    fs::create_dir_all(&directory).map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "cannot create private local-authorship receipt directory: {error}"
        ))
    })?;
    inspect_local_authorship_receipt_directory(&directory)
        .map_err(SyncRuntimeRequestError::ActorRefused)?;
    let path = local_authorship_receipt_path(provider_journal_root, receipt.binding.batch_id)
        .map_err(SyncRuntimeRequestError::ActorRefused)?;
    let encoded = serde_json::to_string(receipt).map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "cannot encode local-authorship receipt: {error}"
        ))
    })?;
    crate::model::atomic_update(&path, &LOCAL_AUTHORSHIP_RECEIPT_LOCK, |content| {
        if content != "{}\n" {
            let existing: LocalAuthorshipReceiptV1 =
                serde_json::from_str(content).map_err(|error| {
                    std::io::Error::new(
                        std::io::ErrorKind::InvalidData,
                        format!("local-authorship receipt is corrupt: {error}"),
                    )
                })?;
            if &existing != receipt {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "local-authorship receipt conflicts with an existing batch receipt",
                ));
            }
        }
        Ok(encoded.clone())
    })
    .map_err(|error| {
        SyncRuntimeRequestError::ActorRefused(format!(
            "cannot persist local-authorship receipt for {}: {error}",
            receipt.binding.batch_id
        ))
    })
}

#[allow(clippy::too_many_arguments)]
fn local_authorship_is_proven(
    provider_journal_root: &Path,
    binding: &EnrollmentBindingV1,
    promotion_session_id: SessionId,
    promoted_state_digest: ContentDigest,
    engine: &crate::oplog::ShardedHotEngine,
    store: &ObjectStore,
    manifest: &OperationBatch,
) -> Result<bool, SyncRuntimeRequestError> {
    let batch_id = manifest.batch_id();
    let Some(receipt) = load_local_authorship_receipt(provider_journal_root, batch_id)? else {
        return Ok(false);
    };
    let manifest_bytes = store
        .read_manifest_bytes(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let evidence = engine
        .accepted_batch_evidence(batch_id)
        .map_err(|error| SyncRuntimeRequestError::ActorRefused(error.to_string()))?;
    let expected = LocalAuthorshipReceiptBindingV1 {
        schema_version: LOCAL_AUTHORSHIP_RECEIPT_SCHEMA_VERSION,
        workspace_id: binding.workspace_id(),
        lineage_digest: binding.lineage_digest(),
        device_id: binding.device_id(),
        endpoint_id: binding.endpoint_id(),
        graph_resource_id: binding.graph_resource_id(),
        promotion_session_id,
        promoted_state_digest,
        author_session_id: manifest.author_session_id(),
        batch_id,
        manifest_fingerprint: ContentDigest::of(&manifest_bytes),
        accepted_event_binding_digest: evidence.event_binding_digest(),
        acceptance_sequence: evidence.acceptance_sequence(),
        prior_frontier_state_digest: evidence.prior_frontier_root().state_digest(),
        post_frontier_state_digest: evidence.post_frontier_root().state_digest(),
    };
    if manifest.origin() != BatchOrigin::LocalMutation
        || manifest.workspace_id() != binding.workspace_id()
        || manifest.lineage_digest() != binding.lineage_digest()
        || manifest.author_device_id() != binding.device_id()
        || receipt.binding != expected
    {
        return Err(SyncRuntimeRequestError::ActorRefused(format!(
            "local-authorship receipt for {batch_id} does not bind this accepted LocalActive mutation"
        )));
    }
    Ok(true)
}

fn map_ambiguous_evidence(evidence: AmbiguousEvidence) -> SyncAmbiguousEvidence {
    match evidence {
        AmbiguousEvidence::EnrollmentResidue => SyncAmbiguousEvidence::EnrollmentResidue,
        AmbiguousEvidence::EnrollmentNamespace => SyncAmbiguousEvidence::EnrollmentNamespace,
        AmbiguousEvidence::EnrollmentGraphBinding => SyncAmbiguousEvidence::EnrollmentGraphBinding,
        AmbiguousEvidence::ArchiveResidue => SyncAmbiguousEvidence::ArchiveResidue,
        AmbiguousEvidence::ArchiveNamespace => SyncAmbiguousEvidence::ArchiveNamespace,
        AmbiguousEvidence::ArchiveBinding => SyncAmbiguousEvidence::ArchiveBinding,
        AmbiguousEvidence::ActiveArchiveMismatch => SyncAmbiguousEvidence::ActiveArchiveMismatch,
    }
}

fn map_component(component: DiscoveryComponent) -> SyncRuntimeComponent {
    match component {
        DiscoveryComponent::Enrollment => SyncRuntimeComponent::Enrollment,
        DiscoveryComponent::Archive => SyncRuntimeComponent::Archive,
    }
}

