        assert_parser_dto_semantics(&expected_journal, &recovered_journal);
        let (logical, _) = load_application_logical(&handle, " /ORDINARY Ω/ ", SyncPageKind::Page);
        assert_parser_dto_semantics(&ordinary, &logical);
        connection
