    #[test]
    fn editor_final_name_collisions_refuse_existing_and_new_saves_before_publication() {
        let fixture = RuntimeHostFixture::safe("editor-final-name-collision");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let target_path = "content/nested pages/Collision Target.md";
        let owner_path = "content/nested pages/Collision Owner.md";
        admit_external_page(
            &handle,
            &fixture,
            target_path,
            b"title:: Collision Before\n\n- target body\n",
        );
        admit_external_page(
            &handle,
            &fixture,
            owner_path,
            b"title:: Collision Final\n\n- owner body\n",
        );
        let target = load_editor_named(&handle, "Collision Before", SyncPageKind::Page);
        let draft = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: "Collision New Physical".into(),
                    page_kind: SyncPageKind::Page,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::NewPage { draft } => draft,
            other => panic!("collision scenario did not produce a draft: {other:?}"),
        };
        let manifests_before = fixture.manifest_count();
        let applied_before = fixture.applied_batch_count();
        let files_before = snapshot_graph_files(fixture.graph_root());

        assert_eq!(
            handle
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::Existing {
                        page_id: target.page_id,
                        revision: target.revision,
                    },
                    preamble: Some("title:: Collision Final".into()),
                    blocks: target.blocks,
                })
                .unwrap(),
            SyncEditorSaveOutcome::Conflict {
                reason: SyncEditorConflict::PageAlreadyExists
            }
        );
        assert_eq!(
            handle
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::New {
                        name: draft.name,
                        page_kind: draft.page_kind,
                        revision: draft.revision,
                        format: None,
                    },
                    preamble: Some("title:: Collision Final".into()),
                    blocks: vec![SyncEditorBlockDto {
                        key: SyncEditorBlockKey::Temporary("body".into()),
                        parent: None,
                        content: "must not publish".into(),
                    }],
                })
                .unwrap(),
            SyncEditorSaveOutcome::Conflict {
                reason: SyncEditorConflict::PageAlreadyExists
            }
        );
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(fixture.applied_batch_count(), applied_before);
        assert_eq!(snapshot_graph_files(fixture.graph_root()), files_before);
        assert_eq!(
            fs::read(fixture.graph_root().join(target_path)).unwrap(),
            b"title:: Collision Before\n\n- target body\n"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_title_content_and_referrer_changes_share_one_atomic_user_authoritative_save() {
        let fixture = RuntimeHostFixture::safe("editor-atomic-title-content-referrers");
        let request = fixture.request();
        let handle = active_handle(SyncRuntimeHandle::open(request.clone()));
        drive_initial_feed(&handle);
        let target_path = "content/nested pages/deep/physical atomic target.md";
        let referrer_path = "content/nested pages/deep/atomic referrer.md";
        fs::create_dir_all(fixture.graph_root().join(target_path).parent().unwrap()).unwrap();
        admit_external_page(
            &handle,
            &fixture,
            target_path,
            b"title:: Atomic Before\nself:: [[Atomic Before]]\nstatus:: before\n\n- target before [[Atomic Before]]\n",
        );
        admit_external_page(
            &handle,
            &fixture,
            referrer_path,
            b"related:: [[Atomic Before]]\n\n- referrer [[Atomic Before]]\n",
        );
        let mut target = load_editor_named(&handle, "Atomic Before", SyncPageKind::Page);
        target.blocks[0].content = "target user final [[Atomic Before]]".into();
        let target_id = parse_editor_page_id(&target.page_id).unwrap();
        let referrer = load_editor_named(&handle, "atomic referrer", SyncPageKind::Page);
        let referrer_id = parse_editor_page_id(&referrer.page_id).unwrap();

        let outcome = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: target.page_id,
                    revision: target.revision,
                },
                preamble: Some(
                    "title:: Atomic After\nself:: [[Atomic Before]]\nstatus:: user final".into(),
                ),
                blocks: target.blocks,
            })
            .unwrap();
        let affected = match outcome {
            SyncEditorSaveOutcome::Durable {
                affected_page_ids, ..
            } => affected_page_ids,
            SyncEditorSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                affected_page_ids,
            } => {
                settle_local_mutation(&handle);
                affected_page_ids
            }
            other => panic!("atomic editor rename was not retained or durable: {other:?}"),
        };
        let counters = handle
            .managed_application_save_instrumentation()
            .expect("multi-page editor save exposes prepared-projection instrumentation")
            .prepared_editor_projection;
        assert_eq!(counters.created, 1);
        assert_eq!(
            counters.reused, 0,
            "rename/referrer work is ineligible for reuse"
        );
        assert_eq!(
            counters.fallback, 1,
            "the affine artifact is discarded once"
        );
        assert!(
            counters.finalizer_post_state_render >= 2,
            "the renamed page and its referrer must each retain an ordinary complete post-state render"
        );
        assert_eq!(
            affected.into_iter().collect::<BTreeSet<_>>(),
            BTreeSet::from([target_id.to_string(), referrer_id.to_string()])
        );

        let saved_target = load_editor_id(&handle, target_id);
        let saved_referrer = load_editor_id(&handle, referrer_id);
        assert_eq!(saved_target.name, "Atomic After");
        assert_eq!(saved_target.path, target_path);
        assert_eq!(
            saved_target.preamble.as_deref(),
            Some("title:: Atomic After\nself:: [[Atomic Before]]\nstatus:: user final")
        );
        assert_eq!(
            saved_target.blocks[0].content,
            "target user final [[Atomic Before]]"
        );
        assert_eq!(
            saved_referrer.preamble.as_deref(),
            Some("related:: [[Atomic After]]")
        );
        assert_eq!(
            saved_referrer.blocks[0].content,
            "referrer [[Atomic After]]"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(handle);

        let restarted = active_handle(SyncRuntimeHandle::open(request));
        drive_initial_feed(&restarted);
        assert_eq!(load_editor_id(&restarted, target_id), saved_target);
        assert_eq!(load_editor_id(&restarted, referrer_id), saved_referrer);
        assert!(matches!(
            restarted.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_content_saves_retain_accepted_identity_across_filename_and_journal_policy_changes() {
        struct PolicyScenario {
            label: &'static str,
            initial_config: &'static [u8],
            current_config: &'static [u8],
            path: &'static str,
            initial: &'static [u8],
            accepted_name: &'static str,
            accepted_kind: SyncPageKind,
        }
        let scenarios = [
            PolicyScenario {
                label: "editor-filename-policy-retention",
                initial_config: br#"{:pages-directory "content/nested pages"
                    :journals-directory "diary"
                    :file/name-format :legacy}"#,
                current_config: br#"{:pages-directory "content/nested pages"
                    :journals-directory "diary"
                    :file/name-format :triple-lowbar}"#,
                path: "content/nested pages/A.B.md",
                initial: b"- before policy change\n",
                accepted_name: "A/B",
                accepted_kind: SyncPageKind::Page,
            },
            PolicyScenario {
                label: "editor-journal-policy-retention",
                initial_config: br#"{:pages-directory "content/nested pages"
                    :journals-directory "diary"
                    :journal/file-name-format "dd-MM-yyyy"
                    :journal/page-title-format "yyyy-MM-dd"}"#,
                current_config: br#"{:pages-directory "content/nested pages"
                    :journals-directory "diary"
                    :journal/file-name-format "dd-MM-yyyy"
                    :journal/page-title-format "MMM d, yyyy"}"#,
                path: "diary/physical journal policy.md",
                initial: b"title:: 25-07-2026\n\n- before journal policy change\n",
                accepted_name: "2026-07-25",
                accepted_kind: SyncPageKind::Journal,
            },
        ];

        for scenario in scenarios {
            let fixture =
                RuntimeHostFixture::safe_with_config(scenario.label, scenario.initial_config);
            let request = fixture.request();
            let first = active_handle(SyncRuntimeHandle::open(request.clone()));
            drive_initial_feed(&first);
            admit_external_page(&first, &fixture, scenario.path, scenario.initial);
            let accepted_row = match first
                .query(SyncRuntimeQueryRequest::ListPages {
                    page_kind: None,
                    limit: MAX_MATERIALIZATION_QUERY_ROWS,
                })
                .unwrap()
            {
                SyncRuntimeQueryReply::Pages(pages) => pages
                    .into_iter()
                    .find(|page| page.path == scenario.path)
                    .unwrap_or_else(|| panic!("{} was not imported", scenario.label)),
                other => panic!("SQLite page list returned the wrong reply: {other:?}"),
            };
            assert_eq!(
                accepted_row.name, scenario.accepted_name,
                "{}",
                scenario.label
            );
            assert_eq!(
                accepted_row.kind, scenario.accepted_kind,
                "{}",
                scenario.label
            );
            let accepted = load_editor_id(&first, parse_page_id(&accepted_row.page_id).unwrap());
            let page_id = parse_editor_page_id(&accepted.page_id).unwrap();
            assert!(matches!(
                first.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ));
            drop(first);

            fs::write(
                fixture.graph_root().join("logseq/config.edn"),
                scenario.current_config,
            )
            .unwrap();
            let reopened = active_handle(SyncRuntimeHandle::open(request.clone()));
            drive_initial_feed(&reopened);
            let mut loaded = load_editor_id(&reopened, page_id);
            loaded.blocks[0].content.push_str(" edited");
            retain_editor_save(
                &reopened,
                SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::Existing {
                        page_id: loaded.page_id,
                        revision: loaded.revision,
                    },
                    preamble: loaded.preamble,
                    blocks: loaded.blocks,
                },
            );
            let saved = load_editor_id(&reopened, page_id);
            assert_eq!(saved.name, scenario.accepted_name);
            assert_eq!(saved.page_kind, scenario.accepted_kind);
            assert_eq!(saved.path, scenario.path);
            assert!(saved.blocks[0].content.ends_with(" edited"));
            assert!(matches!(
                reopened.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ));
            drop(reopened);

            let restarted = active_handle(SyncRuntimeHandle::open(request));
            drive_initial_feed(&restarted);
            assert_eq!(load_editor_id(&restarted, page_id), saved);
            assert!(matches!(
                restarted.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ));
        }
    }

    #[test]
    fn interior_sqlite_counterfeit_cannot_become_durable_editor_truth() {
        crate::test_support::run_on_deep_stack(|| {
            const BLOCK_COUNT: usize = 128;
            const ORIGINAL: &[u8] = b"authoritative-row";
            const COUNTERFEIT: &[u8] = b"counterfeited-row";

            let fixture = RuntimeHostFixture::safe("sync-runtime-editor-interior-corruption");
            let request = fixture.request();
            let first = active_handle(SyncRuntimeHandle::open(request.clone()));
            drive_initial_feed(&first);
            let draft = match first
                .load_editor_page(SyncEditorLoadRequest {
                    page: SyncEditorPageSelector::Name {
                        name: "Editor corruption authority".into(),
                        page_kind: SyncPageKind::Page,
                    },
                })
                .unwrap()
            {
                SyncEditorLoadOutcome::NewPage { draft } => draft,
                other => panic!("corruption fixture did not produce a new-page draft: {other:?}"),
            };
            let created = first
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::New {
                        name: draft.name,
                        page_kind: draft.page_kind,
                        revision: draft.revision,
                        format: None,
                    },
                    preamble: Some("authority:: oplog".into()),
                    blocks: (0..BLOCK_COUNT)
                        .map(|index| SyncEditorBlockDto {
                            key: SyncEditorBlockKey::Temporary(format!("block-{index}")),
                            parent: None,
                            content: format!("authoritative-row-{index:04}-{}", "x".repeat(192)),
                        })
                        .collect(),
                })
                .unwrap();
            let created = match created {
                SyncEditorSaveOutcome::Durable { page, .. } => page,
                SyncEditorSaveOutcome::Deferred {
                    state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                    ..
                } => {
                    settle_local_mutation(&first);
                    load_editor_named(&first, "Editor corruption authority", SyncPageKind::Page)
                }
                other => panic!("large corruption fixture was not durable: {other:?}"),
            };
            let page_id = parse_editor_page_id(&created.page_id).unwrap();
            let page_path = created.path.clone();
            assert!(matches!(
                first.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ));

            let patched = crate::oplog::sqlite::corrupt_equal_length_interior_block_payload(
                &request.database_path,
                ORIGINAL,
                COUNTERFEIT,
            );
            assert!(patched > 0);
            let graph = Graph::open_checked(&request.graph_root).unwrap();
            let advisory = match discover_startup(&DiscoveryRequest {
                profile: StartupStorageProfile::ExperimentalSparse,
                graph_resource_id: graph.canonical_resource_id().unwrap(),
                runtime_root: &request.enrollment_root,
                archive_root: &request.archive_root,
            }) {
                DiscoveryClassification::ExistingLocalActive(advisory) => advisory,
                other => panic!("corruption fixture was no longer LocalActive: {other:?}"),
            };
            // Bind this counterfeit fixture into the bounded checkpoint so this
            // existing regression continues to prove the later affected-page
            // semantic authority fence independently of accidental-corruption
            // sampling.
            crate::oplog::sqlite::refresh_projection_checkpoint_for_harness(
                &request.database_path,
                crate::oplog::sqlite::ProjectionClaim::current(
                    advisory.binding.workspace_id(),
                    advisory.binding.lineage_digest(),
                ),
            )
            .unwrap();
            let reopened = active_handle(SyncRuntimeHandle::open(request.clone()));
            drive_initial_feed(&reopened);
            let load = reopened.load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::PageId {
                    page_id: page_id.to_string(),
                },
            });
            let mut repaired = match load {
                Ok(SyncEditorLoadOutcome::Loaded { page }) => page,
                other => panic!("authenticated hot editor load was unavailable: {other:?}"),
            };
            assert!(repaired
                .blocks
                .iter()
                .all(|block| !block.content.starts_with("counterfeited-row-")));
            let edited = repaired
                .blocks
                .iter_mut()
                .find(|block| block.content.starts_with("authoritative-row-0064-"))
                .expect("repaired page lost the target editor block");
            edited.content.push_str(" honest-editor-suffix");
            let saved = reopened
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::Existing {
                        page_id: repaired.page_id.clone(),
                        revision: repaired.revision,
                    },
                    preamble: repaired.preamble,
                    blocks: repaired.blocks,
                })
                .unwrap();
            let saved = match saved {
                SyncEditorSaveOutcome::Durable { page, .. } => page,
                SyncEditorSaveOutcome::Deferred {
                    state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                    ..
                } => {
                    settle_local_mutation(&reopened);
                    load_editor_named(&reopened, "Editor corruption authority", SyncPageKind::Page)
                }
                other => panic!("repaired editor save was not durable: {other:?}"),
            };
            drain_managed_local(&reopened);
            assert!(matches!(
                reopened.clean_shutdown().unwrap(),
                SyncShutdownOutcome::Safe(_)
            ));

            let replayed = fixture.replay_materialized_page(page_id);
            assert_eq!(replayed.stats.catalog_documents_loaded, 1);
            assert_eq!(replayed.stats.membership_documents_loaded, 1);
            assert_eq!(replayed.stats.home_documents_loaded, 1);
            assert!(replayed
                .blocks
                .iter()
                .all(|block| !block.content.starts_with("counterfeited-row-")));
            assert!(replayed
                .blocks
                .iter()
                .any(|block| block.content.ends_with(" honest-editor-suffix")));
            let projected = rusqlite::Connection::open(&request.database_path)
                .unwrap()
                .query_row(
                    "SELECT COUNT(*) FROM blocks
                 WHERE page_id = ?1 AND content LIKE 'counterfeited-row-%'",
                    rusqlite::params![page_id.as_uuid().as_bytes().as_slice()],
                    |row| row.get::<_, usize>(0),
                )
                .unwrap();
            assert_eq!(projected, 0);
            let graph = fs::read_to_string(fixture.graph_root().join(&page_path)).unwrap();
            assert!(graph.contains("honest-editor-suffix"));
            assert!(!graph.contains("counterfeited-row-"));
            assert_eq!(saved.page_id, page_id.to_string());
        });
    }

    #[test]
    fn editor_stale_base_after_external_watcher_edit_has_zero_save_effects() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-stale");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let path = "content/nested pages/Editor Stale.md";
        admit_external_page(&handle, &fixture, path, b"- before external\n");
        let loaded = load_editor_named(&handle, "Editor Stale", SyncPageKind::Page);
        let file = fixture.graph_root().join(path);
        fs::write(&file, b"- accepted external edit\n").unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        settle_exact_feed(&handle)
            .unwrap_or_else(|state| panic!("external edit did not settle: {state:?}"));

        let manifests_before = fixture.manifest_count();
        let applied_before = fixture.applied_batch_count();
        let files_before = snapshot_graph_files(fixture.graph_root());
        let status_before = handle.status().unwrap();
        let outcome = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: loaded.page_id,
                    revision: loaded.revision,
                },
                preamble: loaded.preamble,
                blocks: loaded.blocks,
            })
            .unwrap();
        assert_eq!(
            outcome,
            SyncEditorSaveOutcome::Conflict {
                reason: SyncEditorConflict::StaleBase
            }
        );
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(fixture.applied_batch_count(), applied_before);
        assert_eq!(snapshot_graph_files(fixture.graph_root()), files_before);
        assert_eq!(handle.status().unwrap(), status_before);
        assert_eq!(fs::read(file).unwrap(), b"- accepted external edit\n");
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_rejects_oversized_deep_cyclic_and_duplicate_keys_before_actor_enqueue() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-bounds");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let draft = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: "Bounded Editor".into(),
                    page_kind: SyncPageKind::Page,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::NewPage { draft } => draft,
            other => panic!("expected new-page draft: {other:?}"),
        };
        let target = || SyncEditorSaveTarget::New {
            name: draft.name.clone(),
            page_kind: draft.page_kind,
            revision: draft.revision.clone(),
            format: None,
        };
        let before_status = handle.status().unwrap();
        let manifests_before = fixture.manifest_count();
        let applied_before = fixture.applied_batch_count();
        let files_before = snapshot_graph_files(fixture.graph_root());

        let oversized = (0..=MAX_SYNC_EDITOR_BLOCKS)
            .map(|index| SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary(format!("block-{index}")),
                parent: None,
                content: String::new(),
            })
            .collect();
        assert!(matches!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: oversized,
            }),
            Err(SyncEditorRequestError::RequestTooLarge(_))
        ));

        let mut deep = Vec::new();
        for index in 0..=MAX_SYNC_EDITOR_DEPTH {
            deep.push(SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary(format!("depth-{index}")),
                parent: (index > 0)
                    .then(|| SyncEditorBlockKey::Temporary(format!("depth-{}", index - 1))),
                content: String::new(),
            });
        }
        assert!(matches!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: deep,
            }),
            Err(SyncEditorRequestError::RequestTooLarge(_))
        ));

        let cyclic = vec![
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("a".into()),
                parent: Some(SyncEditorBlockKey::Temporary("b".into())),
                content: String::new(),
            },
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("b".into()),
                parent: Some(SyncEditorBlockKey::Temporary("a".into())),
                content: String::new(),
            },
        ];
        assert_eq!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: cyclic,
            }),
            Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::CyclicOutline
            ))
        );

        let duplicate = vec![
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("same".into()),
                parent: None,
                content: String::new(),
            },
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("same".into()),
                parent: None,
                content: String::new(),
            },
        ];
        assert_eq!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: duplicate,
            }),
            Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::DuplicateKey
            ))
        );

        let long_key = vec![SyncEditorBlockDto {
            key: SyncEditorBlockKey::Temporary("k".repeat(MAX_SYNC_EDITOR_TEMP_KEY_BYTES + 1)),
            parent: None,
            content: String::new(),
        }];
        assert!(matches!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: long_key,
            }),
            Err(SyncEditorRequestError::RequestTooLarge(_))
        ));
        assert!(matches!(
            handle.load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: "n".repeat(MAX_SYNC_EDITOR_REQUEST_BYTES + 1),
                    page_kind: SyncPageKind::Page,
                },
            }),
            Err(SyncEditorRequestError::RequestTooLarge(_))
        ));
        assert_eq!(
            handle.save_editor_page(SyncEditorSaveRequest {
                target: target(),
                preamble: None,
                blocks: vec![SyncEditorBlockDto {
                    key: SyncEditorBlockKey::Existing(Uuid::new_v4().to_string()),
                    parent: None,
                    content: "caller-minted durable block".into(),
                }],
            }),
            Err(SyncEditorRequestError::InvalidRequest(
                SyncEditorInvalidRequest::InvalidExistingId
            ))
        );

        assert_eq!(handle.status().unwrap(), before_status);
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(fixture.applied_batch_count(), applied_before);
        assert_eq!(snapshot_graph_files(fixture.graph_root()), files_before);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_trusted_local_save_is_immediately_durable_and_derivatives_drain_once() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-published-retry");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let path = "content/nested pages/Editor Retry.md";
        admit_external_page(&handle, &fixture, path, b"- before retry\n");
        let loaded = load_editor_named(&handle, "Editor Retry", SyncPageKind::Page);
        let mut blocks = loaded.blocks.clone();
        blocks[0].content = "after retained retry".into();
        let manifests_before = fixture.manifest_count();
        reset_trusted_local_response_parse_fallbacks();
        let outcome = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: loaded.page_id.clone(),
                    revision: loaded.revision,
                },
                preamble: loaded.preamble,
                blocks,
            })
            .unwrap();
        let saved = match outcome {
            SyncEditorSaveOutcome::Durable { page, .. } => page,
            other => panic!("trusted-local editor save was not durable: {other:?}"),
        };
        assert_eq!(
            trusted_local_response_parse_fallbacks(),
            0,
            "an immediate trusted foreground response must reuse its parser-owned target DTO"
        );
        assert_eq!(saved.blocks[0].content, "after retained retry");
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(
            fs::read(fixture.graph_root().join(path)).unwrap(),
            b"- after retained retry\n"
        );
        drain_managed_local(&handle);
        assert_eq!(fixture.manifest_count(), manifests_before + 1);
        let refreshed = load_editor_named(&handle, "Editor Retry", SyncPageKind::Page);
        assert_eq!(refreshed.page_id, loaded.page_id);
        assert_eq!(refreshed.blocks[0].content, "after retained retry");
        assert_eq!(
            fs::read(fixture.graph_root().join(path)).unwrap(),
            b"- after retained retry\n"
        );
        let encoded = serde_json::to_vec(&SyncEditorLoadOutcome::Loaded {
            page: refreshed.clone(),
        })
        .unwrap();
        assert_eq!(
            serde_json::from_slice::<SyncEditorLoadOutcome>(&encoded).unwrap(),
            SyncEditorLoadOutcome::Loaded { page: refreshed }
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn immediate_managed_application_reply_matches_fresh_exact_parse_and_join_for_title_and_journal_identity(
    ) {
        crate::test_support::run_on_deep_stack(|| {
            const DATE_CONFIG: &[u8] = br#"{:pages-directory "content/nested pages"
            :journals-directory "diary"
            :journal/file-name-format "dd-MM-yyyy"
            :journal/page-title-format "yyyy-MM-dd"}"#;
            let scenarios = [
                (
                    "trusted-response-explicit-title",
                    "content/nested pages/physical title.md",
                    b"title:: Before title\n\n- before\n".as_slice(),
                    "title:: Explicit response title",
                    "Explicit response title",
                    SyncPageKind::Page,
                ),
                (
                    "trusted-response-journal-kind",
                    "content/nested pages/physical journal.md",
                    b"title:: Before journal\n\n- before\n".as_slice(),
                    "title:: 25-07-2026",
                    "2026-07-25",
                    SyncPageKind::Journal,
                ),
            ];

            for (label, path, initial, preamble, expected_name, expected_kind) in scenarios {
                let fixture = RuntimeHostFixture::safe_with_config(label, DATE_CONFIG);
                let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
                drive_initial_feed(&handle);
                admit_external_page(&handle, &fixture, path, initial);

                let (mut requested, revision) = load_application_exact(&handle, path);
                requested.pre_block = Some(preamble.into());
                requested.blocks[0].raw = format!("accepted {expected_name} response");
                reset_trusted_local_response_parse_fallbacks();
                let (saved, saved_revision) = match handle
                    .save_application_page(SyncApplicationPageSaveRequest {
                        target: SyncApplicationPageSaveTarget::Existing {
                            path: requested.path.clone(),
                            revision,
                        },
                        page: requested,
                    })
                    .unwrap()
                {
                    SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => {
                        (page, revision)
                    }
                    other => panic!("{label}: immediate managed save was not durable: {other:?}"),
                };
                assert_eq!(
                    trusted_local_response_parse_fallbacks(),
                    0,
                    "{label}: immediate response must reuse parser-owned exact-target evidence"
                );
                let parse_census = handle
                    .managed_application_save_instrumentation()
                    .expect("managed save exposes exact-target parser census");
                assert_eq!(
                    parse_census.application_stages.response_target_parses, 1,
                    "{label}: response preparation must parse the requested target once"
                );
                assert_eq!(
                    parse_census
                        .application_stages
                        .response_target_dto_conversions,
                    1,
                    "{label}: response preparation must convert that retained parse once"
                );
                assert_eq!(
                    parse_census
                        .application_stages
                        .response_target_exact_dto_reparses,
                    0,
                    "{label}: response preparation must not enter Graph::parse_exact_page_dto"
                );
                assert_eq!(
                    parse_census.prepared_editor_projection.created, 1,
                    "{label}: the editor may prepare one local candidate"
                );
                assert_eq!(
                    parse_census.prepared_editor_projection.reused, 0,
                    "{label}: title/kind changes must retain the complete finalizer planner"
                );
                assert_eq!(
                    parse_census.prepared_editor_projection.fallback, 1,
                    "{label}: ineligible editor preparation must be discarded exactly once"
                );
                assert!(
                    parse_census
                        .prepared_editor_projection
                        .finalizer_post_state_render
                        >= 1,
                    "{label}: fallback must render every final post-state requirement"
                );
                assert_eq!(saved.name, expected_name, "{label}");
                assert_eq!(saved.kind, sync_model_page_kind(expected_kind), "{label}");

                // This independently goes through the ordinary exact load,
                // which parses the final target bytes then joins the durable
                // materialized identity.  Compare the complete wire DTO,
                // including block IDs, rather than a selected field subset.
                let (fresh_exact_joined, fresh_revision) = load_application_exact(&handle, path);
                assert_eq!(saved_revision, fresh_revision, "{label}");
                assert_eq!(
                    serde_json::to_value(&saved).unwrap(),
                    serde_json::to_value(&fresh_exact_joined).unwrap(),
                    "{label}: immediate response diverged from fresh exact parse plus join"
                );

                drain_managed_local(&handle);
                assert!(matches!(
                    handle.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));
            }
        });
    }

