    #[test]
    fn shared_join_owns_pending_state_against_a_conflicting_join() {
        let (_initiator, joiner, handle, descriptor) =
            pending_shared_join_fixture("join-owner-conflicting-join", 0xfe280);
        let conflicting = make_shared_fixture("join-owner-conflicting-descriptor", 0xfe2c0);
        let conflicting_descriptor = activate_and_prepare_shared(&conflicting);
        let workspace_id = joiner.request.identities.workspace_id;
        let provider_entries_per_cut = provider_join_entries_per_cut(&joiner);
        reset_shared_join_instrumentation(workspace_id);

        let (between_turns_entered, between_turns_resume) =
            install_shared_join_pause(workspace_id, SharedJoinTestPausePoint::BetweenTurns);
        let owner_handle = handle.clone();
        let owner = std::thread::spawn(move || owner_handle.join_shared(descriptor));
        between_turns_entered.wait();

        let (contended_entered, contended_resume) = install_shared_join_pause(
            workspace_id,
            SharedJoinTestPausePoint::EnrollmentLockContended,
        );
        let conflicting_handle = handle.clone();
        let competitor =
            std::thread::spawn(move || conflicting_handle.join_shared(conflicting_descriptor));
        contended_entered.wait();
        contended_resume.wait();
        between_turns_resume.wait();

        let joined = owner.join().unwrap();
        assert!(
            joined.is_ok(),
            "the pending join owner lost its enrollment transition: {joined:?}"
        );
        assert!(matches!(
            competitor.join().unwrap(),
            Err(SyncRuntimeRequestError::ActorUnavailable)
        ));
        let traversal = shared_join_instrumentation(workspace_id);
        assert_eq!(
            traversal.provider_entries,
            provider_entries_per_cut * 2,
            "a conflicting descriptor cleared and restarted the owner's pending cut: {traversal:?}"
        );
    }

    #[test]
    fn shared_join_owns_enrollment_transition_against_prepare_shared() {
        let (_initiator, joiner, handle, descriptor) =
            pending_shared_join_fixture("join-owner-prepare", 0xfe300);
        let workspace_id = joiner.request.identities.workspace_id;

        let (between_turns_entered, between_turns_resume) =
            install_shared_join_pause(workspace_id, SharedJoinTestPausePoint::BetweenTurns);
        let owner_handle = handle.clone();
        let owner = std::thread::spawn(move || owner_handle.join_shared(descriptor));
        between_turns_entered.wait();

        let (contended_entered, contended_resume) = install_shared_join_pause(
            workspace_id,
            SharedJoinTestPausePoint::EnrollmentLockContended,
        );
        let preparing_handle = handle.clone();
        let preparing = std::thread::spawn(move || preparing_handle.prepare_shared());
        contended_entered.wait();
        contended_resume.wait();
        between_turns_resume.wait();

        let joined = owner.join().unwrap();
        assert!(
            joined.is_ok(),
            "prepare_shared interleaved the joiner's enrollment transition: {joined:?}"
        );
        assert!(matches!(
            preparing.join().unwrap(),
            Err(SyncRuntimeRequestError::ActorUnavailable)
        ));
        drop(handle);
        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&joiner.request)));
        assert_eq!(
            reopened.status().unwrap().shared_role,
            Some(SyncSharedRole::Joiner)
        );
    }

    #[test]
    fn shared_join_releases_ordinary_operation_ownership_between_turns() {
        let (_initiator, joiner, handle, descriptor) =
            pending_shared_join_fixture("join-owner-status", 0xfe340);
        let workspace_id = joiner.request.identities.workspace_id;

        let (between_turns_entered, between_turns_resume) =
            install_shared_join_pause(workspace_id, SharedJoinTestPausePoint::BetweenTurns);
        let owner_handle = handle.clone();
        let owner = std::thread::spawn(move || owner_handle.join_shared(descriptor));
        between_turns_entered.wait();

        let snapshot = handle
            .status()
            .expect("status must retain ordinary operation ownership between join turns");
        assert_eq!(snapshot.lifecycle, SyncRuntimeLifecycle::Active);
        assert_eq!(snapshot.shared_role, None);
        between_turns_resume.wait();
        assert!(
            owner.join().unwrap().is_ok(),
            "status changed the outcome of the enrollment owner"
        );
    }

    fn activation_fixture_handoff(fixture: &ActivationFixture) -> EnrollmentDiscoveryHandoff {
        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let classification = discover_startup(&DiscoveryRequest {
            profile: StartupStorageProfile::ExperimentalSparse,
            graph_resource_id: graph.canonical_resource_id().unwrap(),
            runtime_root: &fixture.request.enrollment_root,
            archive_root: &fixture.request.archive_root,
        });
        let DiscoveryClassification::ExistingLocalActive(advisory) = classification else {
            panic!("activation fixture no longer classifies LocalActive");
        };
        advisory.handoff
    }

    fn activate_and_prepare_shared(fixture: &ActivationFixture) -> SyncSharedEnrollmentDescriptor {
        let active = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        let handle = active.handle.expect("fixture LocalActive");
        drive_initial_feed(&handle);
        handle.prepare_shared().expect("fixture SharedActive")
    }

    #[test]
    fn managed_storage_validation_is_not_unix_uid_coupled() {
        let uid_probe = ["gete", "uid"].concat();
        for (module, source) in [
            ("wire", include_str!("oplog/wire.rs")),
            ("archive identity", include_str!("oplog/identity.rs")),
            ("enrollment", include_str!("oplog/enrollment.rs")),
            ("SQLite projection", include_str!("oplog/sqlite.rs")),
            (
                "projection receipts",
                include_str!("oplog/projection_store.rs"),
            ),
        ] {
            assert!(
                !source.contains(&uid_probe),
                "{module} admission must not depend on the Tine process uid"
            );
        }
    }

    #[test]
    fn android_receipt_bootstrap_does_not_reenter_capability_preflights() {
        let source = include_str!("oplog/projection_store.rs");
        let directory_start = source
            .find("fn ensure_directory_nofollow(")
            .expect("receipt directory helper");
        let read_start = source[directory_start..]
            .find("fn read_optional_regular(")
            .map(|offset| directory_start + offset)
            .expect("receipt read helper");
        let publication_start = source
            .find("fn publish_android_private_immutable(")
            .expect("Android receipt publication helper");
        let publication_end = source[publication_start..]
            .find("\n#[cfg(test)]\nthread_local!")
            .map(|offset| publication_start + offset)
            .expect("end of Android receipt publication helper");

        let directory = &source[directory_start..read_start];
        assert!(directory.contains("libc::mkdirat"));
        assert!(!directory.contains("root.create_dir"));

        let publication = &source[publication_start..publication_end];
        for required in ["libc::openat", "libc::renameat", "libc::unlinkat"] {
            assert!(
                publication.contains(required),
                "Android receipt publication must retain {required}"
            );
        }
        for forbidden in ["dir.open_with", "dir.rename", "dir.remove_file"] {
            assert!(
                !publication.contains(forbidden),
                "Android receipt bootstrap must not re-enter {forbidden}"
            );
        }

        for function in ["fn open_existing_for_endpoint(", "fn open_with_binding("] {
            let start = source.find(function).expect("receipt root open function");
            let android_start = source[start..]
                .find("#[cfg(target_os = \"android\")]")
                .map(|offset| start + offset)
                .expect("Android receipt root branch");
            let non_android_start = source[android_start..]
                .find("#[cfg(not(target_os = \"android\"))]")
                .map(|offset| android_start + offset)
                .expect("non-Android receipt root branch");
            let android_branch = &source[android_start..non_android_start];
            assert!(android_branch.contains("parent.join(name)"));
            assert!(
                !android_branch.contains("canonicalize("),
                "Android app-private receipt opening must not require traversal of system-owned ancestors"
            );
        }
    }

    #[test]
    fn cold_shared_descriptor_discovery_uses_the_canonical_supported_regular_file() {
        let fixture = ActivationFixture::nested_unicode("cold-conflict-control", 0xa185);
        let descriptor = activate_and_prepare_shared(&fixture);
        let enrollment = fixture.request.provider_root.join("outbox/enrollment");
        let canonical = enrollment.join("shared-enrollment-v1.json");
        assert_eq!(
            inspect_shared_provider_cold_prefix(&fixture.request.provider_root).unwrap(),
            SyncSharedProviderColdPrefix::ReadyForDescriptorInspection,
            "the complete provider shape must still reach canonical descriptor discovery"
        );
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                .unwrap()
                .unwrap(),
            descriptor
        );

        fs::write(
            enrollment.join("shared-enrollment-v1.sync-conflict-20260731-120000-ABCDEFG.json"),
            &descriptor.encoded,
        )
        .unwrap();
        fs::write(fixture.request.provider_root.join(".nomedia"), b"").unwrap();
        fs::write(
            fixture
                .request
                .provider_root
                .join("outbox/.syncthing.provider.tmp"),
            b"partial provider artifact",
        )
        .unwrap();
        assert_eq!(
            inspect_shared_provider_cold_prefix(&fixture.request.provider_root).unwrap(),
            SyncSharedProviderColdPrefix::ReadyForDescriptorInspection,
            "non-authoritative provider artifacts must not hide a valid canonical descriptor"
        );
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                .unwrap()
                .unwrap(),
            descriptor,
            "cold discovery must use the canonical descriptor despite sibling artifacts"
        );
        fs::remove_file(
            enrollment.join("shared-enrollment-v1.sync-conflict-20260731-120000-ABCDEFG.json"),
        )
        .unwrap();

        fs::write(&canonical, b"{").unwrap();
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).unwrap(),
            None,
            "a canonical filename may become visible before its final descriptor bytes"
        );
        fs::write(&canonical, &descriptor.encoded).unwrap();

        let mut unsupported: serde_json::Value =
            serde_json::from_slice(&descriptor.encoded).unwrap();
        let object = unsupported.as_object_mut().unwrap();
        let schema = if object.contains_key("schema_version") {
            object.get_mut("schema_version")
        } else {
            object.get_mut("schemaVersion")
        }
        .expect("shared descriptor schema field");
        *schema = serde_json::Value::from(u64::MAX);
        fs::write(&canonical, serde_json::to_vec(&unsupported).unwrap()).unwrap();
        assert_eq!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).unwrap(),
            None,
            "an incomplete or unsupported descriptor remains retryable while provider delivery settles"
        );
        fs::write(&canonical, &descriptor.encoded).unwrap();

        let extra_link = enrollment.join("descriptor-hard-link");
        fs::hard_link(&canonical, &extra_link).unwrap();
        assert!(
            inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root).is_err(),
            "local filesystem validation errors must not be mislabeled as partial provider delivery"
        );
        fs::remove_file(extra_link).unwrap();

        #[cfg(unix)]
        {
            use std::os::unix::fs::symlink;
            let target = fixture.root.join("descriptor-target");
            fs::write(&target, &descriptor.encoded).unwrap();
            fs::remove_file(&canonical).unwrap();
            symlink(&target, &canonical).unwrap();
            assert!(
                inspect_shared_enrollment_for_cold_discovery(&fixture.request.provider_root)
                    .is_err()
            );
        }
    }

    fn settle_shared_provider(handle: &SyncRuntimeHandle) {
        for _ in 0..1_024 {
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "shared provider did not settle: {tick:?}"
            );
            if matches!(tick, SyncRuntimeTick::Idle)
                && handle.status().unwrap().provider_pending == 0
            {
                return;
            }
        }
        panic!(
            "shared provider exceeded the bounded test turn budget: {:?}",
            handle.status().unwrap()
        );
    }

    fn settle_shared_provider_authority(handle: &SyncRuntimeHandle) {
        for _ in 0..1_024 {
            let tick = handle.tick_provider_for_test().unwrap();
            let status = handle.status().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "shared provider authority did not settle: {tick:?}, {status:?}"
            );
            if status.provider_pending == 0 {
                return;
            }
        }
        panic!(
            "shared provider authority exceeded the bounded test turn budget: {:?}",
            handle.status().unwrap()
        );
    }

    fn joined_shared_pair(
        label: &str,
        seed: u128,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncRuntimeHandle,
        SyncRuntimeHandle,
    ) {
        joined_shared_pair_with_fixture(label, seed, ActivationFixture::nested_unicode)
    }

    fn joined_empty_shared_pair(
        label: &str,
        seed: u128,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncRuntimeHandle,
        SyncRuntimeHandle,
    ) {
        joined_shared_pair_with_fixture(label, seed, ActivationFixture::empty)
    }

    fn joined_shared_pair_with_fixture(
        label: &str,
        seed: u128,
        fixture: fn(&str, u128) -> ActivationFixture,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncRuntimeHandle,
        SyncRuntimeHandle,
    ) {
        let initiator = fixture(&format!("{label}-initiator"), seed);
        let mut receiver = fixture(&format!("{label}-receiver"), seed);
        receiver.request.identities.endpoint_id =
            ProjectionEndpointId::from_uuid(Uuid::from_u128(seed + 0x10));
        receiver.request.identities.device_id = DeviceId::from_uuid(Uuid::from_u128(seed + 0x11));
        receiver.request.identities.session_id = SessionId::from_uuid(Uuid::from_u128(seed + 0x12));
        let descriptor = activate_and_prepare_shared(&initiator);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        let receiver_active = SyncRuntimeHandle::activate_or_resume_local(receiver.request.clone());
        let receiver_joining = receiver_active.handle.expect("receiver LocalActive");
        drive_initial_feed(&receiver_joining);
        receiver_joining
            .join_shared(descriptor)
            .expect("receiver SharedActive");
        drop(receiver_joining);

        let initiator_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&initiator.request)));
        let receiver_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        settle_shared_provider(&initiator_handle);
        settle_shared_provider(&receiver_handle);
        (initiator, receiver, initiator_handle, receiver_handle)
    }

    fn joined_shared_pair_from_graph_copy(
        label: &str,
        seed: u128,
        source: &Path,
    ) -> (
        ActivationFixture,
        ActivationFixture,
        SyncRuntimeHandle,
        SyncRuntimeHandle,
    ) {
        let initiator =
            ActivationFixture::copied_graph(&format!("{label}-initiator"), seed, source);
        let mut receiver =
            ActivationFixture::copied_graph(&format!("{label}-receiver"), seed, source);
        for graph_root in [&initiator.graph_root, &receiver.graph_root] {
            let managed = graph_root.join(".tine-sync");
            if managed.exists() {
                fs::remove_dir_all(managed).unwrap();
            }
        }
        receiver.request.identities.endpoint_id =
            ProjectionEndpointId::from_uuid(Uuid::from_u128(seed + 0x10));
        receiver.request.identities.device_id = DeviceId::from_uuid(Uuid::from_u128(seed + 0x11));
        receiver.request.identities.session_id = SessionId::from_uuid(Uuid::from_u128(seed + 0x12));

        let descriptor = activate_and_prepare_shared(&initiator);
        copy_provider_tree(
            &initiator.request.provider_root,
            &receiver.request.provider_root,
        );
        let receiver_active = SyncRuntimeHandle::activate_or_resume_local(receiver.request.clone());
        let receiver_joining = receiver_active.handle.expect("receiver LocalActive");
        drive_initial_feed(&receiver_joining);
        receiver_joining
            .join_shared(descriptor)
            .unwrap_or_else(|error| panic!("real-corpus receiver could not join: {error}"));
        drop(receiver_joining);

        let initiator_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&initiator.request)));
        let receiver_handle =
            active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        settle_shared_provider(&initiator_handle);
        settle_shared_provider(&receiver_handle);
        (initiator, receiver, initiator_handle, receiver_handle)
    }

    fn submit_shared_page(
        handle: &SyncRuntimeHandle,
        seed: u128,
        name: &str,
        path: &str,
        content: &str,
    ) -> (BatchId, PageId, BlockId, DocumentId) {
        let page_id = PageId::from_uuid(Uuid::from_u128(seed));
        let block_id = BlockId::from_uuid(Uuid::from_u128(seed + 1));
        let document_id = DocumentId::from_uuid(Uuid::from_u128(seed + 2));
        let batch_id = submit_durable(
            handle,
            vec![
                SemanticOperation::CreatePage {
                    page_id,
                    home_document_id: document_id,
                    name: LogicalPageName::parse(name).unwrap(),
                    path: ManagedPath::parse(path).unwrap(),
                    kind: ManagedTextKind::Page,
                },
                SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id,
                        home_document_id: document_id,
                    },
                    page_id,
                    parent: None,
                    order: "a".into(),
                    content: content.into(),
                },
            ],
        );
        (batch_id, page_id, block_id, document_id)
    }

    fn admit_shared_page(
        handle: &SyncRuntimeHandle,
        fixture: &ActivationFixture,
        path: &str,
        body: &[u8],
    ) -> PageId {
        let file = fixture.graph_root.join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, body).unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        settle_exact_feed(handle)
            .unwrap_or_else(|state| panic!("shared page {path:?} did not settle: {state:?}"));
        settle_shared_provider(handle);
        match handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        {
            SyncRuntimeQueryReply::Pages(pages) => pages
                .into_iter()
                .find(|page| page.path == path)
                .and_then(|page| parse_page_id(&page.page_id).ok())
                .unwrap_or_else(|| panic!("shared page {path:?} was not materialized")),
            other => panic!("SQLite page list returned the wrong reply: {other:?}"),
        }
    }

    fn publish_shared_batch(
        handle: &SyncRuntimeHandle,
        fixture: &ActivationFixture,
        batch_id: BatchId,
    ) {
        let manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{batch_id}.manifest"));
        for _ in 0..256 {
            if manifest.is_file() {
                return;
            }
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "shared batch publication failed: {tick:?}"
            );
        }
        panic!("shared batch {batch_id} was not published");
    }

    fn publish_headless_no_op(
        fixture: &ActivationFixture,
        base_batch: BatchId,
        no_op_batch: BatchId,
    ) -> OperationBatch {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let base_manifest =
            OperationBatch::decode(&store.read_manifest_bytes(base_batch).unwrap()).unwrap();
        let semantic_document = base_manifest
            .required_objects()
            .iter()
            .find(|object| object.kind() == crate::oplog::ObjectKind::SemanticEffect)
            .expect("base batch has a semantic object")
            .document_id();
        let empty_effect =
            crate::oplog::SemanticEffect::new(Vec::new(), Vec::new(), Vec::new()).unwrap();
        let empty_effect_bytes = empty_effect.encode().unwrap();
        let empty_effect_object = OperationObject::new(
            base_manifest.workspace_id(),
            semantic_document,
            crate::oplog::ObjectKind::SemanticEffect,
            empty_effect_bytes.clone(),
        )
        .unwrap();
        let manifest = OperationBatch::new_with_causality(
            base_manifest.workspace_id(),
            base_manifest.lineage_digest(),
            no_op_batch,
            base_manifest.author_device_id(),
            base_manifest.author_session_id(),
            base_manifest.origin(),
            crate::oplog::BatchCausalDot::new(
                base_manifest.causal_dot().peer_id(),
                base_manifest.causal_dot().counter().checked_add(1).unwrap(),
            )
            .unwrap(),
            vec![base_batch],
            crate::oplog::FrontierV2::new(Vec::new()).unwrap(),
            crate::oplog::SemanticEffectDigest::of(&empty_effect_bytes),
            vec![empty_effect_object.descriptor().unwrap()],
        )
        .unwrap();
        assert!(
            manifest
                .required_objects()
                .iter()
                .all(|object| object.kind() != crate::oplog::ObjectKind::CrdtUpdate),
            "fixture no-op unexpectedly acquired a document head"
        );
        let mut provider = SharedProviderTransport::open(
            &fixture.request.provider_root,
            &fixture.request.provider_journal_root,
        )
        .unwrap();
        let descriptor = empty_effect_object.descriptor().unwrap();
        provider
            .publish_object(
                descriptor.content_digest(),
                &empty_effect_object.encode().unwrap(),
            )
            .unwrap();
        provider
            .publish_manifest(no_op_batch, &manifest.encode().unwrap())
            .unwrap();
        manifest
    }

    fn provider_object_paths(manifest: &OperationBatch) -> Vec<String> {
        manifest
            .required_objects()
            .iter()
            .map(|object| format!("objects/{}.object", object.content_digest()))
            .collect()
    }

    fn provider_complete_delivery_paths(manifest: &OperationBatch) -> Vec<String> {
        let mut delivered = provider_object_paths(manifest);
        delivered.push(format!("manifests/{}.manifest", manifest.batch_id()));
        delivered
    }

    fn direct_dependency_child_manifest(
        fixture: &ActivationFixture,
        batch_id: BatchId,
        dependency_batch: BatchId,
    ) -> OperationBatch {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let locally_authored =
            OperationBatch::decode(&store.read_manifest_bytes(batch_id).unwrap()).unwrap();
        OperationBatch::new_with_causality(
            locally_authored.workspace_id(),
            locally_authored.lineage_digest(),
            locally_authored.batch_id(),
            locally_authored.author_device_id(),
            locally_authored.author_session_id(),
            locally_authored.origin(),
            locally_authored.causal_dot(),
            vec![dependency_batch],
            locally_authored.dependency_frontier().clone(),
            locally_authored.semantic_effect_digest(),
            locally_authored.required_objects().to_vec(),
        )
        .unwrap()
    }

    fn publish_manifest_to_provider(fixture: &ActivationFixture, manifest: &OperationBatch) {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let mut provider = SharedProviderTransport::open(
            &fixture.request.provider_root,
            &fixture.request.provider_journal_root,
        )
        .unwrap();
        for object in manifest.required_objects() {
            provider
                .publish_object(
                    object.content_digest(),
                    &store.read_object_bytes(object.content_digest()).unwrap(),
                )
                .unwrap();
        }
        provider
            .publish_manifest(manifest.batch_id(), &manifest.encode().unwrap())
            .unwrap();
    }

    fn provider_manifest_recovery_paths(
        fixture: &ActivationFixture,
        batch_id: BatchId,
    ) -> (PathBuf, PathBuf, String, String) {
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let manifest_bytes = store.read_manifest_bytes(batch_id).unwrap();
        let link_relative =
            format!("{SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE}/{batch_id}.link");
        let blob_relative = format!(
            "{SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE}/{}.manifest",
            ContentDigest::of(&manifest_bytes)
        );
        (
            fixture
                .request
                .provider_root
                .join("outbox")
                .join(&link_relative),
            fixture
                .request
                .provider_root
                .join("outbox")
                .join(&blob_relative),
            link_relative,
            blob_relative,
        )
    }

