    #[test]
    fn shared_provider_archive_beyond_entry_and_byte_scan_caps_joins_incrementally() {
        let initiator = make_shared_fixture("provider-large-initiator", 0xb100);
        let mut joiner = make_shared_fixture("provider-large-joiner", 0xb100);
        joiner.request.identities.endpoint_id =
            ProjectionEndpointId::from_uuid(Uuid::from_u128(0xb110));
        joiner.request.identities.device_id = DeviceId::from_uuid(Uuid::from_u128(0xb111));
        joiner.request.identities.session_id = SessionId::from_uuid(Uuid::from_u128(0xb112));
        let descriptor = activate_and_prepare_shared(&initiator);

        let objects = initiator
            .request
            .provider_root
            .join("outbox")
            .join("objects");
        let mut immutable_bytes = 0_usize;
        for index in 0_u32..4_097 {
            let mut payload = vec![0x5a; 2_048];
            payload[..4].copy_from_slice(&index.to_be_bytes());
            let bytes = OperationObject::new(
                initiator.request.identities.workspace_id,
                DocumentId::from_uuid(Uuid::from_u128(0xc000 + u128::from(index))),
                crate::oplog::ObjectKind::AnnotatedBaseBlob,
                payload,
            )
            .unwrap()
            .encode()
            .unwrap();
            let digest = ContentDigest::of(&bytes);
            fs::write(objects.join(format!("{digest}.object")), &bytes).unwrap();
            immutable_bytes += bytes.len();
        }
        assert!(immutable_bytes > 8 * 1024 * 1024);
        assert!(fs::read_dir(&objects).unwrap().count() > 4_096);

        copy_provider_tree(
            &initiator.request.provider_root,
            &joiner.request.provider_root,
        );
        let provider_entries_per_cut = [
            "enrollment",
            SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE,
            SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE,
            SHARED_PROVIDER_MANIFEST_RECOVERY_LINKS_NAMESPACE,
            SHARED_PROVIDER_MANIFEST_RECOVERY_BLOBS_NAMESPACE,
            "manifests",
            "objects",
        ]
        .into_iter()
        .map(|namespace| {
            fs::read_dir(joiner.request.provider_root.join("outbox").join(namespace))
                .unwrap()
                .count()
        })
        .sum::<usize>();
        assert!(provider_entries_per_cut > 4_096);
        reset_shared_join_instrumentation(joiner.request.identities.workspace_id);
        let joiner_active = SyncRuntimeHandle::activate_or_resume_local(joiner.request.clone());
        let joiner_handle = joiner_active.handle.expect("joiner LocalActive");
        drive_initial_feed(&joiner_handle);
        joiner_handle
            .join_shared(descriptor)
            .expect("large provider archive must join incrementally");
        let join_traversal = shared_join_instrumentation(joiner.request.identities.workspace_id);
        assert_eq!(
            join_traversal.provider_entries,
            provider_entries_per_cut * 2,
            "{join_traversal:?}"
        );
        assert_eq!(
            join_traversal.max_retained_history_entries, 0,
            "{join_traversal:?}"
        );
        assert_eq!(
            join_traversal.provider_cut_comparisons, 1,
            "{join_traversal:?}"
        );
        assert_eq!(
            join_traversal.recovery_summary_comparisons, 1,
            "{join_traversal:?}"
        );
        assert!(
            join_traversal.recovery_relations <= join_traversal.provider_entries,
            "{join_traversal:?}"
        );
        assert!(
            join_traversal.local_recovery_point_reads <= join_traversal.local_entries,
            "{join_traversal:?}"
        );
        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&joiner.request)));
        assert_eq!(
            reopened.status().unwrap().shared_role,
            Some(SyncSharedRole::Joiner)
        );
        assert!(matches!(
            reopened.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    fn durable_shared_publication_survives_crash_before_provider_tick() {
        let fixture = make_shared_fixture("provider-publication-resume", 0xb200);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        drive_initial_feed(&reopened);
        let page_id = PageId::from_uuid(Uuid::from_u128(0xb210));
        let document_id = DocumentId::from_uuid(Uuid::from_u128(0xb211));
        let parent_batch = submit_durable(
            &reopened,
            vec![SemanticOperation::CreatePage {
                page_id,
                home_document_id: document_id,
                name: LogicalPageName::parse("Crash Resume Publication").unwrap(),
                path: ManagedPath::parse("notes/crash-resume-publication.md").unwrap(),
                kind: ManagedTextKind::Page,
            }],
        );
        let child_batch = submit_durable(
            &reopened,
            vec![SemanticOperation::CreatePage {
                page_id: PageId::from_uuid(Uuid::from_u128(0xb212)),
                home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xb213)),
                name: LogicalPageName::parse("Crash Resume Publication Child").unwrap(),
                path: ManagedPath::parse("notes/crash-resume-publication-child.md").unwrap(),
                kind: ManagedTextKind::Page,
            }],
        );
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        for batch_id in [parent_batch, child_batch] {
            assert!(matches!(
                store.inspect_batch(batch_id).unwrap(),
                crate::oplog::BatchInspection::Ready(_)
            ));
        }
        let parent_manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{parent_batch}.manifest"));
        let child_manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{child_batch}.manifest"));
        assert!(
            parent_manifest.is_file() && !child_manifest.exists(),
            "the second mutation's safety preflight must publish the accepted parent but leave the newly accepted child durable only in the local archive"
        );
        drop(reopened);

        let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(
            opened.status,
            SyncRuntimeOpenStatus::Active,
            "shared publication reopen failed: {:?}",
            opened.status
        );
        let resumed = opened.handle.expect("resumed SharedActive actor");
        for _ in 0..128 {
            let tick = resumed.tick().unwrap();
            if child_manifest.is_file() {
                assert!(
                    parent_manifest.is_file(),
                    "child manifest became visible before its publishable ancestor"
                );
                break;
            }
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                ),
                "durable pending publication must resume: {tick:?}"
            );
        }
        assert!(
            parent_manifest.is_file() && child_manifest.is_file(),
            "accepted local batch was not republished after reopen"
        );
        assert!(matches!(
            resumed.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    fn provider_object_physical_write_cut_requires_exact_journal_completion_before_manifest_and_head(
    ) {
        let fixture = make_shared_fixture("provider-object-durability-cut", 0xb215);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&handle);

        let (batch_id, ..) = submit_shared_page(
            &handle,
            0xb216,
            "Provider Object Durability Cut",
            "notes/provider-object-durability-cut.md",
            "exact bytes must complete their retry journal",
        );
        let store = ObjectStore::open(
            &fixture.request.archive_root,
            fixture.request.identities.workspace_id,
        )
        .unwrap();
        let manifest =
            OperationBatch::decode(&store.read_manifest_bytes(batch_id).unwrap()).unwrap();
        let unpublished_objects = manifest
            .required_objects()
            .iter()
            .filter_map(|object| {
                let digest = object.content_digest();
                let path = fixture
                    .request
                    .provider_root
                    .join(format!("outbox/objects/{digest}.object"));
                (!path.exists()).then(|| (digest, store.read_object_bytes(digest).unwrap(), path))
            })
            .collect::<Vec<_>>();
        assert!(!unpublished_objects.is_empty());
        let provider_manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{batch_id}.manifest"));
        let pending_records = fixture.request.provider_journal_root.join("records");
        let completed_records = fixture.request.provider_journal_root.join("completed");
        let mut blocked = None;
        let mut pending_before_cut = 0;
        let mut completed_before_cut = 0;
        for _ in 0..128 {
            let target_objects_before = unpublished_objects
                .iter()
                .filter(|(_, _, path)| path.is_file())
                .count();
            let pending_before = fs::read_dir(&pending_records).unwrap().count();
            let completed_before = fs::read_dir(&completed_records).unwrap().count();
            handle
                .install_provider_publication_after_physical_write_fault()
                .unwrap();
            match handle.tick().unwrap() {
                SyncRuntimeTick::RecoveryBlocked(detail) => {
                    let target_objects_after = unpublished_objects
                        .iter()
                        .filter(|(_, _, path)| path.is_file())
                        .count();
                    if target_objects_after > target_objects_before {
                        pending_before_cut = pending_before;
                        completed_before_cut = completed_before;
                        blocked = Some(detail);
                        break;
                    }
                }
                SyncRuntimeTick::Idle | SyncRuntimeTick::Recovering => {}
                other => panic!("unexpected publication cut tick: {other:?}"),
            }
            assert!(
                !provider_manifest.exists(),
                "manifest advanced while seeking the target object publication cut"
            );
        }
        assert!(
            blocked
                .as_deref()
                .is_some_and(|detail| detail.contains("injected provider publication")),
            "the physical-write cut did not block provider advancement: {blocked:?}"
        );
        let (_, object_bytes, provider_object) = unpublished_objects
            .iter()
            .find(|(_, _, path)| path.is_file())
            .expect("the target batch did not reach a physical object write");
        assert_eq!(fs::read(&provider_object).unwrap(), *object_bytes);
        assert!(fs::read_dir(&pending_records).unwrap().count() > pending_before_cut);
        assert_eq!(
            fs::read_dir(&completed_records).unwrap().count(),
            completed_before_cut
        );
        assert!(!provider_manifest.exists());
        assert!(!provider_head_covers(
            &fixture,
            fixture.request.identities.device_id,
            batch_id
        ));

        for _ in 0..128 {
            let tick = handle.tick().unwrap();
            assert!(
                matches!(tick, SyncRuntimeTick::Idle | SyncRuntimeTick::Recovering),
                "exact object retry failed: {tick:?}"
            );
            if provider_manifest.is_file() {
                break;
            }
        }
        assert_eq!(fs::read(&provider_object).unwrap(), *object_bytes);
        assert_eq!(
            fs::read_dir(&pending_records).unwrap().count(),
            pending_before_cut
        );
        assert!(fs::read_dir(&completed_records).unwrap().count() > completed_before_cut);
        assert!(provider_manifest.is_file());
        settle_shared_provider(&handle);
        assert!(provider_head_covers(
            &fixture,
            fixture.request.identities.device_id,
            batch_id
        ));

        let (conflict_batch, ..) = submit_shared_page(
            &handle,
            0xb21a,
            "Provider Object Exact Conflict",
            "notes/provider-object-exact-conflict.md",
            "conflicting physical bytes must fail closed",
        );
        let conflict_manifest =
            OperationBatch::decode(&store.read_manifest_bytes(conflict_batch).unwrap()).unwrap();
        let (conflict_digest, conflict_path) = conflict_manifest
            .required_objects()
            .iter()
            .map(|object| {
                let digest = object.content_digest();
                let path = fixture
                    .request
                    .provider_root
                    .join(format!("outbox/objects/{digest}.object"));
                (digest, path)
            })
            .find(|(_, path)| !path.exists())
            .expect("new batch must require an unpublished object");
        fs::write(&conflict_path, b"conflicting provider object bytes").unwrap();
        let conflict_provider_manifest = fixture
            .request
            .provider_root
            .join(format!("outbox/manifests/{conflict_batch}.manifest"));
        let mut conflict = None;
        for _ in 0..128 {
            match handle.tick().unwrap() {
                SyncRuntimeTick::RecoveryBlocked(detail) => {
                    conflict = Some(detail);
                    break;
                }
                SyncRuntimeTick::Idle | SyncRuntimeTick::Recovering => {}
                other => panic!("unexpected exact-conflict tick: {other:?}"),
            }
        }
        assert!(
            conflict.as_deref().is_some_and(|detail| {
                detail.contains("conflicting provider bytes")
                    && detail.contains(&conflict_digest.to_string())
            }),
            "conflicting existing bytes did not fail closed: {conflict:?}"
        );
        assert!(!conflict_provider_manifest.exists());
        assert!(!provider_head_covers(
            &fixture,
            fixture.request.identities.device_id,
            conflict_batch
        ));
        drop(handle);
    }

    #[test]
    fn frontier_head_crash_cuts_repair_before_safe_handoff() {
        let fixture = make_shared_fixture("provider-head-crash-cuts", 0xb240);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let heads = fixture
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);

        let first = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&first);
        let (manifest_cut_batch, ..) = submit_shared_page(
            &first,
            0xb250,
            "Manifest Before Head Cut",
            "notes/manifest-before-head-cut.md",
            "durable manifest before head",
        );
        publish_shared_batch(&first, &fixture, manifest_cut_batch);
        assert_eq!(
            fs::read_dir(&heads).unwrap().count(),
            1,
            "the cut must occur after the manifest but before its frontier head"
        );
        drop(first);

        let unsafe_repair =
            active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&unsafe_repair);
        assert_eq!(fs::read_dir(&heads).unwrap().count(), 1);
        let (retirement_cut_batch, ..) = submit_shared_page(
            &unsafe_repair,
            0xb260,
            "Head Before Retirement Cut",
            "notes/head-before-retirement-cut.md",
            "durable head before retirement",
        );
        publish_shared_batch(&unsafe_repair, &fixture, retirement_cut_batch);
        for _ in 0..16 {
            let tick = unsafe_repair.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "head publication failed before retirement cut: {tick:?}"
            );
            if fs::read_dir(&heads).unwrap().count() == 2 {
                break;
            }
        }
        assert_eq!(
            fs::read_dir(&heads).unwrap().count(),
            2,
            "the cut must retain both the durable new and superseded old head"
        );
        drop(unsafe_repair);

        let retirement_repair =
            active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&retirement_repair);
        assert_eq!(
            fs::read_dir(&heads).unwrap().count(),
            1,
            "unsafe reopen did not retire the exact superseded own-device head"
        );
        assert!(matches!(
            retirement_repair.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
    }

    #[test]
    fn startup_discovers_manifest_stranded_beyond_an_older_valid_frontier_head() {
        let (author, receiver, author_handle, receiver_handle) =
            joined_shared_pair("provider-stranded-manifest", 0xb270);
        assert!(matches!(
            receiver_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(receiver_handle);

        let author_heads = author
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);
        let older_heads = fs::read_dir(&author_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        assert!(!older_heads.is_empty());

        let (stranded_batch, ..) = submit_shared_page(
            &author_handle,
            0xb280,
            "Stranded Provider Manifest",
            "notes/stranded-provider-manifest.md",
            "published without a newer frontier head",
        );
        publish_shared_batch(&author_handle, &author, stranded_batch);
        let provider_manifest = author
            .request
            .provider_root
            .join(format!("outbox/manifests/{stranded_batch}.manifest"));
        let manifest = OperationBatch::decode(&fs::read(&provider_manifest).unwrap()).unwrap();
        assert_eq!(manifest.batch_id(), stranded_batch);
        for object in manifest.required_objects() {
            assert!(
                author
                    .request
                    .provider_root
                    .join(format!("outbox/objects/{}.object", object.content_digest()))
                    .is_file(),
                "manifest became visible before all of its immutable objects"
            );
        }
        let heads_at_crash = fs::read_dir(&author_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            heads_at_crash, older_heads,
            "the crash cut must retain only the older valid frontier head"
        );
        drop(author_handle);

        let receiver_manifest = receiver
            .request
            .provider_root
            .join(format!("outbox/manifests/{stranded_batch}.manifest"));
        assert!(!receiver_manifest.exists());
        copy_provider_tree(
            &author.request.provider_root,
            &receiver.request.provider_root,
        );
        assert!(receiver_manifest.is_file());
        assert!(!receiver
            .graph_root
            .join("notes/stranded-provider-manifest.md")
            .exists());

        reset_provider_traversal_instrumentation(receiver.request.identities.workspace_id);
        let receiver_startup =
            active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));
        settle_shared_provider(&receiver_startup);
        let traversal =
            provider_traversal_instrumentation(receiver.request.identities.workspace_id);
        assert!(
            receiver
                .graph_root
                .join("notes/stranded-provider-manifest.md")
                .is_file(),
            "normal startup did not discover the fully published stranded manifest: {traversal:?}"
        );
        let receiver_heads = receiver
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);
        assert!(
            fs::read_dir(&receiver_heads).unwrap().any(|entry| {
                let entry = entry.unwrap();
                let path = format!(
                    "{SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE}/{}",
                    entry.file_name().to_string_lossy()
                );
                SharedProviderFrontierHeadV1::decode(&path, &fs::read(entry.path()).unwrap())
                    .is_ok_and(|head| {
                        head.author_device_id() == receiver.request.identities.device_id
                            && head.frontier_tips().contains(&stranded_batch)
                    })
            }),
            "receiver did not durably publish a covering authenticated head"
        );
        let receiver_intents = receiver
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE);
        assert_eq!(
            fs::read_dir(&receiver_intents).unwrap().count(),
            0,
            "receiver's covering head did not retire the foreign stranded intent"
        );
        assert!(matches!(
            receiver_startup.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
    }

    #[test]
    fn normal_startup_chunks_every_foreign_intent_before_head_publication_and_safe() {
        const TEST_HEAD_SCAN_LIMIT: usize = 4;
        const STRANDED_BATCHES: usize = TEST_HEAD_SCAN_LIMIT + 2;

        let (author, receiver, author_handle, receiver_handle) =
            joined_shared_pair("provider-chunked-stranded-intents", 0xeb00);
        assert!(matches!(
            receiver_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(receiver_handle);

        let author_heads = author
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);
        let older_heads = fs::read_dir(&author_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        assert!(!older_heads.is_empty());

        let mut stranded = Vec::with_capacity(STRANDED_BATCHES);
        for index in 0..STRANDED_BATCHES {
            let path = format!("notes/chunked-stranded-intent-{index}.md");
            let (batch_id, ..) = submit_shared_page(
                &author_handle,
                0xeb20 + (index as u128) * 4,
                &format!("Chunked Stranded Intent {index}"),
                &path,
                "published without a newer frontier head",
            );
            publish_shared_batch(&author_handle, &author, batch_id);
            stranded.push((batch_id, path));
        }
        let heads_at_crash = fs::read_dir(&author_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            heads_at_crash, older_heads,
            "the fixture must retain only the older valid frontier head"
        );
        drop(author_handle);

        copy_provider_tree(
            &author.request.provider_root,
            &receiver.request.provider_root,
        );
        let intent_root = receiver
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE);
        let intent_entries = fs::read_dir(&intent_root)
            .unwrap()
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        assert_eq!(intent_entries.len(), STRANDED_BATCHES);
        for entry in intent_entries {
            let relative = format!(
                "{SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE}/{}",
                entry.file_name().to_string_lossy()
            );
            let intent = SharedProviderPublicationIntentV1::decode(
                &relative,
                &fs::read(entry.path()).unwrap(),
            )
            .unwrap();
            assert_eq!(
                intent.publisher_device_id(),
                author.request.identities.device_id
            );
            let manifest_path = receiver
                .request
                .provider_root
                .join(format!("outbox/manifests/{}.manifest", intent.batch_id()));
            let manifest_bytes = fs::read(&manifest_path).unwrap();
            assert_eq!(ContentDigest::of(&manifest_bytes), intent.manifest_digest());
            let manifest = OperationBatch::decode(&manifest_bytes).unwrap();
            assert_eq!(manifest.batch_id(), intent.batch_id());
            for object in manifest.required_objects() {
                assert!(
                    receiver
                        .request
                        .provider_root
                        .join(format!("outbox/objects/{}.object", object.content_digest()))
                        .is_file(),
                    "intent {} lacks a matching immutable object",
                    intent.batch_id()
                );
            }
        }

        let receiver_heads = receiver
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);
        let heads_before_startup = fs::read_dir(&receiver_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        PROVIDER_HEAD_SCAN_LIMIT_OVERRIDES.lock().unwrap().insert(
            receiver.request.identities.workspace_id,
            TEST_HEAD_SCAN_LIMIT,
        );
        reset_provider_traversal_instrumentation(receiver.request.identities.workspace_id);
        let receiver_startup =
            active_handle(SyncRuntimeHandle::open(reopen_request(&receiver.request)));

        for _ in 0..64 {
            let tick = receiver_startup.tick().unwrap();
            assert!(
                !matches!(
                    tick,
                    SyncRuntimeTick::RecoveryBlocked(_)
                        | SyncRuntimeTick::Blocked(_)
                        | SyncRuntimeTick::Terminal(_)
                        | SyncRuntimeTick::Failed(_)
                ),
                "chunked normal-startup discovery failed: {tick:?}"
            );
            if provider_traversal_instrumentation(receiver.request.identities.workspace_id)
                .head_scan_chunk_boundaries
                == 1
            {
                break;
            }
        }

        let first_boundary =
            provider_traversal_instrumentation(receiver.request.identities.workspace_id);
        assert_eq!(
            first_boundary.head_scan_chunk_boundaries, 1,
            "normal startup did not reach the isolated chunk boundary: {first_boundary:?}"
        );
        assert_eq!(
            first_boundary.head_scan_completions, 0,
            "a chunk boundary was mistaken for discovery EOF: {first_boundary:?}"
        );
        assert_eq!(
            first_boundary.full_scan_entries, 0,
            "a valid multi-chunk head+intent scan triggered a broad fallback"
        );
        let heads_at_first_boundary = fs::read_dir(&receiver_heads)
            .unwrap()
            .map(|entry| {
                let entry = entry.unwrap();
                (entry.file_name(), fs::read(entry.path()).unwrap())
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            heads_at_first_boundary, heads_before_startup,
            "head publication outran incomplete multi-chunk discovery"
        );
        assert!(
            matches!(
                activation_fixture_handoff(&receiver),
                EnrollmentDiscoveryHandoff::Unsafe { .. }
            ),
            "the first chunk boundary falsely published Safe"
        );

        settle_shared_provider(&receiver_startup);
        PROVIDER_HEAD_SCAN_LIMIT_OVERRIDES
            .lock()
            .unwrap()
            .remove(&receiver.request.identities.workspace_id);
        let completed =
            provider_traversal_instrumentation(receiver.request.identities.workspace_id);
        assert_eq!(
            completed.intent_entries, STRANDED_BATCHES,
            "one or more foreign intents were skipped across chunk boundaries: {completed:?}"
        );
        assert!(
            completed.head_scan_chunk_boundaries >= 2 && completed.head_scan_completions >= 1,
            "discovery did not resume through every chunk to actual EOF: {completed:?}"
        );
        assert_eq!(
            completed.full_scan_entries, 0,
            "valid multi-chunk discovery triggered a broad manifest/object scan"
        );
        for (batch_id, path) in &stranded {
            assert!(
                receiver.graph_root.join(path).is_file(),
                "observed intent batch {batch_id} did not converge"
            );
        }
        assert_eq!(receiver_startup.status().unwrap().provider_pending, 0);
        assert_eq!(
            fs::read_dir(&intent_root).unwrap().count(),
            0,
            "covering head publication did not retire every foreign intent"
        );
        let last_batch = stranded.last().unwrap().0;
        assert!(
            fs::read_dir(&receiver_heads).unwrap().any(|entry| {
                let entry = entry.unwrap();
                let path = format!(
                    "{SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE}/{}",
                    entry.file_name().to_string_lossy()
                );
                SharedProviderFrontierHeadV1::decode(&path, &fs::read(entry.path()).unwrap())
                    .is_ok_and(|head| {
                        head.author_device_id() == receiver.request.identities.device_id
                            && head.frontier_tips().contains(&last_batch)
                    })
            }),
            "receiver did not publish an authenticated head covering the final foreign batch"
        );
        assert!(matches!(
            receiver_startup.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
        assert_eq!(
            activation_fixture_handoff(&receiver),
            EnrollmentDiscoveryHandoff::Safe
        );
    }

    #[test]
    fn peer_retired_publication_intent_settles_and_later_delivery_reaches_safe() {
        let (author, peer, author_handle, peer_handle) =
            joined_shared_pair("provider-peer-retired-intent", 0xed00);
        let (first_batch, ..) = submit_shared_page(
            &author_handle,
            0xed20,
            "Peer Retired Intent",
            "notes/peer-retired-intent.md",
            "published before the author's covering head",
        );
        publish_shared_batch(&author_handle, &author, first_batch);

        let author_intents = author
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE);
        let intent_entry = fs::read_dir(&author_intents)
            .unwrap()
            .map(Result::unwrap)
            .next()
            .expect("author publication intent");
        assert_eq!(
            fs::read_dir(&author_intents).unwrap().count(),
            1,
            "fixture must retain exactly the newly published intent"
        );
        let intent_relative = format!(
            "{SHARED_PROVIDER_PUBLICATION_INTENTS_NAMESPACE}/{}",
            intent_entry.file_name().to_string_lossy()
        );

        copy_provider_tree(&author.request.provider_root, &peer.request.provider_root);
        peer_handle
            .observe_provider_paths(
                vec![
                    intent_relative.clone(),
                    format!("manifests/{first_batch}.manifest"),
                ],
                false,
            )
            .unwrap();
        settle_shared_provider(&peer_handle);
        assert!(
            !peer
                .request
                .provider_root
                .join("outbox")
                .join(&intent_relative)
                .exists(),
            "peer did not retire the foreign intent after publishing a covering head"
        );

        replicate_provider_file_event(
            &peer.request.provider_root,
            &author.request.provider_root,
            Path::new("outbox").join(&intent_relative).as_path(),
        );
        assert!(
            !author
                .request
                .provider_root
                .join("outbox")
                .join(&intent_relative)
                .exists(),
            "provider deletion did not replicate back to the author"
        );

        let (later_batch, ..) = submit_shared_page(
            &peer_handle,
            0xed40,
            "Later Peer Delivery",
            "notes/later-peer-delivery.md",
            "must not starve behind converged retirement",
        );
        publish_shared_batch(&peer_handle, &peer, later_batch);
        settle_shared_provider(&peer_handle);
        copy_provider_tree(&peer.request.provider_root, &author.request.provider_root);
        author_handle
            .observe_provider_paths(vec![format!("manifests/{later_batch}.manifest")], false)
            .unwrap();

        let mut blocked_ticks = 0;
        for _ in 0..512 {
            let tick = author_handle.tick().unwrap();
            if matches!(tick, SyncRuntimeTick::RecoveryBlocked(_)) {
                blocked_ticks += 1;
            }
            if matches!(tick, SyncRuntimeTick::Idle)
                && author_handle.status().unwrap().provider_pending == 0
            {
                break;
            }
        }
        assert_eq!(
            blocked_ticks, 0,
            "an already-absent retirement target permanently blocked provider progress"
        );
        assert!(
            author
                .graph_root
                .join("notes/later-peer-delivery.md")
                .is_file(),
            "later peer delivery starved behind the settled retirement"
        );

        let descriptor_bytes = fs::read(
            author
                .request
                .provider_root
                .join("outbox")
                .join(SHARED_ENROLLMENT_DESCRIPTOR_PATH),
        )
        .unwrap();
        let descriptor = SharedEnrollmentDescriptorV1::decode(&descriptor_bytes).unwrap();
        let manifest_bytes = fs::read(
            author
                .request
                .provider_root
                .join(format!("outbox/manifests/{later_batch}.manifest")),
        )
        .unwrap();
        let manifest = OperationBatch::decode(&manifest_bytes).unwrap();
        let replayed_intent = SharedProviderPublicationIntentV1::new(
            descriptor.workspace_id(),
            descriptor.lineage_digest(),
            descriptor.digest().unwrap(),
            peer.request.identities.device_id,
            manifest.author_device_id(),
            later_batch,
            ContentDigest::of(&manifest_bytes),
        )
        .unwrap();
        let replayed_intent_path = replayed_intent.path().unwrap();
        fs::write(
            author
                .request
                .provider_root
                .join("outbox")
                .join(&replayed_intent_path),
            replayed_intent.encode().unwrap(),
        )
        .unwrap();
        author_handle
            .observe_provider_paths(vec![replayed_intent_path.clone()], false)
            .unwrap();
        assert!(matches!(
            author_handle.tick().unwrap(),
            SyncRuntimeTick::Recovering
        ));
        fs::remove_file(
            author
                .request
                .provider_root
                .join("outbox")
                .join(&replayed_intent_path),
        )
        .unwrap();
        assert!(
            !matches!(
                author_handle.tick().unwrap(),
                SyncRuntimeTick::RecoveryBlocked(_)
            ),
            "queued replayed-intent retirement did not settle after provider deletion"
        );
        settle_shared_provider(&author_handle);
        assert!(matches!(
            author_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
    }

    #[test]
    fn absent_superseded_head_settles_and_reappeared_head_retires_again() {
        let fixture = make_shared_fixture("provider-idempotent-head-retirement", 0xeda0);
        let _descriptor = activate_and_prepare_shared(&fixture);
        let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
        settle_shared_provider(&handle);

        let heads = fixture
            .request
            .provider_root
            .join("outbox")
            .join(SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE);
        let old_entry = fs::read_dir(&heads).unwrap().next().unwrap().unwrap();
        let old_name = old_entry.file_name();
        let old_path = old_entry.path();
        let old_bytes = fs::read(&old_path).unwrap();
        let old_relative = format!(
            "{SHARED_PROVIDER_FRONTIER_HEADS_NAMESPACE}/{}",
            old_name.to_string_lossy()
        );

        let (batch_id, ..) = submit_shared_page(
            &handle,
            0xedc0,
            "Idempotent Head Retirement",
            "notes/idempotent-head-retirement.md",
            "publish the replacement before retiring the old head",
        );
        publish_shared_batch(&handle, &fixture, batch_id);
        for _ in 0..64 {
            if fs::read_dir(&heads).unwrap().count() == 2 {
                break;
            }
            let tick = handle.tick().unwrap();
            assert!(
                !matches!(tick, SyncRuntimeTick::RecoveryBlocked(_)),
                "replacement head publication blocked: {tick:?}"
            );
        }
        assert_eq!(
            fs::read_dir(&heads).unwrap().count(),
            2,
            "fixture did not stop between replacement publication and old-head retirement"
        );

        fs::remove_file(&old_path).unwrap();
        settle_shared_provider(&handle);
        assert_eq!(
            fs::read_dir(&heads).unwrap().count(),
            1,
            "an already-absent superseded head did not settle"
        );

        fs::write(&old_path, &old_bytes).unwrap();
        handle
            .observe_provider_paths(vec![old_relative.clone()], false)
            .unwrap();
        settle_shared_provider(&handle);
        assert!(
            !old_path.exists(),
            "redelivered superseded head was not retired"
        );

        let removed = fixture.request.provider_root.join("outbox").join("removed");
        let retired_old = fs::read_dir(&removed)
            .unwrap()
            .map(Result::unwrap)
            .find(|entry| fs::read(entry.path()).is_ok_and(|bytes| bytes == old_bytes))
            .expect("completed old-head retirement diagnostic");
        fs::remove_file(retired_old.path()).unwrap();
        fs::write(&old_path, &old_bytes).unwrap();
        handle
            .observe_provider_paths(vec![old_relative], false)
            .unwrap();
        settle_shared_provider(&handle);
        assert!(
            !old_path.exists(),
            "reappeared head was not retired again after completed-retirement evidence loss"
        );
        assert!(matches!(
            handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(snapshot)) if snapshot.provider_pending == 0
        ));
    }

    #[test]
    fn two_offline_devices_union_reordered_frontier_heads_without_history_scan() {
        let (first, second, first_handle, second_handle) =
            joined_shared_pair("provider-two-offline-heads", 0xb2a0);
        assert!(matches!(
            first_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let first_offline = active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let (first_batch, ..) = submit_shared_page(
            &first_offline,
            0xb2c0,
            "First Offline Tail",
            "notes/first-offline-tail.md",
            "first offline device",
        );
        publish_shared_batch(&first_offline, &first, first_batch);
        settle_shared_provider(&first_offline);
        assert!(matches!(
            first_offline.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        copy_provider_tree(&second.request.provider_root, &first.request.provider_root);
        reset_provider_traversal_instrumentation(second.request.identities.workspace_id);
        let second_merged = active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        settle_shared_provider(&second_merged);
        let second_traversal =
            provider_traversal_instrumentation(second.request.identities.workspace_id);
        assert_eq!(
            second_traversal.full_scan_entries, 0,
            "{second_traversal:?}"
        );
        assert_eq!(second_traversal.exact_manifests, 1, "{second_traversal:?}");
        assert!(
            second
                .graph_root
                .join("notes/first-offline-tail.md")
                .is_file(),
            "second device did not traverse the first device's unseen head"
        );
        assert!(
            second_traversal.head_entries >= 2,
            "both offline devices' reordered head records were not unioned: {second_traversal:?}"
        );
    }

    #[test]
    fn two_offline_authors_union_frontier_heads_converge_without_return_first() {
        let (first, second, first_handle, second_handle) =
            joined_shared_pair("provider-two-offline-authors", 0xe400);
        assert!(matches!(
            first_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let first_offline = active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let (first_batch, ..) = submit_shared_page(
            &first_offline,
            0xe420,
            "First Offline Page",
            "notes/first-offline-page.md",
            "first offline device",
        );
        publish_shared_batch(&first_offline, &first, first_batch);
        settle_shared_provider(&first_offline);
        assert!(matches!(
            first_offline.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let second_offline =
            active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        let (second_batch, ..) = submit_shared_page(
            &second_offline,
            0xe430,
            "Second Offline Page",
            "notes/second-offline-page.md",
            "second offline device",
        );
        publish_shared_batch(&second_offline, &second, second_batch);
        settle_shared_provider(&second_offline);
        assert!(matches!(
            second_offline.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        let first_manifest = OperationBatch::decode(
            &fs::read(
                first
                    .request
                    .provider_root
                    .join(format!("outbox/manifests/{first_batch}.manifest")),
            )
            .unwrap(),
        )
        .unwrap();
        let second_manifest = OperationBatch::decode(
            &fs::read(
                second
                    .request
                    .provider_root
                    .join(format!("outbox/manifests/{second_batch}.manifest")),
            )
            .unwrap(),
        )
        .unwrap();
        assert_eq!(
            first_manifest.causal_dependency_heads(),
            second_manifest.causal_dependency_heads(),
            "both offline authors must branch from the same durable base"
        );
        assert_eq!(first_manifest.causal_dependency_heads().len(), 1);

        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        copy_provider_tree(&second.request.provider_root, &first.request.provider_root);
        let first_merged = active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let second_merged = active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        for _ in 0..1_024 {
            let first_tick = first_merged.tick().unwrap();
            let second_tick = second_merged.tick().unwrap();
            if matches!(first_tick, SyncRuntimeTick::Idle)
                && matches!(second_tick, SyncRuntimeTick::Idle)
                && first_merged.status().unwrap().provider_pending == 0
                && second_merged.status().unwrap().provider_pending == 0
            {
                break;
            }
        }
        assert_eq!(
            first_merged.status().unwrap().provider_pending,
            0,
            "first author did not settle the unioned offline branches"
        );
        assert_eq!(
            second_merged.status().unwrap().provider_pending,
            0,
            "second author did not settle the unioned offline branches"
        );
        for graph_root in [&first.graph_root, &second.graph_root] {
            assert!(graph_root.join("notes/first-offline-page.md").is_file());
            assert!(graph_root.join("notes/second-offline-page.md").is_file());
        }
        assert!(matches!(
            first_merged.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_merged.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    fn shared_provider_new_nested_path_converges_after_duplicate_delivery_and_receiver_crash() {
        let (first, second, first_handle, second_handle) =
            joined_shared_pair("provider-new-nested-path-crash", 0xe500);
        let path = "notes/provider-created/deep/physical-source.md";
        fs::create_dir_all(first.graph_root.join(path).parent().unwrap()).unwrap();
        assert!(first.graph_root.join("notes").is_dir());
        assert!(second.graph_root.join("notes").is_dir());
        assert!(!second.graph_root.join(path).parent().unwrap().exists());
        assert!(matches!(
            first_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        fs::write(
            first.graph_root.join(path),
            b"- provider-created nested page\n",
        )
        .unwrap();
        let source_handle = active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let admission = drain_until_settled(&source_handle);
        assert!(
            admitted_an_epoch(&admission),
            "source external edit did not enter immutable history: {admission:?}"
        );
        settle_shared_provider(&source_handle);
        let source = load_editor_named(&source_handle, "physical-source", SyncPageKind::Page);
        assert_eq!(source.name, "physical-source");
        assert_eq!(source.path, path);
        assert!(source
            .blocks
            .iter()
            .any(|block| block.content == "provider-created nested page"));
        assert!(matches!(
            source_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        let graph = Graph::open(&first.graph_root);
        let parsed_entry = graph
            .list_pages()
            .into_iter()
            .find(|entry| entry.rel_path == path)
            .expect("independent parser lost the source page");
        let parsed_source = graph.load_page(&parsed_entry).unwrap();
        assert_eq!(parsed_source.name, source.name);
        assert!(parsed_source
            .blocks
            .iter()
            .any(|block| block.raw.contains("provider-created nested page")));

        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        second_handle.observe_provider().unwrap();
        for _ in 0..32 {
            let _ = second_handle.tick().unwrap();
        }
        drop(second_handle);

        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        let receiver = active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        receiver.observe_provider().unwrap();
        let mut last_tick = SyncRuntimeTick::Idle;
        for _ in 0..256 {
            last_tick = receiver.tick().unwrap();
            if receiver.status().unwrap().provider_pending == 0 {
                break;
            }
        }
        let status = receiver.status().unwrap();
        assert_eq!(
            status.provider_pending, 0,
            "eventual duplicate delivery plus receiver restart did not converge: \
             {status:?}, last tick {last_tick:?}"
        );
        assert_eq!(
            fs::read(second.graph_root.join(path)).unwrap(),
            fs::read(first.graph_root.join(path)).unwrap()
        );
    }

    #[test]
    fn concurrent_offline_canonical_equivalent_editor_titles_preserve_exact_semantics() {
        assert_eq!(
            crate::refs::page_key("Café Plan"),
            crate::refs::page_key("Cafe\u{301} Plan"),
            "fixture titles must share one canonical identity"
        );
        let (first, second, first_handle, second_handle) =
            joined_empty_shared_pair("concurrent-editor-title-unicode", 0xe700);
        let target_path = "notes/physical-target.markdown";
        let target_page_id =
            admit_shared_page(&first_handle, &first, target_path, b"- target body\n");
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        second_handle.observe_provider().unwrap();
        settle_shared_provider(&second_handle);

        for (handle, title) in [
            (&first_handle, "Café Plan"),
            (&second_handle, "Cafe\u{301} Plan"),
        ] {
            let target = load_editor_id(handle, target_page_id);
            assert_eq!(
                retain_editor_save(
                    handle,
                    SyncEditorSaveRequest {
                        target: SyncEditorSaveTarget::Existing {
                            page_id: target.page_id,
                            revision: target.revision,
                        },
                        preamble: Some(format!("title:: {title}")),
                        blocks: target.blocks,
                    },
                ),
                target_page_id
            );
            settle_shared_provider(handle);
        }
        assert!(matches!(
            first_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(first_handle);
        drop(second_handle);

        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        copy_provider_tree(&second.request.provider_root, &first.request.provider_root);
        let first_merged = active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let second_merged = active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        settle_shared_provider(&first_merged);
        settle_shared_provider(&second_merged);
        let first_status = first_merged.status().unwrap();
        let second_status = second_merged.status().unwrap();
        assert_eq!(first_status.provider_pending, 0);
        assert_eq!(second_status.provider_pending, 0);
        let load = |handle: &SyncRuntimeHandle| {
            handle
                .load_editor_page(SyncEditorLoadRequest {
                    page: SyncEditorPageSelector::PageId {
                        page_id: target_page_id.to_string(),
                    },
                })
                .unwrap_or_else(|error| {
                    panic!(
                        "converged editor load failed: {error:?}; first={first_status:?}; \
                         second={second_status:?}"
                    )
                })
        };
        let first_page = match load(&first_merged) {
            SyncEditorLoadOutcome::Loaded { page } => page,
            outcome => panic!(
                "first replica did not retain the concurrently titled page: {outcome:?}; \
                 first={first_status:?}; second={second_status:?}"
            ),
        };
        let second_page = match load(&second_merged) {
            SyncEditorLoadOutcome::Loaded { page } => page,
            outcome => panic!(
                "second replica did not retain the concurrently titled page: {outcome:?}; \
                 first={first_status:?}; second={second_status:?}"
            ),
        };
        assert_eq!(
            first_page.name, second_page.name,
            "same provider union selected different exact authored titles; \
             first={first_status:?}; second={second_status:?}"
        );
        assert!(
            ["Café Plan", "Cafe\u{301} Plan"].contains(&first_page.name.as_str()),
            "winner must preserve one authored UTF-8 spelling"
        );
        assert_eq!(first_page.preamble, second_page.preamble);
        assert_eq!(
            first_page.preamble.as_deref(),
            Some(format!("title:: {}", first_page.name).as_str())
        );
        for graph_root in [&first.graph_root, &second.graph_root] {
            let parsed = Graph::open(graph_root)
                .list_pages()
                .into_iter()
                .find(|entry| entry.rel_path == target_path)
                .expect("independent graph parser lost the title target");
            assert_eq!(
                parsed.name, first_page.name,
                "independent graph bytes disagree with the effective title at {graph_root:?}; \
                 first={first_status:?}; second={second_status:?}"
            );
        }
        assert_eq!(
            fs::read(first.graph_root.join(target_path)).unwrap(),
            fs::read(second.graph_root.join(target_path)).unwrap()
        );
        for handle in [&first_merged, &second_merged] {
            let sqlite_page = match handle
                .query(SyncRuntimeQueryRequest::ListPages {
                    page_kind: None,
                    limit: MAX_MATERIALIZATION_QUERY_ROWS,
                })
                .unwrap()
            {
                SyncRuntimeQueryReply::Pages(pages) => pages
                    .into_iter()
                    .find(|page| page.page_id == target_page_id.to_string())
                    .expect("SQLite lost the title target"),
                other => panic!("SQLite page list returned the wrong reply: {other:?}"),
            };
            assert_eq!(sqlite_page.name, first_page.name);
            assert_eq!(sqlite_page.path, target_path);
        }

        let (unrelated_batch, _, _, _) = submit_shared_page(
            &first_merged,
            0xe740,
            "Unrelated After Title Race",
            "notes/unrelated-after-title-race.md",
            "unrelated catalog state must not change the selected exact title",
        );
        publish_shared_batch(&first_merged, &first, unrelated_batch);
        settle_shared_provider(&first_merged);
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        second_merged.observe_provider().unwrap();
        settle_shared_provider(&second_merged);
        assert_eq!(
            load_editor_id(&first_merged, target_page_id).name,
            first_page.name
        );
        assert_eq!(
            load_editor_id(&second_merged, target_page_id).name,
            first_page.name
        );

        let provider_manifest_count = || {
            fs::read_dir(first.request.provider_root.join("outbox/manifests"))
                .unwrap()
                .count()
        };
        let manifests_before_noop = provider_manifest_count();
        first_merged
            .observe_watcher(vec![
                SyncWatcherObservation::managed_path(target_path).unwrap()
            ])
            .unwrap();
        settle_exact_feed(&first_merged)
            .unwrap_or_else(|state| panic!("unchanged title reimport did not settle: {state:?}"));
        assert_eq!(
            provider_manifest_count(),
            manifests_before_noop,
            "unchanged title reimport published a semantic batch"
        );
        assert!(matches!(
            first_merged.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_merged.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(first_merged);
        drop(second_merged);

        let first_restarted =
            active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
        let second_restarted =
            active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
        drive_initial_feed(&first_restarted);
        drive_initial_feed(&second_restarted);
        let first_after_restart = load_editor_id(&first_restarted, target_page_id);
        let second_after_restart = load_editor_id(&second_restarted, target_page_id);
        assert_eq!(first_after_restart.name, first_page.name);
        assert_eq!(second_after_restart.name, first_page.name);
        assert_eq!(first_after_restart.preamble, first_page.preamble);
        assert_eq!(second_after_restart.preamble, first_page.preamble);
        for handle in [&first_restarted, &second_restarted] {
            let sqlite_page = match handle
                .query(SyncRuntimeQueryRequest::ListPages {
                    page_kind: None,
                    limit: MAX_MATERIALIZATION_QUERY_ROWS,
                })
                .unwrap()
            {
                SyncRuntimeQueryReply::Pages(pages) => pages
                    .into_iter()
                    .find(|page| page.page_id == target_page_id.to_string())
                    .expect("second-restart SQLite lost the title target"),
                other => panic!("second-restart SQLite returned the wrong reply: {other:?}"),
            };
            assert_eq!(sqlite_page.name, first_page.name);
            assert_eq!(sqlite_page.path, target_path);
        }
        assert!(matches!(
            first_restarted.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_restarted.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    fn concurrent_explicit_and_filename_fallback_titles_converge_in_both_winner_directions() {
        fn run_case(label: &str, seed: u128, first_is_explicit: bool) -> bool {
            let (first, second, first_handle, second_handle) =
                joined_empty_shared_pair(label, seed);
            let target_path = "notes/Café Plan.md";
            let target_page_id = admit_shared_page(
                &first_handle,
                &first,
                target_path,
                b"title:: Concurrent Original\n\n- explicit versus fallback body\n",
            );
            copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
            second_handle.observe_provider().unwrap();
            settle_shared_provider(&second_handle);

            for (handle, explicit) in [
                (&first_handle, first_is_explicit),
                (&second_handle, !first_is_explicit),
            ] {
                let target = load_editor_id(handle, target_page_id);
                assert_eq!(
                    retain_editor_save(
                        handle,
                        SyncEditorSaveRequest {
                            target: SyncEditorSaveTarget::Existing {
                                page_id: target.page_id,
                                revision: target.revision,
                            },
                            preamble: explicit.then(|| "title:: Cafe\u{301} Plan".to_owned()),
                            blocks: target.blocks,
                        },
                    ),
                    target_page_id
                );
                settle_shared_provider(handle);
            }
            assert!(matches!(
                first_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            assert!(matches!(
                second_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            drop(first_handle);
            drop(second_handle);

            copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
            copy_provider_tree(&second.request.provider_root, &first.request.provider_root);
            let first_merged =
                active_handle(SyncRuntimeHandle::open(reopen_request(&first.request)));
            let second_merged =
                active_handle(SyncRuntimeHandle::open(reopen_request(&second.request)));
            settle_shared_provider(&first_merged);
            settle_shared_provider(&second_merged);
            let first_page = load_editor_id(&first_merged, target_page_id);
            let second_page = load_editor_id(&second_merged, target_page_id);
            assert_eq!(first_page.name, second_page.name);
            assert_eq!(first_page.preamble, second_page.preamble);
            let explicit_won = first_page.name == "Cafe\u{301} Plan";
            if explicit_won {
                assert_eq!(
                    first_page.preamble.as_deref(),
                    Some("title:: Cafe\u{301} Plan")
                );
            } else {
                assert_eq!(first_page.name, "Café Plan");
                assert!(
                    first_page.preamble.as_deref().is_none_or(|preamble| {
                        !preamble.lines().any(|line| {
                            crate::doc::parse_property_line(line)
                                .is_some_and(|(key, _)| key.eq_ignore_ascii_case("title"))
                        })
                    }),
                    "selected filename fallback retained an explicit title"
                );
            }
            for graph_root in [&first.graph_root, &second.graph_root] {
                let parsed = Graph::open(graph_root)
                    .list_pages()
                    .into_iter()
                    .find(|entry| entry.rel_path == target_path)
                    .expect("explicit/fallback convergence lost the physical page");
                assert_eq!(parsed.name, first_page.name);
            }
            assert_eq!(
                fs::read(first.graph_root.join(target_path)).unwrap(),
                fs::read(second.graph_root.join(target_path)).unwrap()
            );
            assert!(matches!(
                first_merged.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            assert!(matches!(
                second_merged.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            explicit_won
        }

        let first_assignment = run_case("explicit-fallback-first-explicit", 0xe800, true);
        let reversed_assignment = run_case("explicit-fallback-first-fallback", 0xe900, false);
        assert_ne!(
            first_assignment, reversed_assignment,
            "swapping explicit/fallback over fixed endpoint provenance must exercise both winners"
        );
    }

    #[test]
    fn effective_title_projection_authority_is_point_bounded_with_a_wide_unrelated_frontier() {
        const UNRELATED_PAGES: usize = 24;
        // Crash-cut hooks are keyed by workspace across the test process, so
        // this fixture must not alias a provider recovery-cut fixture.
        let (first, second, first_handle, second_handle) =
            joined_shared_pair("effective-title-point-authority", 0xfaa00);
        let target_path = "notes/effective-title-point-target.md";
        let (target_batch, target_page_id, _, _) = submit_shared_page(
            &first_handle,
            0xea20,
            "Point Authority Original",
            target_path,
            "point authority target",
        );
        publish_shared_batch(&first_handle, &first, target_batch);
        settle_shared_provider(&first_handle);
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        second_handle.observe_provider().unwrap();
        settle_shared_provider(&second_handle);

        for index in 0..UNRELATED_PAGES {
            let seed = 0xeb00 + (index as u128) * 4;
            let (batch, ..) = submit_shared_page(
                &first_handle,
                seed,
                &format!("Point Authority Unrelated {index}"),
                &format!("notes/point-authority-unrelated-{index}.md"),
                "unrelated accepted-frontier payload",
            );
            publish_shared_batch(&first_handle, &first, batch);
        }
        settle_shared_provider(&first_handle);
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        second_handle.observe_provider().unwrap();
        settle_shared_provider(&second_handle);

        for (handle, title) in [
            (&first_handle, "Café Point Authority"),
            (&second_handle, "Cafe\u{301} Point Authority"),
        ] {
            let target = load_editor_id(handle, target_page_id);
            assert_eq!(
                retain_editor_save(
                    handle,
                    SyncEditorSaveRequest {
                        target: SyncEditorSaveTarget::Existing {
                            page_id: target.page_id,
                            revision: target.revision,
                        },
                        preamble: Some(format!("title:: {title}")),
                        blocks: target.blocks,
                    },
                ),
                target_page_id
            );
            settle_shared_provider(handle);
        }

        let first_before = first_handle.engine_instrumentation().unwrap();
        let second_before = second_handle.engine_instrumentation().unwrap();
        copy_provider_tree(&first.request.provider_root, &second.request.provider_root);
        copy_provider_tree(&second.request.provider_root, &first.request.provider_root);
        first_handle.observe_provider().unwrap();
        second_handle.observe_provider().unwrap();
        settle_shared_provider(&first_handle);
        settle_shared_provider(&second_handle);
        let first_after = first_handle.engine_instrumentation().unwrap();
        let second_after = second_handle.engine_instrumentation().unwrap();

        let authority_calls = first_after.effective_title_projection_authority_calls
            - first_before.effective_title_projection_authority_calls
            + second_after.effective_title_projection_authority_calls
            - second_before.effective_title_projection_authority_calls;
        let point_proofs = first_after.effective_title_projection_point_proofs
            - first_before.effective_title_projection_point_proofs
            + second_after.effective_title_projection_point_proofs
            - second_before.effective_title_projection_point_proofs;
        let frontier_head_visits = first_after.effective_title_projection_frontier_head_visits
            - first_before.effective_title_projection_frontier_head_visits
            + second_after.effective_title_projection_frontier_head_visits
            - second_before.effective_title_projection_frontier_head_visits;
        assert!(
            authority_calls > 0,
            "fixture did not exercise transient effective-title projection authority"
        );
        assert_eq!(
            point_proofs,
            authority_calls * 3,
            "effective-title authority work must remain a fixed three point proofs per authentication"
        );
        assert_eq!(
            frontier_head_visits, 0,
            "effective-title authority enumerated direct dependency heads"
        );
        for (calls_before, calls_after, instrumentation) in [
            (
                first_before.effective_title_projection_authority_calls,
                first_after.effective_title_projection_authority_calls,
                first_after,
            ),
            (
                second_before.effective_title_projection_authority_calls,
                second_after.effective_title_projection_authority_calls,
                second_after,
            ),
        ] {
            if calls_after > calls_before {
                assert!(
                    instrumentation.effective_title_projection_max_accepted_documents
                        >= UNRELATED_PAGES + 1,
                    "point authority did not run against the deliberately wide accepted frontier"
                );
            }
        }

        let first_page = load_editor_id(&first_handle, target_page_id);
        let second_page = load_editor_id(&second_handle, target_page_id);
        assert_eq!(first_page.name, second_page.name);
        assert_eq!(first_page.preamble, second_page.preamble);
        assert!(["Café Point Authority", "Cafe\u{301} Point Authority"]
            .contains(&first_page.name.as_str()));
        assert_eq!(
            first_page.preamble.as_deref(),
            Some(format!("title:: {}", first_page.name).as_str())
        );
        for graph_root in [&first.graph_root, &second.graph_root] {
            let parsed = Graph::open(graph_root)
                .list_pages()
                .into_iter()
                .find(|entry| entry.rel_path == target_path)
                .expect("wide-frontier convergence lost the physical target");
            assert_eq!(parsed.name, first_page.name);
        }
        assert_eq!(
            fs::read(first.graph_root.join(target_path)).unwrap(),
            fs::read(second.graph_root.join(target_path)).unwrap()
        );
        assert!(matches!(
            first_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        assert!(matches!(
            second_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

