    #[test]
    #[ignore = "manual release benchmark: 1,000-page direct Markdown versus managed reopen"]
    fn managed_startup_reopen_1000_page_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_startup_reopen_1000_page_manual_benchmark -- --ignored --nocapture"
        );
        const NAMED_PAGE: &str = "Synthetic 0";
        let additional_pages = std::env::var("TINE_MANAGED_STARTUP_BENCH_PAGES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|pages| *pages > 0)
            .unwrap_or(997);
        let expected_pages = additional_pages + 3;
        let blocks_per_page = std::env::var("TINE_MANAGED_STARTUP_BENCH_BLOCKS_PER_PAGE")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|blocks| *blocks > 0)
            .unwrap_or(10);
        let runs = std::env::var("TINE_MANAGED_STARTUP_BENCH_RUNS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|runs| *runs > 0)
            .unwrap_or(5);
        let fixture = ActivationFixture::scaled_with_blocks(
            "managed-startup-reopen-1000-page",
            0xa0d0,
            additional_pages,
            blocks_per_page,
        );
        let source = user_graph_bytes(&fixture.graph_root);
        let (source_files, source_bytes, blocks) = activation_source_counts(&fixture.graph_root);
        assert_eq!(source_files, expected_pages);
        assert!(source_bytes > 0 && blocks >= additional_pages * blocks_per_page);

        // Activation/import is intentionally outside the comparison. It happens
        // once, then a successful Safe handoff leaves each measured managed open
        // as a fresh runtime reopening the same user-facing graph bytes.
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let activation_handle = activated
            .handle
            .expect("activation retains a runtime handle");
        drive_initial_feed(&activation_handle);
        assert!(
            matches!(
                activation_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ),
            "activation must finish with a Safe handoff before reopen measurement"
        );
        drop(activation_handle);
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            source,
            "activation and the benchmark must preserve identical graph bytes"
        );

        let mut direct = Vec::with_capacity(runs);
        let mut managed = Vec::with_capacity(runs);
        for run in 0..runs {
            // Alternate first position to reduce a warm-page-cache advantage for
            // either backend; each sample still constructs a fresh Graph or actor.
            let (direct_receipt, managed_receipt) = if run % 2 == 0 {
                let direct =
                    measure_direct_startup(&fixture.graph_root, NAMED_PAGE, expected_pages);
                let managed = measure_managed_startup(&fixture.request, NAMED_PAGE, expected_pages);
                (direct, managed)
            } else {
                let managed = measure_managed_startup(&fixture.request, NAMED_PAGE, expected_pages);
                let direct =
                    measure_direct_startup(&fixture.graph_root, NAMED_PAGE, expected_pages);
                (direct, managed)
            };
            assert_eq!(
                direct_receipt.named_page, managed_receipt.named_page,
                "direct and managed first named-page loads must have identical user-facing semantics"
            );
            assert_eq!(
                direct_receipt.graph_state, managed_receipt.graph_state,
                "direct whole-graph parse and managed whole-graph query must expose the same pages"
            );
            eprintln!(
                "managed_startup_bench run={} direct_open_ms={:.3} direct_first_named_page_ms={:.3} direct_whole_graph_on_demand_ms={:.3} direct_paced_background_warmer_ms={:.3} managed_open_ms={:.3} managed_first_named_page_ms={:.3} managed_whole_graph_on_demand_ms={:.3} managed_deferred_catch_up_and_shutdown_ms={:.3} managed_resume={:?} managed_open_phases: {} managed_promoted_open_phases: {}",
                run + 1,
                startup_ms(direct_receipt.milestones.backend_open),
                startup_ms(direct_receipt.milestones.first_named_page),
                startup_ms(direct_receipt.milestones.whole_graph_on_demand),
                startup_ms(direct_receipt.paced_background_warmer),
                startup_ms(managed_receipt.milestones.backend_open),
                startup_ms(managed_receipt.milestones.first_named_page),
                startup_ms(managed_receipt.milestones.whole_graph_on_demand),
                startup_ms(managed_receipt.deferred_catch_up_and_shutdown),
                managed_receipt.resume,
                startup_open_phase_receipt(&managed_receipt.open),
                startup_promoted_open_phase_receipt(&managed_receipt.promoted),
            );
            direct.push(direct_receipt);
            managed.push(managed_receipt);
        }
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            source,
            "all measured reopen cycles must preserve graph bytes"
        );

        let direct_open = startup_median(
            &direct
                .iter()
                .map(|receipt| receipt.milestones.backend_open)
                .collect::<Vec<_>>(),
        );
        let direct_first_page = startup_median(
            &direct
                .iter()
                .map(|receipt| receipt.milestones.first_named_page)
                .collect::<Vec<_>>(),
        );
        let direct_whole_graph = startup_median(
            &direct
                .iter()
                .map(|receipt| receipt.milestones.whole_graph_on_demand)
                .collect::<Vec<_>>(),
        );
        let direct_warmer = startup_median(
            &direct
                .iter()
                .map(|receipt| receipt.paced_background_warmer)
                .collect::<Vec<_>>(),
        );
        let managed_open = startup_median(
            &managed
                .iter()
                .map(|receipt| receipt.milestones.backend_open)
                .collect::<Vec<_>>(),
        );
        let managed_first_page = startup_median(
            &managed
                .iter()
                .map(|receipt| receipt.milestones.first_named_page)
                .collect::<Vec<_>>(),
        );
        let managed_whole_graph = startup_median(
            &managed
                .iter()
                .map(|receipt| receipt.milestones.whole_graph_on_demand)
                .collect::<Vec<_>>(),
        );
        eprintln!(
            "managed_startup_bench median runs={} fixture_files={} fixture_bytes={} fixture_blocks={} direct_open_ms={:.3} direct_first_named_page_ms={:.3} direct_whole_graph_on_demand_ms={:.3} direct_paced_background_warmer_ms={:.3} managed_open_ms={:.3} managed_first_named_page_ms={:.3} managed_whole_graph_on_demand_ms={:.3}",
            runs,
            source_files,
            source_bytes,
            blocks,
            startup_ms(direct_open),
            startup_ms(direct_first_page),
            startup_ms(direct_whole_graph),
            startup_ms(direct_warmer),
            startup_ms(managed_open),
            startup_ms(managed_first_page),
            startup_ms(managed_whole_graph),
        );
    }

    #[test]
    #[ignore = "manual release benchmark: settled broad reconciliation and safe shutdown"]
    fn managed_reconciliation_and_shutdown_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_reconciliation_and_shutdown_manual_benchmark -- --ignored --nocapture"
        );
        let total_pages = std::env::var("TINE_MANAGED_RECONCILIATION_BENCH_PAGES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|pages| *pages >= 4)
            .unwrap_or(1_000);
        let blocks_per_page = std::env::var("TINE_MANAGED_RECONCILIATION_BENCH_BLOCKS_PER_PAGE")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|blocks| *blocks > 0)
            .unwrap_or(1);
        let fixture = ActivationFixture::scaled_with_blocks(
            &format!("managed-reconciliation-{total_pages}"),
            0xa0fa + total_pages as u128,
            total_pages - 3,
            blocks_per_page,
        );
        let exact_source = user_graph_bytes(&fixture.graph_root);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("activation retains a runtime");
        drive_initial_feed(&handle);

        handle
            .observe_watcher(vec![SyncWatcherObservation::RescanRequired])
            .unwrap();
        let reconciliation_started = Instant::now();
        let mut turns = 0usize;
        while handle.status().unwrap().watcher.pending {
            turns = turns.saturating_add(1);
            assert!(
                turns <= 1_024,
                "settled broad reconciliation exceeded the bounded turn budget"
            );
            match handle.tick().unwrap() {
                SyncRuntimeTick::Terminal(detail) | SyncRuntimeTick::Failed(detail) => {
                    panic!("settled broad reconciliation failed: {detail}")
                }
                _ => {}
            }
        }
        let reconciliation = reconciliation_started.elapsed();
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            exact_source,
            "settled reconciliation must preserve every graph byte"
        );

        let shutdown_started = Instant::now();
        let shutdown = handle.clean_shutdown();
        let shutdown_elapsed = shutdown_started.elapsed();
        assert!(matches!(shutdown, Ok(SyncShutdownOutcome::Safe(_))));
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            exact_source,
            "safe shutdown after reconciliation must preserve every graph byte"
        );
        eprintln!(
            "managed_reconciliation_shutdown_bench total_pages={} blocks_per_page={} turns={} reconciliation_ms={:.3} shutdown_ms={:.3}",
            total_pages,
            blocks_per_page,
            turns,
            startup_ms(reconciliation),
            startup_ms(shutdown_elapsed),
        );
        let reconciliation_ceiling = Duration::from_millis(
            (total_pages as u64)
                .div_ceil(1_000)
                .saturating_mul(300)
                .max(500),
        );
        assert!(
            reconciliation < reconciliation_ceiling,
            "settled broad reconciliation exceeded its linear ceiling at {total_pages} pages: elapsed={reconciliation:?}, ceiling={reconciliation_ceiling:?}"
        );
        assert!(
            shutdown_elapsed < Duration::from_millis(300),
            "safe shutdown exceeded 300 ms after settled reconciliation at {total_pages} pages: {shutdown_elapsed:?}"
        );
    }

    fn remove_resume_points(root: &Path) -> usize {
        let mut removed = 0;
        let mut directories = vec![root.to_path_buf()];
        while let Some(directory) = directories.pop() {
            for entry in fs::read_dir(directory).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    directories.push(entry.path());
                } else if entry
                    .path()
                    .extension()
                    .is_some_and(|extension| extension == "resume-point")
                {
                    fs::remove_file(entry.path()).unwrap();
                    removed += 1;
                }
            }
        }
        removed
    }

    #[test]
    #[ignore = "manual release benchmark: crash reopen of a real graph copy"]
    fn managed_crash_reopen_real_graph_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_crash_reopen_real_graph_manual_benchmark -- --ignored --nocapture"
        );
        let source = PathBuf::from(
            std::env::var("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY")
                .expect("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY must name a disposable graph copy"),
        );
        let fixture = ActivationFixture::copied_graph("managed-crash-reopen-real", 0xa0d5, &source);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("real graph copy activates");
        drive_initial_feed(&handle);

        let mut directories = vec![fixture.graph_root.clone()];
        let mut managed_paths = Vec::new();
        while let Some(directory) = directories.pop() {
            for entry in fs::read_dir(directory).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    directories.push(entry.path());
                } else if matches!(
                    entry.path().extension().and_then(|value| value.to_str()),
                    Some("md" | "org")
                ) {
                    managed_paths.push(
                        entry
                            .path()
                            .strip_prefix(&fixture.graph_root)
                            .unwrap()
                            .to_string_lossy()
                            .replace('\\', "/"),
                    );
                }
            }
        }
        managed_paths.sort();
        let path = managed_paths
            .into_iter()
            .find(|path| {
                let (page, _) = load_application_exact(&handle, path);
                !page.blocks.is_empty()
            })
            .expect("real graph copy has an editable managed page");
        let (page, revision) = load_application_exact(&handle, &path);
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            "crash-reopen benchmark pending edit",
        );
        assert_eq!(handle.status().unwrap().managed_local_pending, 1);

        // Dropping the live actor without draining its committed local frame or
        // calling clean_shutdown matches a killed process during a pending save.
        drop(handle);
        if std::env::var_os("TINE_MANAGED_CRASH_REOPEN_FORCE_FULL_REPLAY").is_some() {
            assert!(
                remove_resume_points(&fixture.request.archive_root) > 0,
                "the manual cacheless comparison requires a published resume point"
            );
        }
        reset_runtime_open_instrumentation(workspace_id);
        reset_promoted_runtime_open_instrumentation(workspace_id);

        let started = Instant::now();
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        let elapsed = started.elapsed();
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let open = take_runtime_open_instrumentation(workspace_id);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        if std::env::var_os("TINE_MANAGED_CRASH_REOPEN_FORCE_FULL_REPLAY").is_some() {
            assert!(
                promoted.reconstructed_bootstrap_resume,
                "cacheless crash recovery must reconstruct one detached bootstrap resume"
            );
        }
        let resume = reopened
            .handle
            .as_ref()
            .and_then(|handle| handle.engine_instrumentation().ok())
            .map(|instrumentation| instrumentation.resume);
        eprintln!(
            "managed_crash_reopen_real elapsed_ms={:.3} resume={resume:?} open_phases: {} promoted_phases: {}",
            startup_ms(elapsed),
            startup_open_phase_receipt(&open),
            startup_promoted_open_phase_receipt(&promoted),
        );
        assert!(
            elapsed < Duration::from_secs(10),
            "real-graph crash reopen exceeded 10 seconds"
        );
        drop(reopened.handle);
    }

    /// Unsafe reopen of a real-scale graph whose managed history has been AGED:
    /// many accepted saves across many pages, each drained so the local journal
    /// compacts, before the final pending save and the unsafe drop.
    ///
    /// `managed_crash_reopen_real_graph_manual_benchmark` reopens a graph that was
    /// activated moments earlier, so its oplog holds one generation and recovery is
    /// trivially fast. That is not the state Martin's ~63 s reopen came from: his is
    /// a graph lived in for days, with accumulated generations, retained runs and
    /// manifests. This benchmark exists to find out which of those quantities the
    /// recovery cost actually tracks — graph size is already known not to explain it.
    ///
    /// `TINE_MANAGED_CRASH_REOPEN_ROUNDS` sets the number of accepted+drained saves
    /// (default 32; the test-build compaction threshold is 4 frames, so 32 rounds
    /// crosses it repeatedly). Sweep it to get the shape of the curve.
    /// An unsafe reopen after an aged managed history must OPEN the projection
    /// it already has, not rebuild it.
    ///
    /// The projection was at the accepted frontier the whole time; only the
    /// engine's run-local scratch address had moved, and that used to make the
    /// two roots compare unequal. Recovery could read that only as corruption,
    /// so it discarded a correct database and replayed the entire accepted
    /// history to reproduce it -- 72 s on a 1,046-file graph, and worse as the
    /// graph grows. This asserts on counters rather than elapsed time: a return
    /// of the defect means batches applied or pages materialized, which is
    /// visible whatever the machine's speed.
    #[test]
    fn managed_unsafe_reopen_at_the_accepted_frontier_opens_without_rebuilding() {
        let fixture = ActivationFixture::nested_unicode("managed-reopen-no-rebuild", 0xa0e8);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("synthetic graph activates");
        drive_initial_feed(&handle);

        // Age the local journal well past its compaction threshold, draining
        // every round, so the reopen faces a compacted multi-generation history
        // rather than the single generation a freshly activated graph has.
        for round in 0..6 {
            let (page, revision) = load_application_exact(&handle, "Root.md");
            let _ =
                save_application_block_text(&handle, page, revision, &format!("aged edit {round}"));
            for _ in 0..512 {
                if handle.status().unwrap().managed_local_pending == 0 {
                    break;
                }
                handle.tick().unwrap();
            }
            assert_eq!(
                handle.status().unwrap().managed_local_pending,
                0,
                "aging round {round} did not drain"
            );
        }
        // Drop the live actor without a clean shutdown: a killed process.
        drop(handle);

        reset_promoted_runtime_open_instrumentation(workspace_id);
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        let resume = reopened
            .handle
            .as_ref()
            .and_then(|handle| handle.engine_instrumentation().ok())
            .map(|instrumentation| instrumentation.resume)
            .expect("reopened runtime reports its resume observation");
        assert!(
            resume.adopted,
            "the compacted journal boundary must publish an adoptable crash-recovery point"
        );
        assert!(
            resume.replayed_generations < 6,
            "reopen replayed the complete six-generation aged suffix instead of the bounded post-compaction suffix: {resume:?}"
        );
        assert_eq!(
            promoted.projection_recovery, "opened-existing",
            "a projection already at the accepted frontier was not opened as-is (reason: {})",
            promoted.projection_rebuild_reason
        );
        assert_eq!(
            promoted.projection_applied_batches, 0,
            "an unsafe reopen at the accepted frontier replayed accepted batches"
        );
        assert_eq!(
            promoted.projection_bulk_pages_materialized, 0,
            "an unsafe reopen at the accepted frontier re-materialized pages"
        );
    }

    /// Age a graph, shut it down cleanly, then damage only the disposable
    /// SQLite projection. The oplog is untouched and authoritative, so the
    /// graph must still open.
    ///
    /// `damage` runs with the runtime stopped and returns what the projection
    /// recovery is expected to report.
    fn managed_safe_reopen_after_projection_damage(
        name: &str,
        seed: u128,
        damage: impl FnOnce(&Path),
        expected_recovery: &str,
    ) {
        let fixture = ActivationFixture::nested_unicode(name, seed);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("synthetic graph activates");
        drive_initial_feed(&handle);

        let (page, revision) = load_application_exact(&handle, "Root.md");
        let _ = save_application_block_text(&handle, page, revision, "edit before the damage");
        for _ in 0..512 {
            if handle.status().unwrap().managed_local_pending == 0 {
                break;
            }
            handle.tick().unwrap();
        }
        assert_eq!(
            handle.status().unwrap().managed_local_pending,
            0,
            "the pre-damage edit must drain, so the projection is current at shutdown"
        );
        assert!(
            matches!(handle.clean_shutdown(), Ok(SyncShutdownOutcome::Safe(_))),
            "the graph must reach a Safe handoff, which is the case this covers"
        );
        drop(handle);

        damage(&fixture.request.database_path);

        reset_promoted_runtime_open_instrumentation(workspace_id);
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(
            reopened.status,
            SyncRuntimeOpenStatus::Active,
            "a damaged disposable projection must not make an authoritative oplog unopenable"
        );
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        assert_eq!(
            promoted.projection_recovery, expected_recovery,
            "recovery took the wrong branch (reason: {})",
            promoted.projection_rebuild_reason
        );

        // Opening is not the whole claim: the rebuilt projection must actually
        // answer for the graph, including the edit made before the damage.
        let handle = reopened
            .handle
            .expect("the reopened runtime retains a handle");
        let (page, _) = load_application_exact(&handle, "Root.md");
        assert!(
            page.blocks
                .iter()
                .any(|block| block.raw.contains("edit before the damage")),
            "the rebuilt projection lost an accepted, drained edit"
        );
        drop(handle);
    }

    /// A cleanly shut down graph whose disposable projection has been deleted
    /// -- a cleared cache directory, a sweeper, a restore that skipped it.
    ///
    /// The crash path already rebuilds this exact state. Refusing it after a
    /// *clean* shutdown made the tidier lifecycle the unrecoverable one, and
    /// the refusal is reported to the frontend as `Retryable`, so the user gets
    /// a retry button that cannot ever succeed.
    #[test]
    fn managed_safe_reopen_rebuilds_a_deleted_disposable_projection() {
        managed_safe_reopen_after_projection_damage(
            "managed-safe-reopen-deleted-projection",
            0xa0ea,
            |database_path| {
                tine_storage::sqlite::SqliteFileSet::new(database_path)
                    .remove()
                    .expect("the projection file set is removable");
            },
            "rebuilt-missing",
        );
    }

    /// The same graph whose projection file is present but unreadable. This is
    /// the shape a schema-version bump or genuine corruption takes, and unlike
    /// deletion it also has forensic evidence to preserve.
    #[test]
    fn managed_safe_reopen_rebuilds_an_unreadable_disposable_projection() {
        managed_safe_reopen_after_projection_damage(
            "managed-safe-reopen-unreadable-projection",
            0xa0eb,
            |database_path| {
                fs::write(database_path, b"this is not a SQLite database")
                    .expect("the projection file is writable");
            },
            "rebuilt-preserving-evidence",
        );
    }

    #[test]
    fn managed_safe_reopen_rebuilds_a_corrupt_reconciliation_baseline() {
        let fixture = ActivationFixture::nested_unicode(
            "managed-safe-reopen-corrupt-reconciliation-baseline",
            0xa0ec,
        );
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("synthetic graph activates");
        drive_initial_feed(&handle);

        let (page, revision) = load_application_exact(&handle, "Root.md");
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            "accepted before baseline corruption",
        );
        drain_managed_local(&handle);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(handle);

        let baseline_path = fixture
            .request
            .application_runtime_root
            .join(crate::oplog::sync_layout::RECONCILIATION_DIR)
            .join(fixture.request.identities.workspace_id.to_string())
            .join(fixture.request.identities.endpoint_id.to_string())
            .join(crate::oplog::sync_layout::RECONCILIATION_DATABASE_FILE);
        assert!(baseline_path.is_file());
        let connection = rusqlite::Connection::open(&baseline_path).unwrap();
        connection
            .execute("UPDATE binding SET endpoint = zeroblob(16)", [])
            .unwrap();
        drop(connection);
        let archive_before = immutable_archive_bytes(&fixture.request.archive_root);

        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(
            reopened.status,
            SyncRuntimeOpenStatus::Active,
            "corruption of a disposable reconciliation baseline must not refuse the graph"
        );
        let handle = reopened
            .handle
            .expect("the recovered graph retains a handle");
        let (page, _) = load_application_exact(&handle, "Root.md");
        assert!(
            page.blocks
                .iter()
                .any(|block| block.raw.contains("accepted before baseline corruption")),
            "baseline recovery lost an accepted edit"
        );
        assert_eq!(
            immutable_archive_bytes(&fixture.request.archive_root),
            archive_before,
            "rebuilding a disposable baseline may not rewrite authoritative history"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));

        let forensic_prefix = crate::oplog::sync_layout::RECONCILIATION_FORENSIC_PREFIX;
        let forensic = fs::read_dir(baseline_path.parent().unwrap())
            .unwrap()
            .map(Result::unwrap)
            .find(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(forensic_prefix)
            })
            .expect("corrupt baseline evidence is preserved")
            .path();
        assert!(forensic.join("EVIDENCE_COMPLETE").is_file());
        assert!(forensic.join("REBUILD_COMPLETE").is_file());
    }

    /// A retained run is a reconstructible accelerator, not authority.  This
    /// captures the pre-recovery failure journey by corrupting only the
    /// `blobs.data` file of the exact run selected by the published resume
    /// point, then forcing SQLite to materialize documents from that selected
    /// run on reopen.
    #[test]
    fn managed_reopen_rebuilds_after_malformed_retained_scratch_blob() {
        let fixture = ActivationFixture::nested_unicode(
            "managed-reopen-malformed-retained-scratch-blob",
            0xa0ed,
        );
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("synthetic graph activates");
        drive_initial_feed(&handle);

        let (page, revision) = load_application_exact(&handle, "Root.md");
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            "accepted before retained scratch corruption",
        );
        let (written, _) = load_application_exact(&handle, "Root.md");
        assert!(
            written
                .blocks
                .iter()
                .any(|block| block.raw.contains("accepted before retained scratch corruption")),
            "the fresh activation's current retained scratch must serve a read-after-write before any restart"
        );
        drain_managed_local(&handle);
        assert!(
            matches!(handle.clean_shutdown(), Ok(SyncShutdownOutcome::Safe(_))),
            "the selected run is emitted only after a safe, settled handoff"
        );
        drop(handle);

        let expected_graph = user_graph_bytes(&fixture.graph_root);
        let immutable_archive_before_recovery =
            immutable_archive_bytes(&fixture.request.archive_root);
        let immutable_history_before_recovery =
            immutable_engine_history_bytes(&fixture.request.archive_root);
        let immutable_receipts_before_recovery =
            immutable_projection_receipt_bytes(&fixture.request.receipt_root);

        let (selected_run_id, selected_run) =
            selected_retained_scratch_run_for_test(&fixture.request.archive_root);
        let selected_before = fs::read_dir(&selected_run)
            .unwrap()
            .map(Result::unwrap)
            .filter(|entry| entry.file_type().unwrap().is_file())
            .map(|entry| {
                (
                    entry.file_name().to_string_lossy().into_owned(),
                    fs::read(entry.path()).unwrap(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let selected_blobs = selected_run.join(tine_storage::formats::SCRATCH_BLOBS_FILE);
        assert!(
            selected_blobs.is_file(),
            "selected retained run has blobs.data"
        );

        // The retained SQLite projection would otherwise remain a valid cache
        // and hide the fault.  It is disposable, so force its normal rebuild
        // without touching any accepted immutable archive bytes.
        tine_storage::sqlite::SqliteFileSet::new(&fixture.request.database_path)
            .remove()
            .expect("the disposable SQLite projection is removable");
        fs::write(&selected_blobs, b"not a scratch blob").unwrap();
        let selected_corrupted = fs::read_dir(&selected_run)
            .unwrap()
            .map(Result::unwrap)
            .filter(|entry| entry.file_type().unwrap().is_file())
            .map(|entry| {
                (
                    entry.file_name().to_string_lossy().into_owned(),
                    fs::read(entry.path()).unwrap(),
                )
            })
            .collect::<BTreeMap<_, _>>();

        let selected_at_reclamation = Arc::new(Mutex::new(None));
        let selected_at_reclamation_result = Arc::clone(&selected_at_reclamation);
        let selected_at_reclamation_path = selected_run.clone();
        let selected_at_reclamation_expected = selected_corrupted.clone();
        act_once_at_resume_lifecycle_cut_for_workspace_for_test(
            fixture.request.identities.workspace_id,
            ResumeLifecycleCut::BeforeReclamation,
            Box::new(move || {
                let observed = recursive_file_bytes(&selected_at_reclamation_path);
                assert_eq!(
                    observed, selected_at_reclamation_expected,
                    "recovery must leave the refused run byte-exact through replacement publication and up to authenticated reclamation"
                );
                *selected_at_reclamation_result.lock().unwrap() = Some(observed);
            }),
        );
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let reopened = reopened
            .handle
            .expect("typed retained-scratch failure replays into an active runtime");
        assert_eq!(
            immutable_archive_bytes(&fixture.request.archive_root),
            immutable_archive_before_recovery,
            "cache-only retained-scratch recovery must not alter immutable archive authority"
        );
        assert_eq!(
            immutable_engine_history_bytes(&fixture.request.archive_root),
            immutable_history_before_recovery,
            "cache-only retained-scratch recovery must not alter immutable engine history"
        );
        assert_eq!(
            immutable_projection_receipt_bytes(&fixture.request.receipt_root),
            immutable_receipts_before_recovery,
            "cache-only retained-scratch recovery must not alter immutable projection receipts"
        );
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            expected_graph,
            "replay recovery must not rewrite direct graph bytes"
        );
        assert_eq!(
            selected_at_reclamation.lock().unwrap().as_ref(),
            Some(&selected_corrupted),
            "the exact pre-reclamation preservation seam must fire during post-open publication"
        );
        let (replacement_after_recovery, replacement_after_recovery_path) =
            selected_retained_scratch_run_for_test(&fixture.request.archive_root);
        assert_ne!(replacement_after_recovery, selected_run_id);
        assert!(replacement_after_recovery_path.is_dir());
        if selected_run.is_dir() {
            assert_eq!(
                recursive_file_bytes(&selected_run),
                selected_corrupted,
                "an unreclaimed refused run must remain byte-for-byte intact"
            );
        } else {
            assert!(
                !selected_run.exists(),
                "authenticated reclamation must remove the whole refused run, never leave a partial entry"
            );
        }
        assert_ne!(selected_corrupted, selected_before);

        let (recovered_page, recovered_revision) = load_application_exact(&reopened, "Root.md");
        assert!(
            recovered_page.blocks.iter().any(|block| block
                .raw
                .contains("accepted before retained scratch corruption")),
            "the recovered public application page must contain the last accepted edit"
        );
        let _ = save_application_block_text(
            &reopened,
            recovered_page,
            recovered_revision,
            "accepted after retained scratch recovery",
        );
        let (saved_page, _) = load_application_exact(&reopened, "Root.md");
        assert!(
            saved_page.blocks.iter().any(|block| block
                .raw
                .contains("accepted after retained scratch recovery")),
            "a public application save after recovery must be immediately readable"
        );
        drain_managed_local(&reopened);

        let immutable_archive_after_save = immutable_archive_bytes(&fixture.request.archive_root);
        let immutable_history_after_save =
            immutable_engine_history_bytes(&fixture.request.archive_root);
        let immutable_receipts_after_save =
            immutable_projection_receipt_bytes(&fixture.request.receipt_root);
        assert_byte_map_is_strict_extension(
            &immutable_archive_before_recovery,
            &immutable_archive_after_save,
            "immutable archive",
        );
        assert_byte_map_is_strict_extension(
            &immutable_history_before_recovery,
            &immutable_history_after_save,
            "immutable engine history",
        );
        assert_byte_map_is_strict_extension(
            &immutable_receipts_before_recovery,
            &immutable_receipts_after_save,
            "immutable projection receipts",
        );
        let graph_after_save = user_graph_bytes(&fixture.graph_root);
        assert_ne!(
            graph_after_save, expected_graph,
            "the accepted post-recovery save must update the direct graph projection"
        );
        assert!(
            graph_after_save.values().any(|bytes| bytes
                .windows(b"accepted after retained scratch recovery".len())
                .any(|window| window == b"accepted after retained scratch recovery")),
            "the direct graph projection must contain the accepted post-recovery edit"
        );
        if selected_run.is_dir() {
            assert_eq!(
                recursive_file_bytes(&selected_run),
                selected_corrupted,
                "the accepted post-recovery save must not reuse or alter abandoned run {selected_run_id}"
            );
        } else {
            assert!(
                !selected_run.exists(),
                "later lifecycle work must not recreate a partially retired refused run"
            );
        }
        assert!(matches!(
            reopened.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        let (replacement_run_id, _) =
            selected_retained_scratch_run_for_test(&fixture.request.archive_root);
        assert_ne!(
            replacement_run_id, selected_run_id,
            "safe recovery publishes a fresh retained run rather than reusing the malformed one"
        );
    }

    #[test]
    #[ignore = "manual release benchmark: unsafe reopen after an aged managed history"]
    fn managed_crash_reopen_aged_history_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_crash_reopen_aged_history_manual_benchmark -- --ignored --nocapture"
        );
        let source = PathBuf::from(
            std::env::var("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY")
                .expect("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY must name a disposable graph copy"),
        );
        let rounds: usize = std::env::var("TINE_MANAGED_CRASH_REOPEN_ROUNDS")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(32);
        let fixture = ActivationFixture::copied_graph("managed-crash-reopen-aged", 0xa0e7, &source);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("real graph copy activates");
        drive_initial_feed(&handle);

        let mut directories = vec![fixture.graph_root.clone()];
        let mut managed_paths = Vec::new();
        while let Some(directory) = directories.pop() {
            for entry in fs::read_dir(directory).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    directories.push(entry.path());
                } else if matches!(
                    entry.path().extension().and_then(|value| value.to_str()),
                    Some("md" | "org")
                ) {
                    managed_paths.push(
                        entry
                            .path()
                            .strip_prefix(&fixture.graph_root)
                            .unwrap()
                            .to_string_lossy()
                            .replace('\\', "/"),
                    );
                }
            }
        }
        managed_paths.sort();
        let editable = managed_paths
            .into_iter()
            .filter(|path| {
                let (page, _) = load_application_exact(&handle, path);
                !page.blocks.is_empty()
            })
            .take(rounds.max(1))
            .collect::<Vec<_>>();
        assert!(
            !editable.is_empty(),
            "real graph copy has an editable managed page"
        );

        // Age the history: each round is an accepted save that is then fully
        // drained, so the local journal reaches and crosses its compaction
        // threshold repeatedly rather than staying in one generation.
        let aging_started = Instant::now();
        for round in 0..rounds {
            let path = &editable[round % editable.len()];
            let (page, revision) = load_application_exact(&handle, path);
            let _ = save_application_block_text(
                &handle,
                page,
                revision,
                &format!("aged-history benchmark edit {round}"),
            );
            for _ in 0..512 {
                if handle.status().unwrap().managed_local_pending == 0 {
                    break;
                }
                handle.tick().unwrap();
            }
            assert_eq!(
                handle.status().unwrap().managed_local_pending,
                0,
                "aging round {round} did not drain"
            );
        }
        let aging = aging_started.elapsed();

        // One final UNDRAINED save, then drop the live actor without
        // clean_shutdown: a killed process during a pending save.
        let path = &editable[rounds % editable.len()];
        let (page, revision) = load_application_exact(&handle, path);
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            "aged-history benchmark pending edit",
        );
        assert_eq!(handle.status().unwrap().managed_local_pending, 1);
        drop(handle);

        reset_runtime_open_instrumentation(workspace_id);
        reset_promoted_runtime_open_instrumentation(workspace_id);
        let started = Instant::now();
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        let elapsed = started.elapsed();
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let open = take_runtime_open_instrumentation(workspace_id);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        let resume = reopened
            .handle
            .as_ref()
            .and_then(|handle| handle.engine_instrumentation().ok())
            .map(|instrumentation| instrumentation.resume);
        eprintln!(
            "managed_crash_reopen_aged rounds={rounds} aging_ms={:.3} elapsed_ms={:.3} resume={resume:?} open_phases: {} promoted_phases: {}",
            startup_ms(aging),
            startup_ms(elapsed),
            startup_open_phase_receipt(&open),
            startup_promoted_open_phase_receipt(&promoted),
        );
        // Hard real-corpus recovery ceiling. A return of the per-document
        // whole-graph anchor work (which put this same case at 72 s) must fail
        // loudly instead of being read as "slow today".
        assert!(
            elapsed < Duration::from_secs(10),
            "aged-history crash reopen exceeded the 10-second real-corpus recovery ceiling: elapsed_ms={:.3}",
            startup_ms(elapsed),
        );
        drop(reopened.handle);
    }

    /// Only a tick that committed a batch may be reported as a content change.
    ///
    /// The two admitted variants were treated alike, so a drain that took no
    /// completed batch still told the frontend the graph had changed. That
    /// contentless signal, arriving while a page was dirty, is what produced a
    /// conflict against nothing -- the false-conflict incident of 2026-08-06.
    #[test]
    fn only_a_committing_tick_reports_an_observable_change() {
        assert!(SyncRuntimeTick::AdmittedComplete { epoch: 7 }.committed_observable_change());
        assert!(
            !SyncRuntimeTick::AdmittedNoop { epoch: 7 }.committed_observable_change(),
            "an admission that took no completed batch is not a content change"
        );
        for quiet in [
            SyncRuntimeTick::Idle,
            SyncRuntimeTick::Recovering,
            SyncRuntimeTick::RetryFull,
            SyncRuntimeTick::Blocked("blocked".into()),
            SyncRuntimeTick::RecoveryBlocked("blocked".into()),
            SyncRuntimeTick::Failed("failed".into()),
            SyncRuntimeTick::Terminal("terminal".into()),
        ] {
            assert!(
                !quiet.committed_observable_change(),
                "{quiet:?} committed nothing and must not be reported as a change"
            );
        }
    }

    /// A rebuild must resolve documents through its root-bound lookup sessions.
    ///
    /// This asserts the mechanism, not a duration, because the defect it guards
    /// is invisible in a single measurement: with the sessions unthreaded every
    /// document resolution re-walked the scratch LSM from the top, so
    /// per-document cost grew with the graph and a rebuild visiting a linear
    /// number of documents came out at about n^1.6 -- 15 s on a 1,045-file
    /// graph against Martin's 10-s ceiling. A wall-clock budget would pass on a
    /// small CI fixture no matter how the lookups are routed; session reuse is
    /// the property that actually holds the curve down, and it is checkable at
    /// any scale.
    #[test]
    fn managed_projection_rebuild_resolves_documents_through_lookup_sessions() {
        // Cross more than two 64-page terminal materialization windows. One
        // window can legitimately report one root miss and one later hit while
        // still batching all of its document loads; reuse is observable only
        // when the same retained session serves another bounded window.
        let fixture = ActivationFixture::scaled("managed-rebuild-lookup-sessions", 0xa0ec, 130);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("scaled graph activates");
        drive_initial_feed(&handle);
        assert!(
            matches!(handle.clean_shutdown(), Ok(SyncShutdownOutcome::Safe(_))),
            "the fixture must reach a Safe handoff before its projection is discarded"
        );
        drop(handle);

        tine_storage::sqlite::SqliteFileSet::new(&fixture.request.database_path)
            .remove()
            .expect("the projection file set is removable");

        reset_promoted_runtime_open_instrumentation(workspace_id);
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        assert_eq!(
            promoted.projection_recovery, "rebuilt-missing",
            "this test only says something if a rebuild actually ran (reason: {})",
            promoted.projection_rebuild_reason
        );
        let rebuild = &promoted.projection_rebuild_counters;
        assert!(
            rebuild.exact_document_loads > 1,
            "a rebuild that loaded {} document(s) is too small to show reuse",
            rebuild.exact_document_loads
        );
        // Sessions must exist AND be reused. A session that is constructed and
        // then consulted once per document would report only misses, which is
        // the same cost as having none.
        assert!(
            rebuild.accepted_frontier_session_hits > rebuild.accepted_frontier_session_misses,
            "accepted-frontier lookups did not reuse their session ({} hits, {} misses over {} document loads)",
            rebuild.accepted_frontier_session_hits,
            rebuild.accepted_frontier_session_misses,
            rebuild.exact_document_loads
        );
        assert!(
            rebuild.external_exact_session_hits > rebuild.external_exact_session_misses,
            "external-exact document loads did not reuse their session ({} hits, {} misses over {} document loads)",
            rebuild.external_exact_session_hits,
            rebuild.external_exact_session_misses,
            rebuild.exact_document_loads
        );
        drop(reopened.handle);
    }

    /// Cost of a FULL projection rebuild on a real-scale graph.
    ///
    /// Every other managed benchmark measures a reopen that is *allowed to keep*
    /// its projection, so none of them price the rebuild itself. Since the
    /// frontier-identity cut, an ordinary reopen never rebuilds -- but a rebuild
    /// is still legitimately reachable through genuine corruption, a schema
    /// change, or a persisted identity-format change, and on that day it is the
    /// user's whole experience of the product. Martin's requirement is that it
    /// stay under 10 s and be truly linear, because other graphs are 10x this
    /// one.
    ///
    /// The trigger here is deliberately the cheapest legitimate one: the
    /// projection file set is deleted after a clean shutdown, so recovery takes
    /// `RebuiltMissing` and no forensic preservation is charged to the number.
    /// A corruption trigger would rebuild the same way plus evidence capture.
    ///
    /// `TINE_MANAGED_REBUILD_GRAPH_COPY` names a disposable graph copy;
    /// `TINE_MANAGED_REBUILD_ROUNDS` sets how many accepted+drained saves age
    /// the history first (compacted generations carry whole-graph slices, so an
    /// aged history is what a rebuild actually has to replay).
    #[test]
    #[ignore = "manual release benchmark: full projection rebuild on a real-scale graph"]
    fn managed_projection_rebuild_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_projection_rebuild_manual_benchmark -- --ignored --nocapture"
        );
        let source = PathBuf::from(
            std::env::var("TINE_MANAGED_REBUILD_GRAPH_COPY")
                .expect("TINE_MANAGED_REBUILD_GRAPH_COPY must name a disposable graph copy"),
        );
        let rounds: usize = std::env::var("TINE_MANAGED_REBUILD_ROUNDS")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(8);
        let fixture =
            ActivationFixture::copied_graph("managed-projection-rebuild", 0xa0e9, &source);
        let workspace_id = fixture.request.identities.workspace_id;
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("real graph copy activates");
        drive_initial_feed(&handle);

        let mut directories = vec![fixture.graph_root.clone()];
        let mut managed_paths = Vec::new();
        while let Some(directory) = directories.pop() {
            for entry in fs::read_dir(directory).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    directories.push(entry.path());
                } else if matches!(
                    entry.path().extension().and_then(|value| value.to_str()),
                    Some("md" | "org")
                ) {
                    managed_paths.push(
                        entry
                            .path()
                            .strip_prefix(&fixture.graph_root)
                            .unwrap()
                            .to_string_lossy()
                            .replace('\\', "/"),
                    );
                }
            }
        }
        managed_paths.sort();
        let graph_files = managed_paths.len();
        let editable = managed_paths
            .into_iter()
            .filter(|path| {
                let (page, _) = load_application_exact(&handle, path);
                !page.blocks.is_empty()
            })
            .take(rounds.max(1))
            .collect::<Vec<_>>();
        assert!(
            !editable.is_empty(),
            "real graph copy has an editable managed page"
        );

        for round in 0..rounds {
            let path = &editable[round % editable.len()];
            let (page, revision) = load_application_exact(&handle, path);
            let _ = save_application_block_text(
                &handle,
                page,
                revision,
                &format!("projection-rebuild benchmark edit {round}"),
            );
            for _ in 0..512 {
                if handle.status().unwrap().managed_local_pending == 0 {
                    break;
                }
                handle.tick().unwrap();
            }
            assert_eq!(
                handle.status().unwrap().managed_local_pending,
                0,
                "aging round {round} did not drain"
            );
        }

        // A clean shutdown, so the number below prices the rebuild and not a
        // crash recovery that happens to rebuild.
        assert!(
            matches!(handle.clean_shutdown(), Ok(SyncShutdownOutcome::Safe(_))),
            "the aged graph must reach a Safe handoff before the projection is discarded"
        );
        drop(handle);

        // The trigger: the disposable projection is gone. Recovery must
        // reconstruct it from authoritative history alone.
        tine_storage::sqlite::SqliteFileSet::new(&fixture.request.database_path)
            .remove()
            .expect("the projection file set is removable");
        assert!(
            !tine_storage::sqlite::SqliteFileSet::new(&fixture.request.database_path).any_exists(),
            "the benchmark must actually discard the projection it means to price"
        );

        reset_runtime_open_instrumentation(workspace_id);
        reset_promoted_runtime_open_instrumentation(workspace_id);
        let started = Instant::now();
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        let elapsed = started.elapsed();
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let open = take_runtime_open_instrumentation(workspace_id);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        eprintln!(
            "managed_projection_rebuild files={graph_files} rounds={rounds} elapsed_ms={:.3} open_phases: {} promoted_phases: {}",
            startup_ms(elapsed),
            startup_open_phase_receipt(&open),
            startup_promoted_open_phase_receipt(&promoted),
        );
        // Reading the branch off the run, not inferring it from the timing:
        // a number that turned out to price "opened an existing projection"
        // would be measuring the opposite of this benchmark's subject.
        assert_eq!(
            promoted.projection_recovery, "rebuilt-missing",
            "the benchmark must price a real rebuild (reason: {})",
            promoted.projection_rebuild_reason
        );
        assert!(
            promoted.projection_applied_batches > 0,
            "a rebuild that applied no accepted batches did not reconstruct anything"
        );
        assert!(
            elapsed < Duration::from_secs(10),
            "projection rebuild exceeded the 10-second real-corpus recovery ceiling: elapsed_ms={:.3}",
            startup_ms(elapsed),
        );
        drop(reopened.handle);
    }

    #[test]
    fn managed_crash_reopen_synthetic_history_sweep_with_and_without_resume_point() {
        const PATH: &str = "notes/Synthetic crash history.md";
        const INITIAL: &[u8] = b"- initial synthetic history\n";

        for accepted_edits in [1_u64, 2] {
            assert!(
                accepted_edits + 1 < MANAGED_LOCAL_COMPACTION_FRAME_THRESHOLD,
                "the synthetic history sweep and final pending tail must remain below compaction"
            );
            for cacheless in [false, true] {
                let fixture = ActivationFixture::empty(
                    &format!(
                        "managed-crash-history-{accepted_edits}-{}",
                        if cacheless {
                            "cacheless"
                        } else {
                            "accelerated"
                        }
                    ),
                    0xa170 + accepted_edits as u128 * 0x20 + cacheless as u128,
                );
                fs::write(fixture.graph_root.join(PATH), INITIAL).unwrap();
                let request = reopen_request(&fixture.request);
                let workspace_id = fixture.request.identities.workspace_id;
                let activated =
                    SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
                assert_eq!(activated.status, SyncLocalActivationStatus::Active);
                let handle = activated
                    .handle
                    .expect("synthetic history fixture activates");
                drive_initial_feed(&handle);

                let (mut page, mut revision) = load_application_exact(&handle, PATH);
                for edit in 1..=accepted_edits {
                    (page, revision) = save_application_block_text(
                        &handle,
                        page,
                        revision,
                        &format!("accepted and drained synthetic edit {edit}"),
                    );
                }
                drain_managed_local(&handle);
                let drained = handle.status().unwrap();
                assert_eq!(drained.managed_local_pending, 0);
                assert_eq!(drained.managed_local_checkpointed_sequence, accepted_edits);
                assert_eq!(drained.managed_local_next_sequence, accepted_edits);

                let (tail_page, tail_revision) = save_application_block_text(
                    &handle,
                    page,
                    revision,
                    "actor-accepted undrained synthetic tail",
                );
                let tail_bytes = fs::read(fixture.graph_root.join(PATH)).unwrap();
                let pending = handle.status().unwrap();
                assert_eq!(pending.managed_local_pending, 1);
                assert_eq!(pending.managed_local_checkpointed_sequence, accepted_edits);
                assert_eq!(pending.managed_local_next_sequence, accepted_edits + 1);
                let retained_frames = managed_local_journal_frames(&request);
                assert_eq!(retained_frames.len(), accepted_edits as usize + 1);
                assert_eq!(
                    retained_frames.last().unwrap().sequence(),
                    accepted_edits,
                    "the sole undrained tail must be the final accepted sequence"
                );

                // The final tail is actor-accepted and projected, but its
                // derivative journal frame has not been drained or handed off.
                drop(handle);
                if cacheless {
                    assert!(
                        remove_resume_points(&fixture.request.archive_root) > 0,
                        "synthetic cacheless reopen requires a published resume point"
                    );
                }
                reset_runtime_open_instrumentation(workspace_id);
                reset_promoted_runtime_open_instrumentation(workspace_id);
                let started = Instant::now();
                let opened = SyncRuntimeHandle::open(request.clone());
                let elapsed = started.elapsed();
                assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
                let open = take_runtime_open_instrumentation(workspace_id);
                let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
                if cacheless {
                    assert!(
                        promoted.reconstructed_bootstrap_resume,
                        "cacheless synthetic reopen must reconstruct the detached bootstrap resume"
                    );
                }
                eprintln!(
                    "managed_crash_reopen_synthetic accepted_edits={accepted_edits} cacheless={cacheless} elapsed_ms={:.3} open_phases: {} promoted_phases: {}",
                    startup_ms(elapsed),
                    startup_open_phase_receipt(&open),
                    startup_promoted_open_phase_receipt(&promoted),
                );
                assert!(
                    elapsed < Duration::from_secs(10),
                    "synthetic crash reopen exceeded 10 seconds: accepted_edits={accepted_edits} cacheless={cacheless}"
                );

                let reopened = opened.handle.expect("active synthetic reopen has an actor");
                drive_initial_feed(&reopened);
                let recovered_status = reopened.status().unwrap();
                assert_eq!(
                    recovered_status.recovery,
                    Some(SyncRuntimeRecovery::TookOverCrashedUnsafe)
                );
                assert_eq!(recovered_status.managed_local_pending, 0);
                assert_eq!(
                    recovered_status.managed_local_checkpointed_sequence,
                    accepted_edits + 1
                );
                assert_eq!(
                    recovered_status.managed_local_next_sequence,
                    accepted_edits + 1
                );
                let (recovered, recovered_revision) = load_application_exact(&reopened, PATH);
                assert_parser_dto_semantics(&tail_page, &recovered);
                assert_eq!(tail_revision, recovered_revision);
                assert_eq!(fs::read(fixture.graph_root.join(PATH)).unwrap(), tail_bytes);
                assert!(matches!(
                    reopened.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));
            }
        }
    }

    #[test]
    #[ignore = "manual release gate: managed page and Journals reads at 1,000 and 10,000 mixed pages"]
    fn managed_application_read_1000_and_10000_page_manual_gate() {
        assert!(
            !cfg!(debug_assertions),
            "this gate is release-only; run cargo test -p tine-core --release managed_application_read_1000_and_10000_page_manual_gate -- --ignored --nocapture"
        );
        let page_counts = std::env::var("TINE_MANAGED_APPLICATION_READ_GATE_PAGES")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| part.trim().parse::<usize>().unwrap())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![1_000, 10_000]);
        let samples = std::env::var("TINE_MANAGED_APPLICATION_READ_GATE_SAMPLES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|samples| *samples >= 2)
            .unwrap_or(20);
        let mut managed_page_p95_by_scale = Vec::new();

        for (scale, total_pages) in page_counts.into_iter().enumerate() {
            assert!(total_pages >= 4);
            let fixture = ActivationFixture::scaled_mixed_with_journals(
                "managed-application-read-gate",
                0xa0f0 + scale as u128 * 16,
                total_pages - 3,
                4,
            );
            let source = user_graph_bytes(&fixture.graph_root);
            assert_eq!(source.len(), total_pages + 1);

            let direct_graph = Graph::open(&fixture.graph_root);
            let direct_entries = direct_graph.list_pages();
            assert_eq!(direct_entries.len(), total_pages);
            let target = direct_entries
                .iter()
                .find(|entry| entry.name == "Synthetic 1")
                .expect("mixed fixture retains its ordinary target")
                .clone();
            let mut direct_journals = direct_entries
                .iter()
                .filter(|entry| {
                    entry.kind == PageKind::Journal
                        && entry.date_key.is_some_and(|day| {
                            day <= crate::date::JournalDate::today().ordinal_key()
                        })
                })
                .cloned()
                .collect::<Vec<_>>();
            direct_journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap()));
            assert!(direct_journals.len() >= 3);

            let mut direct_page_samples = Vec::with_capacity(samples);
            let mut direct_target = None;
            for _ in 0..samples {
                let started = Instant::now();
                let page = direct_graph.load_page(&target).unwrap();
                direct_page_samples.push(started.elapsed());
                direct_target = Some(page);
            }
            let direct_feed_started = Instant::now();
            let direct_feed = direct_journals
                .iter()
                .take(3)
                .map(|entry| direct_graph.load_page(entry).unwrap())
                .collect::<Vec<_>>();
            let direct_feed_elapsed = direct_feed_started.elapsed();

            let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
            assert_eq!(activated.status, SyncLocalActivationStatus::Active);
            let activation_handle = activated.handle.expect("activation retains its actor");
            drive_initial_feed(&activation_handle);
            assert!(matches!(
                activation_handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
            drop(activation_handle);

            let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
            assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
            let handle = opened.handle.expect("managed reopen retains its actor");
            let mut managed_page_samples = Vec::with_capacity(samples);
            let mut managed_target = None;
            for _ in 0..samples {
                let started = Instant::now();
                let page = load_application_exact(&handle, &target.rel_path).0;
                managed_page_samples.push(started.elapsed());
                managed_target = Some(page);
            }

            let inventory_engine_before = handle.engine_instrumentation().unwrap();
            let managed_feed_started = Instant::now();
            let managed_entries = match handle.application_page_inventory().unwrap() {
                SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
                other => panic!("managed page inventory did not load: {other:?}"),
            };
            let mut managed_journals = managed_entries
                .into_iter()
                .filter(|entry| {
                    entry.kind == PageKind::Journal
                        && entry.date_key.is_some_and(|day| {
                            day <= crate::date::JournalDate::today().ordinal_key()
                        })
                })
                .collect::<Vec<_>>();
            managed_journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap()));
            let managed_feed = managed_journals
                .iter()
                .take(3)
                .map(|entry| load_application_exact(&handle, &entry.rel_path).0)
                .collect::<Vec<_>>();
            let managed_feed_elapsed = managed_feed_started.elapsed();
            let inventory_engine_after = handle.engine_instrumentation().unwrap();

            assert_parser_dto_semantics(
                &direct_target.expect("direct target loaded"),
                &managed_target.expect("managed target loaded"),
            );
            assert_eq!(direct_feed.len(), managed_feed.len());
            for (direct, managed) in direct_feed.iter().zip(&managed_feed) {
                assert_parser_dto_semantics(direct, managed);
            }
            assert_eq!(
                user_graph_bytes(&fixture.graph_root),
                source,
                "read gates preserve the source tree"
            );

            let direct_page_p50 = startup_median(&direct_page_samples);
            let direct_page_p95 = startup_p95(&direct_page_samples);
            let managed_page_p50 = startup_median(&managed_page_samples);
            let managed_page_p95 = startup_p95(&managed_page_samples);
            eprintln!(
                "managed_application_read_gate pages={total_pages} samples={samples} direct_page_p50_ms={:.3} direct_page_p95_ms={:.3} managed_page_p50_ms={:.3} managed_page_p95_ms={:.3} direct_journals_first_page_ms={:.3} managed_journals_first_page_ms={:.3}",
                startup_ms(direct_page_p50),
                startup_ms(direct_page_p95),
                startup_ms(managed_page_p50),
                startup_ms(managed_page_p95),
                startup_ms(direct_feed_elapsed),
                startup_ms(managed_feed_elapsed),
            );
            assert!(
                managed_page_p50 <= Duration::from_millis(50)
                    && managed_page_p50 <= direct_page_p50.saturating_mul(10),
                "managed page-open p50 gate failed at {total_pages} pages: direct={direct_page_p50:?}, managed={managed_page_p50:?}"
            );
            assert!(
                managed_page_p95 <= Duration::from_millis(50)
                    && managed_page_p95 <= direct_page_p95.saturating_mul(10),
                "managed page-open p95 gate failed at {total_pages} pages: direct={direct_page_p95:?}, managed={managed_page_p95:?}"
            );
            assert!(
                managed_feed_elapsed <= Duration::from_millis(500),
                "managed Journals first-page gate failed at {total_pages} pages: {managed_feed_elapsed:?}"
            );
            assert_eq!(
                inventory_engine_after.catalog_hot_state_loads,
                inventory_engine_before.catalog_hot_state_loads,
                "page inventory must not materialize the hot catalog once per graph page"
            );
            managed_page_p95_by_scale.push((total_pages, managed_page_p95));
            assert!(matches!(
                handle.clean_shutdown(),
                Ok(SyncShutdownOutcome::Safe(_))
            ));
        }

        if let [(_, smaller), (larger_pages, larger)] = managed_page_p95_by_scale.as_slice() {
            assert!(
                *larger <= smaller.saturating_mul(2).max(*smaller + Duration::from_millis(5)),
                "managed page-open p95 scales with unrelated graph size at {larger_pages} pages: smaller={smaller:?}, larger={larger:?}"
            );
        }
    }

    fn managed_query_gate_scales() -> Vec<usize> {
        let raw =
            std::env::var("TINE_MANAGED_QUERY_GATE_PAGES").unwrap_or_else(|_| "1000,10000".into());
        let scales = raw
            .split(',')
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| {
                value.parse::<usize>().unwrap_or_else(|error| {
                    panic!("TINE_MANAGED_QUERY_GATE_PAGES contains {value:?}: {error}")
                })
            })
            .collect::<BTreeSet<_>>();
        assert!(
            !scales.is_empty() && scales.iter().all(|pages| *pages >= 100),
            "TINE_MANAGED_QUERY_GATE_PAGES must contain one or more scales of at least 100 pages"
        );
        scales.into_iter().collect()
    }

    fn managed_query_gate_samples() -> usize {
        std::env::var("TINE_MANAGED_QUERY_GATE_SAMPLES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|samples| *samples >= 2)
            .unwrap_or(5)
    }

    fn assert_managed_simple_query_matches_direct(
        label: &str,
        mut managed: SyncApplicationBoundedRefGroups,
        direct: crate::model::BoundedRefGroups,
    ) {
        assert_eq!(managed.exceeded, direct.exceeded, "{label}");
        assert_eq!(managed.total, direct.total, "{label}");
        let mut direct_groups = (*direct.groups).clone();
        canonicalize_query_groups_for_mode_differential(&mut managed.groups);
        canonicalize_query_groups_for_mode_differential(&mut direct_groups);
        assert_eq!(
            serde_json::to_value(managed.groups).unwrap(),
            serde_json::to_value(direct_groups).unwrap(),
            "managed query diverged from parser-owned Direct Files semantics: {label}"
        );
    }

    fn max_query_gate_counter(
        samples: &[ManagedApplicationQueryInstrumentation],
        value: impl Fn(&ManagedApplicationQueryInstrumentation) -> usize,
    ) -> usize {
        samples.iter().map(value).max().unwrap_or(0)
    }

    fn managed_query_search_manual_receipt(
        fixture: &ActivationFixture,
        label: &str,
        samples: usize,
        expected_total_pages: Option<usize>,
        expected_task_result_rows: Option<usize>,
    ) {
        const MAX_ROWS: usize = 20_000;
        const MAX_BYTES: usize = 32 * 1024 * 1024;
        let indexed = "(task TODO)";
        let regex_all = "(content-regex \".*\")";
        let graph_search_source = "query-density-page";

        let direct = Graph::open(&fixture.graph_root);
        let total_pages = direct.list_pages().len();
        assert!(total_pages > 0, "{label} fixture has no pages");
        let direct_indexed = direct.run_query_bounded(indexed, MAX_ROWS, MAX_BYTES);
        let direct_regex_all = direct.run_query_bounded(regex_all, MAX_ROWS, MAX_BYTES);
        let direct_graph_search = direct.run_graph_search(graph_search_source, 0, MAX_ROWS, false);
        if let Some(expected_total_pages) = expected_total_pages {
            assert_eq!(
                total_pages, expected_total_pages,
                "synthetic query fixture did not activate at its configured scale: {label}"
            );
            let expected_task_result_rows = expected_task_result_rows
                .expect("synthetic query fixture must declare its task density");
            assert!(
                direct_indexed.total > 0,
                "synthetic indexed Direct query must be nonempty: {label}"
            );
            assert_eq!(
                direct_indexed.total, expected_task_result_rows,
                "synthetic indexed Direct total drifted: {label}"
            );
            assert_eq!(
                direct_regex_all.total, total_pages,
                "synthetic Regex-All Direct total must equal the configured page scale: {label}"
            );
            let direct_graph_blocks = direct_graph_search
                .hits
                .iter()
                .filter(|hit| matches!(hit, crate::query_plan::QueryHit::Block { .. }))
                .count();
            assert!(
                direct_graph_blocks > 0,
                "synthetic graph block search must be nonempty: {label}"
            );
            assert_eq!(
                direct_graph_blocks, total_pages,
                "synthetic graph block-search Direct total must equal the configured page scale: {label}"
            );
        }

        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(
            activated.status,
            SyncLocalActivationStatus::Active,
            "{label}"
        );
        let activation_handle = activated.handle.expect("activation retains its actor");
        drive_initial_feed(&activation_handle);
        assert!(matches!(
            activation_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(activation_handle);

        let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(opened.status, SyncRuntimeOpenStatus::Active, "{label}");
        let handle = opened.handle.expect("managed reopen retains its actor");
        let run_simple = |query: &str| {
            handle
                .reset_managed_application_query_instrumentation()
                .unwrap();
            let started = Instant::now();
            let outcome = handle
                .application_navigation(SyncApplicationNavigationRequest::SimpleQuery {
                    query: query.into(),
                    max_rows: MAX_ROWS,
                    max_bytes: MAX_BYTES,
                })
                .unwrap();
            let elapsed = started.elapsed();
            let SyncApplicationNavigationOutcome::Loaded {
                reply: SyncApplicationNavigationReply::SimpleQuery(result),
            } = outcome
            else {
                panic!("managed query returned the wrong outcome: {outcome:?}")
            };
            (
                elapsed,
                result,
                handle.managed_application_query_instrumentation().unwrap(),
            )
        };
        let run_graph_search = || {
            handle
                .reset_managed_application_query_instrumentation()
                .unwrap();
            let started = Instant::now();
            let outcome = handle
                .application_navigation(SyncApplicationNavigationRequest::GraphSearch {
                    source: graph_search_source.into(),
                    page_limit: 0,
                    block_limit: MAX_ROWS,
                    lane: Some("performance-receipt".into()),
                    explain: false,
                    scope: None,
                })
                .unwrap();
            let elapsed = started.elapsed();
            let SyncApplicationNavigationOutcome::Loaded {
                reply: SyncApplicationNavigationReply::GraphSearch(result),
            } = outcome
            else {
                panic!("managed graph search returned the wrong outcome: {outcome:?}")
            };
            (
                elapsed,
                result,
                handle.managed_application_query_instrumentation().unwrap(),
            )
        };

        let mut indexed_samples = Vec::with_capacity(samples);
        let mut regex_all_samples = Vec::with_capacity(samples);
        let mut graph_search_samples = Vec::with_capacity(samples);
        let mut indexed_counters = Vec::with_capacity(samples);
        let mut regex_all_counters = Vec::with_capacity(samples);
        let mut graph_search_counters = Vec::with_capacity(samples);
        for sample in 0..samples {
            let (elapsed, result, counters) = run_simple(indexed);
            let bounded_result_rows = result
                .groups
                .iter()
                .map(|group| group.blocks.len())
                .sum::<usize>();
            let bounded_result_total = result.total;
            assert_managed_simple_query_matches_direct(
                &format!("{label} indexed sample={sample}"),
                result,
                direct_indexed.clone(),
            );
            assert_eq!(
                counters.sparse_attempts, 1,
                "indexed task query must make exactly one sparse attempt: {counters:?}"
            );
            assert_eq!(
                counters.sparse_completions, 1,
                "indexed task query must complete exactly one sparse attempt: {counters:?}"
            );
            assert_eq!(
                counters.sparse_fallbacks, 0,
                "indexed task query must not fall back to the page evaluator: {counters:?}"
            );
            assert_eq!(
                counters.full_inventory_passes, 0,
                "indexed task query performed a full inventory scan: {counters:?}"
            );
            assert_eq!(
                counters.inventory_pages, 0,
                "indexed task query visited inventory rows: {counters:?}"
            );
            assert_eq!(
                counters.result_page_hydrations, 0,
                "indexed task query must not hydrate result pages: {counters:?}"
            );
            assert_eq!(
                counters.metadata_page_hydrations, 0,
                "indexed task query must not hydrate metadata pages: {counters:?}"
            );
            assert_eq!(
                counters.sparse_parser_rows, counters.sparse_candidate_rows,
                "indexed task query must parse each deduplicated sparse candidate exactly once: {counters:?}"
            );
            assert_eq!(
                counters.sparse_overlay_rows, 0,
                "the settled indexed-query receipt must have no overlay candidates: {counters:?}"
            );
            assert_eq!(
                counters.sparse_sqlite_rows_fetched, counters.sparse_candidate_rows,
                "settled indexed-query SQLite reads must stay candidate-row bounded: {counters:?}"
            );
            assert_eq!(
                counters.sparse_overlay_index_visits, 0,
                "settled indexed-query receipt must not visit a hot marker index: {counters:?}"
            );
            assert_eq!(
                counters.sparse_overlay_candidate_visits, 0,
                "settled indexed-query receipt must not visit hot candidates: {counters:?}"
            );
            assert_eq!(
                counters.sparse_overlay_structure_lookups, 0,
                "settled indexed-query receipt must not read hot structures: {counters:?}"
            );
            assert_eq!(
                counters.sparse_overlay_raw_bytes_cloned, 0,
                "settled indexed-query receipt must not clone hot raw bytes: {counters:?}"
            );
            assert_eq!(
                counters.sparse_masked_page_fast_forwards, 0,
                "settled indexed-query receipt must not fast-forward masked pages: {counters:?}"
            );
            assert_eq!(
                counters.sparse_dto_constructions, bounded_result_rows,
                "indexed task query must construct DTOs only for its bounded result rows: {counters:?}"
            );
            assert!(
                bounded_result_rows <= bounded_result_total,
                "indexed task query emitted more bounded rows than its total: rows={bounded_result_rows} total={bounded_result_total}"
            );
            if let Some(expected) = expected_task_result_rows {
                assert_eq!(
                    counters.sparse_candidate_rows, expected,
                    "synthetic task candidate density drifted: {counters:?}"
                );
                assert_eq!(
                    counters.sparse_parser_rows, expected,
                    "synthetic task parser rows drifted: {counters:?}"
                );
                assert_eq!(
                    counters.sparse_ancestor_rows, 0,
                    "synthetic root task candidates must not read ancestors: {counters:?}"
                );
                assert_eq!(
                    counters.sparse_dto_constructions, expected,
                    "synthetic task DTO count drifted: {counters:?}"
                );
            }
            indexed_samples.push(elapsed);
            indexed_counters.push(counters);

            let (elapsed, result, counters) = run_simple(regex_all);
            assert_managed_simple_query_matches_direct(
                &format!("{label} Regex-All sample={sample}"),
                result,
                direct_regex_all.clone(),
            );
            assert_eq!(
                counters.full_inventory_passes, 1,
                "Regex-All must make exactly one inventory pass: {counters:?}"
            );
            assert_eq!(
                counters.inventory_pages, total_pages,
                "Regex-All inventory did not cover each page exactly once: {counters:?}"
            );
            assert_eq!(
                counters.result_page_hydrations, total_pages,
                "Regex-All must hydrate every inventoried page as a query result exactly once: {counters:?}"
            );
            regex_all_samples.push(elapsed);
            regex_all_counters.push(counters);

            let (elapsed, mut result, counters) = run_graph_search();
            let mut expected = direct_graph_search.clone();
            canonicalize_graph_search_for_mode_differential(&mut result);
            canonicalize_graph_search_for_mode_differential(&mut expected);
            assert_eq!(
                serde_json::to_value(result).unwrap(),
                serde_json::to_value(expected).unwrap(),
                "managed graph search diverged from parser-owned Direct Files semantics: {label} sample={sample}"
            );
            assert_eq!(
                counters.block_branches, 1,
                "the graph-search receipt must exercise its block branch: {counters:?}"
            );
            assert_eq!(
                counters.full_inventory_passes, 1,
                "graph search must make exactly one inventory pass: {counters:?}"
            );
            assert_eq!(
                counters.inventory_pages, total_pages,
                "graph-search inventory did not cover each page exactly once: {counters:?}"
            );
            assert_eq!(
                counters.result_page_hydrations, total_pages,
                "graph block search must hydrate every inventoried page as a query result exactly once: {counters:?}"
            );
            graph_search_samples.push(elapsed);
            graph_search_counters.push(counters);
        }

        let indexed_p50 = startup_median(&indexed_samples);
        let indexed_p95 = startup_p95(&indexed_samples);
        let regex_all_p50 = startup_median(&regex_all_samples);
        let regex_all_p95 = startup_p95(&regex_all_samples);
        let graph_search_p50 = startup_median(&graph_search_samples);
        let graph_search_p95 = startup_p95(&graph_search_samples);
        eprintln!(
            "managed_query_search_gate fixture={label} pages={total_pages} samples={samples} indexed_p50_ms={:.3} indexed_p95_ms={:.3} regex_all_p50_ms={:.3} regex_all_p95_ms={:.3} graph_search_p50_ms={:.3} graph_search_p95_ms={:.3} indexed_sparse_attempts_max={} indexed_sparse_completions_max={} indexed_sparse_fallbacks_max={} indexed_sparse_candidates_max={} indexed_sparse_sqlite_rows_fetched_max={} indexed_sparse_ancestors_max={} indexed_sparse_parser_rows_max={} indexed_sparse_overlay_rows_max={} indexed_sparse_overlay_index_visits_max={} indexed_sparse_overlay_candidate_visits_max={} indexed_sparse_overlay_structure_lookups_max={} indexed_sparse_overlay_raw_bytes_cloned_max={} indexed_sparse_masked_page_fast_forwards_max={} indexed_sparse_dtos_max={} indexed_inventory_passes_max={} indexed_result_hydrations_max={} indexed_metadata_hydrations_max={} regex_all_inventory_passes_max={} regex_all_result_hydrations_max={} graph_search_inventory_passes_max={} graph_search_result_hydrations_max={}",
            startup_ms(indexed_p50),
            startup_ms(indexed_p95),
            startup_ms(regex_all_p50),
            startup_ms(regex_all_p95),
            startup_ms(graph_search_p50),
            startup_ms(graph_search_p95),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_attempts),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_completions),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_fallbacks),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_candidate_rows),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_sqlite_rows_fetched),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_ancestor_rows),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_parser_rows),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_overlay_rows),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_overlay_index_visits),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_overlay_candidate_visits),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_overlay_structure_lookups),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_overlay_raw_bytes_cloned),
            max_query_gate_counter(&indexed_counters, |counters| counters
                .sparse_masked_page_fast_forwards),
            max_query_gate_counter(&indexed_counters, |counters| counters.sparse_dto_constructions),
            max_query_gate_counter(&indexed_counters, |counters| counters.full_inventory_passes),
            max_query_gate_counter(&indexed_counters, |counters| counters.result_page_hydrations),
            max_query_gate_counter(&indexed_counters, |counters| counters.metadata_page_hydrations),
            max_query_gate_counter(&regex_all_counters, |counters| counters.full_inventory_passes),
            max_query_gate_counter(&regex_all_counters, |counters| counters.result_page_hydrations),
            max_query_gate_counter(&graph_search_counters, |counters| counters.full_inventory_passes),
            max_query_gate_counter(&graph_search_counters, |counters| counters.result_page_hydrations),
        );

        // The indexed task-query ceiling is calibrated from the exact-current
        // release receipt: 10k/100% density measured p95 92.271ms. 150ms
        // preserves modest machine-variance headroom; the remaining limits
        // stay emergency tripwires retained from the predecessor receipt.
        assert!(
            indexed_p95 < Duration::from_millis(150),
            "indexed query calibrated 150ms p95 architectural ceiling exceeded at {label}: {indexed_p95:?}"
        );
        assert!(
            regex_all_p95 < Duration::from_secs(2),
            "Regex-All emergency tripwire exceeded two seconds at {label}: {regex_all_p95:?}"
        );
        assert!(
            graph_search_p95 < Duration::from_secs(2),
            "graph-search emergency tripwire exceeded two seconds at {label}: {graph_search_p95:?}"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn managed_graph_search_accounts_for_pending_overlay_metadata_separately() {
        const TOTAL_PAGES: usize = 16;
        const MAX_ROWS: usize = 20_000;
        let fixture = ActivationFixture::scaled_query_candidate_density(
            "managed-query-search-overlay-accounting",
            0xa2f3,
            TOTAL_PAGES,
            4,
        );
        let overlay_path = Graph::open(&fixture.graph_root)
            .list_pages()
            .into_iter()
            .next()
            .expect("overlay fixture must contain pages")
            .rel_path;

        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let activation_handle = activated.handle.expect("activation retains its actor");
        drive_initial_feed(&activation_handle);
        assert!(matches!(
            activation_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(activation_handle);

        let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
        let handle = opened.handle.expect("managed reopen retains its actor");
        let (mut page, revision) = load_application_exact(&handle, &overlay_path);
        let original_raw = page.blocks[0].raw.clone();
        let edited_raw = format!("{original_raw} active-overlay-edit");
        page.blocks[0].raw = edited_raw.clone();
        let save = handle
            .save_application_page(SyncApplicationPageSaveRequest {
                target: SyncApplicationPageSaveTarget::Existing {
                    path: page.path.clone(),
                    revision: revision.clone(),
                },
                page,
            })
            .unwrap();
        let SyncApplicationPageSaveOutcome::Saved {
            page: saved_page,
            revision: saved_revision,
            ..
        } = save
        else {
            panic!("the overlay fixture edit was not accepted as a changed save: {save:?}")
        };
        assert_eq!(saved_page.blocks[0].raw, edited_raw);
        assert_ne!(
            saved_revision, revision,
            "the overlay fixture must advance the page revision"
        );
        assert_eq!(
            handle.status().unwrap().managed_local_pending,
            1,
            "the query must run with a real, undrained local overlay"
        );
        let direct = Graph::open(&fixture.graph_root);
        let mut expected = direct.run_graph_search("query-density-page", 0, MAX_ROWS, false);
        assert_eq!(
            expected
                .hits
                .iter()
                .filter(|hit| matches!(hit, crate::query_plan::QueryHit::Block { .. }))
                .count(),
            TOTAL_PAGES,
            "the changed direct-file fixture must retain one matching block per page"
        );

        handle
            .reset_managed_application_query_instrumentation()
            .unwrap();
        let outcome = handle
            .application_navigation(SyncApplicationNavigationRequest::GraphSearch {
                source: "query-density-page".into(),
                page_limit: 0,
                block_limit: MAX_ROWS,
                lane: Some("overlay-accounting".into()),
                explain: false,
                scope: None,
            })
            .unwrap();
        let SyncApplicationNavigationOutcome::Loaded {
            reply: SyncApplicationNavigationReply::GraphSearch(mut actual),
        } = outcome
        else {
            panic!("managed graph search returned the wrong outcome: {outcome:?}")
        };
        canonicalize_graph_search_for_mode_differential(&mut actual);
        canonicalize_graph_search_for_mode_differential(&mut expected);
        assert_eq!(
            serde_json::to_value(actual).unwrap(),
            serde_json::to_value(expected).unwrap(),
            "the active-overlay graph search must retain Direct Files semantics"
        );

        let counters = handle.managed_application_query_instrumentation().unwrap();
        assert_eq!(
            counters.full_inventory_passes, 1,
            "graph search must keep its one full inventory pass: {counters:?}"
        );
        assert_eq!(
            counters.inventory_pages, TOTAL_PAGES,
            "graph search must inventory each fixture page once: {counters:?}"
        );
        assert_eq!(
            counters.block_branches, 1,
            "the receipt must execute graph search's block branch: {counters:?}"
        );
        assert_eq!(
            counters.result_page_hydrations, TOTAL_PAGES,
            "every graph-search result page must be hydrated exactly once, independent of metadata work: {counters:?}"
        );
        assert!(
            counters.metadata_page_hydrations > 0,
            "the active overlay must make metadata/context hydration observable instead of hiding it in result work: {counters:?}"
        );

        drain_managed_local(&handle);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    #[ignore = "manual release performance receipt: managed task query densities plus Regex-All and graph search at 1k/10k and optional copied corpus"]
    fn managed_query_search_manual_gate() {
        assert!(
            !cfg!(debug_assertions),
            "run with cargo test -p tine-core --release managed_query_search_manual_gate -- --ignored --nocapture"
        );
        let samples = managed_query_gate_samples();
        for (scale, total_pages) in managed_query_gate_scales().into_iter().enumerate() {
            for (density, candidate_pages) in [
                ("0.1pct", (total_pages.saturating_add(999) / 1_000).max(1)),
                ("10pct", (total_pages.saturating_add(9) / 10).max(1)),
                ("100pct", total_pages),
            ] {
                let fixture = ActivationFixture::scaled_query_candidate_density(
                    "managed-query-search-gate",
                    0xa1f0 + (scale as u128) * 16 + candidate_pages as u128,
                    total_pages,
                    candidate_pages,
                );
                managed_query_search_manual_receipt(
                    &fixture,
                    &format!("synthetic-{total_pages}-{density}"),
                    samples,
                    Some(total_pages),
                    Some(candidate_pages),
                );
            }
        }

        if std::env::var_os("TINE_MANAGED_QUERY_GATE_REAL_GRAPH_COPY").is_some() {
            let source = real_graph_copy_source_from_env("TINE_MANAGED_QUERY_GATE_REAL_GRAPH_COPY");
            let fixture =
                ActivationFixture::copied_graph("managed-query-search-real-copy", 0xa2f0, &source);
            managed_query_search_manual_receipt(
                &fixture,
                "explicit-real-copy",
                samples,
                None,
                None,
            );
        }
    }

    #[test]
    #[ignore = "manual release gate: managed reads on an explicitly supplied backed-up graph copy"]
    fn managed_application_read_real_graph_copy_manual_gate() {
        assert!(
            !cfg!(debug_assertions),
            "this gate is release-only; run with TINE_MANAGED_READ_REAL_GRAPH_COPY=<copy> cargo test -p tine-core --release managed_application_read_real_graph_copy_manual_gate -- --ignored --nocapture"
        );
        let source_root = real_graph_copy_source_from_env("TINE_MANAGED_READ_REAL_GRAPH_COPY");
        let fixture = ActivationFixture::copied_graph(
            "managed-application-read-real-copy",
            0xa140,
            &source_root,
        );
        let source = user_graph_bytes(&fixture.graph_root);
        let direct_graph = Graph::open(&fixture.graph_root);
        let mut direct_entries = direct_graph.list_pages();
        direct_entries.sort_by(|left, right| left.rel_path.cmp(&right.rel_path));
        assert!(!direct_entries.is_empty());
        eprintln!(
            "managed_real_graph_read_gate copied_files={} activating disposable copy",
            direct_entries.len()
        );

        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let activation_handle = activated.handle.expect("activation retains its actor");
        drive_initial_feed(&activation_handle);
        assert!(matches!(
            activation_handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
        drop(activation_handle);

        let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
        let handle = opened.handle.expect("managed reopen retains its actor");
        let engine_before = handle.engine_instrumentation().unwrap();
        let feed_started = Instant::now();
        let mut managed_entries = match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("managed page inventory did not load: {other:?}"),
        };
        managed_entries.sort_by(|left, right| left.rel_path.cmp(&right.rel_path));
        let direct_inventory_semantics = direct_entries
            .iter()
            .map(|entry| {
                (
                    entry.rel_path.clone(),
                    entry.name.clone(),
                    entry.kind,
                    entry.date_key,
                )
            })
            .collect::<Vec<_>>();
        let managed_inventory_semantics = managed_entries
            .iter()
            .map(|entry| {
                (
                    entry.rel_path.clone(),
                    entry.name.clone(),
                    entry.kind,
                    entry.date_key,
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(managed_inventory_semantics, direct_inventory_semantics);

        let all_journals = managed_entries
            .iter()
            .filter(|entry| entry.kind == PageKind::Journal && entry.date_key.is_some())
            .cloned()
            .collect::<Vec<_>>();
        let mut journals = all_journals
            .iter()
            .filter(|entry| {
                entry
                    .date_key
                    .is_some_and(|day| day <= crate::date::JournalDate::today().ordinal_key())
            })
            .cloned()
            .collect::<Vec<_>>();
        if journals.len() < 3 {
            journals = all_journals;
        }
        journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap()));
        assert!(journals.len() >= 3);
        for entry in journals.iter().take(3) {
            let direct = direct_graph.load_page(entry).unwrap();
            let managed = load_application_exact(&handle, &entry.rel_path).0;
            assert_parser_dto_semantics(&direct, &managed);
        }
        let feed_elapsed = feed_started.elapsed();

        let mut direct_samples = Vec::with_capacity(direct_entries.len());
        let mut managed_samples = Vec::with_capacity(direct_entries.len());
        let mut slowest = (Duration::ZERO, String::new());
        for entry in &direct_entries {
            let direct_started = Instant::now();
            let direct = direct_graph.load_page(entry).unwrap();
            direct_samples.push(direct_started.elapsed());

            let managed_started = Instant::now();
            let managed = load_application_exact(&handle, &entry.rel_path).0;
            let managed_elapsed = managed_started.elapsed();
            if managed_elapsed > slowest.0 {
                slowest = (managed_elapsed, entry.rel_path.clone());
            }
            managed_samples.push(managed_elapsed);
            assert_parser_dto_semantics(&direct, &managed);
        }
        let engine_after = handle.engine_instrumentation().unwrap();
        let direct_p50 = startup_median(&direct_samples);
        let direct_p95 = startup_p95(&direct_samples);
        let managed_p50 = startup_median(&managed_samples);
        let managed_p95 = startup_p95(&managed_samples);
        eprintln!(
            "managed_real_graph_read_gate pages={} direct_p50_ms={:.3} direct_p95_ms={:.3} managed_p50_ms={:.3} managed_p95_ms={:.3} journals_first_page_ms={:.3} slowest_managed_ms={:.3} slowest_path={:?}",
            direct_entries.len(),
            startup_ms(direct_p50),
            startup_ms(direct_p95),
            startup_ms(managed_p50),
            startup_ms(managed_p95),
            startup_ms(feed_elapsed),
            startup_ms(slowest.0),
            slowest.1,
        );
        assert!(
            managed_p50 <= Duration::from_millis(50)
                && managed_p50 <= direct_p50.saturating_mul(10),
            "real-copy managed page-open p50 failed: direct={direct_p50:?}, managed={managed_p50:?}"
        );
        assert!(
            managed_p95 <= Duration::from_millis(50)
                && managed_p95 <= direct_p95.saturating_mul(10),
            "real-copy managed page-open p95 failed: direct={direct_p95:?}, managed={managed_p95:?}"
        );
        assert!(
            feed_elapsed <= Duration::from_millis(500),
            "real-copy Journals first-page gate failed: {feed_elapsed:?}"
        );
        assert_eq!(
            engine_after.catalog_hot_state_loads, engine_before.catalog_hot_state_loads,
            "ordinary real-copy reads must not enter hot catalog materialization"
        );
        assert_eq!(user_graph_bytes(&fixture.graph_root), source);
        assert!(matches!(
            handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));
    }

    #[test]
    #[ignore = "manual release benchmark: managed application saves at 100 and 10,000 pages"]
    fn managed_application_save_100_and_10000_page_manual_benchmark() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_application_save_100_and_10000_page_manual_benchmark -- --ignored --nocapture"
        );
        const NAMED_PAGE: &str = "Synthetic 0";
        let page_counts = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_PAGES")
            .ok()
            .map(|value| {
                value
                    .split(',')
                    .map(|part| {
                        part.trim().parse::<usize>().unwrap_or_else(|error| {
                            panic!(
                                "TINE_MANAGED_APPLICATION_SAVE_BENCH_PAGES contains {part:?}: {error}"
                            )
                        })
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| vec![100, 10_000]);
        assert!(
            !page_counts.is_empty() && page_counts.iter().all(|pages| *pages >= 4),
            "managed application-save benchmark needs nonempty total page counts of at least four: {page_counts:?}"
        );
        let target_blocks = managed_application_save_benchmark_target_blocks(
            std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_TARGET_BLOCKS")
                .ok()
                .as_deref(),
        )
        .unwrap_or_else(|error| {
            panic!("TINE_MANAGED_APPLICATION_SAVE_BENCH_TARGET_BLOCKS {error}")
        });
        let p95_ceiling = managed_application_save_benchmark_p95_ceiling(target_blocks);
        let runs = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_RUNS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|runs| *runs > 0)
            .unwrap_or(1);
        let warmups = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_WARMUPS")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(2);
        let samples_per_run = std::env::var("TINE_MANAGED_APPLICATION_SAVE_BENCH_SAMPLES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|samples| *samples > 0)
            .unwrap_or(5);
        let edits_per_run = warmups
            .checked_add(samples_per_run)
            .expect("managed application-save edit count must fit usize");

        for total_pages in page_counts {
            let additional_pages = total_pages - 3;
            let mut managed_samples = Vec::with_capacity(runs * samples_per_run);
            let mut managed_runs = Vec::with_capacity(runs);
            let mut direct_files_samples = Vec::with_capacity(runs * samples_per_run);

            for run in 0..runs {
                let mut managed_run_samples = Vec::with_capacity(samples_per_run);
                let unrelated_blocks = if total_pages >= 10_000 { 1 } else { 10 };
                let fixture = ActivationFixture::scaled_with_target_and_unrelated_blocks(
                    &format!("managed-application-save-{total_pages}-run-{run}"),
                    0xa120 + total_pages as u128 * 16 + run as u128,
                    additional_pages,
                    target_blocks,
                    unrelated_blocks,
                );
                let mut expected_graph = user_graph_bytes(&fixture.graph_root);
                let (source_pages, _, _) = activation_source_counts(&fixture.graph_root);
                assert_eq!(source_pages, total_pages);
                let request = reopen_request(&fixture.request);

                // Activation/import and its startup catch-up are intentionally
                // outside the caller-observed save interval.
                let activated =
                    SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
                assert_eq!(activated.status, SyncLocalActivationStatus::Active);
                let handle = activated
                    .handle
                    .expect("managed application benchmark activation retains a runtime handle");
                drive_initial_feed(&handle);
                let initial_journal = handle
                    .managed_application_save_instrumentation()
                    .expect("benchmark activation exposes local-journal instrumentation");
                assert_eq!(initial_journal.managed_local_next_sequence, 0);
                assert_eq!(initial_journal.managed_local_pending, 0);

                let (mut page, mut revision) =
                    load_application_logical(&handle, NAMED_PAGE, SyncPageKind::Page);
                let target_path = page.path.clone();
                let unchanged_path = expected_graph
                    .keys()
                    .find(|path| *path != &target_path)
                    .expect("scaled benchmark has an unrelated sentinel page")
                    .clone();
                let unchanged_bytes = expected_graph[&unchanged_path].clone();
                let mut expected_journal_targets = Vec::with_capacity(edits_per_run);
                for edit in 0..edits_per_run {
                    let content = format!(
                        "managed application save total-pages={total_pages} run={run} edit={edit}"
                    );
                    page.blocks[0].raw = content.clone();
                    let page_blocks = flatten_application_blocks(&page.blocks).len();
                    let timed = edit >= warmups;
                    let counters_before = handle
                        .managed_application_save_instrumentation()
                        .expect("benchmark save obtains actor foreground instrumentation");
                    let started = Instant::now();
                    let outcome = handle
                        .save_application_page(SyncApplicationPageSaveRequest {
                            target: SyncApplicationPageSaveTarget::Existing {
                                path: target_path.clone(),
                                revision: revision.clone(),
                            },
                            page,
                        })
                        .expect("ordinary managed application save succeeds");
                    let caller = started.elapsed();
                    let counters_after = handle
                        .managed_application_save_instrumentation()
                        .expect("benchmark save obtains post-save foreground instrumentation");
                    let (returned, returned_revision) = match outcome {
                        SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => {
                            (page, revision)
                        }
                        other => {
                            panic!("ordinary managed application save was not direct: {other:?}")
                        }
                    };
                    assert_eq!(returned.path, target_path);
                    assert_eq!(returned.blocks[0].raw, content);
                    assert_ne!(returned_revision, revision);

                    let exact_bytes = fs::read(fixture.graph_root.join(&target_path)).unwrap();
                    assert_eq!(
                        counters_after.managed_local_next_sequence,
                        counters_before.managed_local_next_sequence + 1,
                        "each ordinary save appends exactly one managed-local journal frame"
                    );
                    assert_eq!(
                        counters_after.managed_local_pending,
                        counters_before.managed_local_pending + 1,
                        "the benchmark keeps each accepted frame pending until the post-measurement drain"
                    );
                    expected_journal_targets.push((target_path.clone(), exact_bytes.clone()));
                    expected_graph.insert(target_path.clone(), exact_bytes);
                    assert_eq!(
                        fs::read(fixture.graph_root.join(&unchanged_path)).unwrap(),
                        unchanged_bytes,
                        "ordinary application save leaves an unrelated graph file untouched"
                    );
                    let parsed = Graph::open(&fixture.graph_root)
                        .load_by_path(&target_path)
                        .unwrap()
                        .expect("saved target remains an exact graph page");
                    assert_parser_dto_semantics(&returned, &parsed);
                    let immediate = load_application_exact(&handle, &target_path);
                    assert_parser_dto_semantics(&returned, &immediate.0);
                    assert_eq!(
                        immediate.1, returned_revision,
                        "the returned application revision must be the next save conflict base"
                    );

                    if timed {
                        let page_local_reads = assert_managed_application_save_foreground_counters(
                            counters_before,
                            counters_after,
                            page_blocks,
                        );
                        let local_mutation_detail_accounting =
                            assert_managed_application_save_detail_accounting(
                                counters_after.preparation_stages,
                                counters_after.local_mutation_detail,
                                page_blocks,
                            );
                        assert_managed_application_save_editor_request_accounting(
                            counters_after.application_stages,
                            page_blocks,
                            counters_after.local_mutation_detail,
                            counters_after.prepared_editor_projection,
                        );
                        let sample = ManagedApplicationSaveBenchmarkSample {
                            caller,
                            application_stages: counters_after.application_stages,
                            preparation_stages: counters_after.preparation_stages,
                            local_mutation_detail: counters_after.local_mutation_detail,
                            local_mutation_detail_accounting,
                            stages: counters_after.commit_stages,
                            page_local_reads,
                        };
                        managed_samples.push(sample);
                        managed_run_samples.push(sample);
                    }
                    page = returned;
                    revision = returned_revision;
                }

                // Inspect the active segment before derivative drain can
                // compact its authenticated prefix into a generation anchor.
                let foreground_frames = managed_local_journal_frames(&request);
                assert_eq!(foreground_frames.len(), expected_journal_targets.len());
                for (sequence, (frame, (expected_path, expected_target))) in foreground_frames
                    .iter()
                    .zip(&expected_journal_targets)
                    .enumerate()
                {
                    assert_eq!(frame.sequence(), sequence as u64);
                    let record = decode_managed_local_record(frame).unwrap();
                    assert_eq!(record.projection().intent().path().as_str(), expected_path);
                    assert_eq!(
                        record.projection().intent().target().bytes(),
                        Some(expected_target.as_slice()),
                        "each retained journal frame names the exact graph bytes returned by its save"
                    );
                }

                // All foreground saves above are consecutive. Derivative work
                // begins only after their timing and byte/semantic receipts.
                for _ in 0..edits_per_run.saturating_mul(16).saturating_add(128) {
                    if handle.status().unwrap().managed_local_pending == 0 {
                        break;
                    }
                    handle.tick().unwrap();
                }
                assert_eq!(handle.status().unwrap().managed_local_pending, 0);
                assert_eq!(user_graph_bytes(&fixture.graph_root), expected_graph);
                assert!(matches!(
                    handle.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));
                assert!(
                    managed_local_file_names(&request)
                        .iter()
                        .filter(|name| name.ends_with(".anchor-v2"))
                        .count()
                        > 1,
                    "drain plus test-threshold compaction advances schema-2 authority"
                );

                let reopened = active_handle(SyncRuntimeHandle::open(request));
                drive_initial_feed(&reopened);
                let restored = load_application_exact(&reopened, &target_path);
                assert_parser_dto_semantics(&page, &restored.0);
                assert_eq!(revision, restored.1);
                assert_eq!(user_graph_bytes(&fixture.graph_root), expected_graph);
                assert!(matches!(
                    reopened.clean_shutdown().unwrap(),
                    SyncShutdownOutcome::Safe(_)
                ));

                // Direct Files saves are a separately reported comparable
                // user operation: they avoid the managed application request,
                // actor crossing, journal, and retained semantic overlay.
                let direct_fixture = ActivationFixture::scaled_with_target_and_unrelated_blocks(
                    &format!("direct-files-save-{total_pages}-run-{run}"),
                    0xa220 + total_pages as u128 * 16 + run as u128,
                    additional_pages,
                    target_blocks,
                    unrelated_blocks,
                );
                let mut direct_expected_graph = user_graph_bytes(&direct_fixture.graph_root);
                let (source_pages, _, _) = activation_source_counts(&direct_fixture.graph_root);
                assert_eq!(source_pages, total_pages);
                let direct_graph = Graph::open_checked(&direct_fixture.graph_root)
                    .expect("direct fixture graph opens");
                direct_graph.warm_cache();
                let mut direct_page = direct_graph
                    .load_named(NAMED_PAGE, PageKind::Page)
                    .expect("direct benchmark named-page request succeeds")
                    .expect("direct benchmark synthetic page exists");
                let direct_target_path = direct_page.path.clone();
                let direct_unchanged_path = direct_expected_graph
                    .keys()
                    .find(|path| *path != &direct_target_path)
                    .expect("scaled direct benchmark has an unrelated sentinel page")
                    .clone();
                let direct_unchanged_bytes = direct_expected_graph[&direct_unchanged_path].clone();
                for edit in 0..edits_per_run {
                    let content = format!(
                        "direct files save total-pages={total_pages} run={run} edit={edit}"
                    );
                    let direct_block = &mut direct_page.blocks[0];
                    direct_block.raw = content;
                    direct_block.marker = None;
                    direct_block.properties.clear();
                    direct_block.tags.clear();
                    let started = Instant::now();
                    let next_revision = direct_graph
                        .save_page(&direct_page, direct_page.rev.as_deref())
                        .expect("direct existing-page save succeeds");
                    let caller = started.elapsed();
                    direct_page.rev = Some(next_revision.clone());
                    let exact_bytes =
                        fs::read(direct_fixture.graph_root.join(&direct_target_path)).unwrap();
                    direct_expected_graph.insert(direct_target_path.clone(), exact_bytes);
                    assert_eq!(
                        fs::read(direct_fixture.graph_root.join(&direct_unchanged_path)).unwrap(),
                        direct_unchanged_bytes,
                        "direct save leaves an unrelated graph file untouched"
                    );
                    let parsed = Graph::open(&direct_fixture.graph_root)
                        .load_by_path(&direct_target_path)
                        .unwrap()
                        .expect("direct saved target remains an exact graph page");
                    assert_parser_dto_semantics(&direct_page, &parsed);
                    assert_eq!(parsed.rev.as_deref(), Some(next_revision.as_str()));
                    if edit >= warmups {
                        direct_files_samples.push(caller);
                    }
                }
                assert_eq!(
                    user_graph_bytes(&direct_fixture.graph_root),
                    direct_expected_graph,
                    "the completed Direct Files edit sequence changes exactly its target file"
                );
                managed_runs.push(managed_run_samples);
            }

            assert_eq!(managed_samples.len(), runs * samples_per_run);
            assert_eq!(managed_runs.len(), runs);
            assert_eq!(direct_files_samples.len(), runs * samples_per_run);
            let (managed_p50, managed_p95) =
                managed_application_save_quantiles(&managed_samples, |sample| sample.caller);
            let direct_files_p50 = startup_median(&direct_files_samples);
            let direct_files_p95 = startup_p95(&direct_files_samples);
            eprintln!(
                "managed_application_save_bench total_pages={total_pages} target_blocks={target_blocks} runs={runs} warmups={warmups} samples_per_run={samples_per_run} managed_application_save: {} managed_application_save_runs: {} direct_files_existing_page_save_p50_ms={:.3} direct_files_existing_page_save_p95_ms={:.3} (reported separately; this operation does not perform managed caller work)",
                managed_application_save_phase_receipt(&managed_samples),
                managed_application_save_run_receipt(&managed_runs),
                startup_ms(direct_files_p50),
                startup_ms(direct_files_p95),
            );
            if target_blocks <= 10 {
                assert!(
                    managed_p50 < Duration::from_millis(10),
                    "managed application save ordinary-page p50 exceeded 10 ms at scale={total_pages} pages target_blocks={target_blocks}: p50={managed_p50:?} p95={managed_p95:?}"
                );
            }
            assert!(
                managed_p95 < p95_ceiling,
                "managed application save p95 exceeded {:?} at scale={total_pages} pages target_blocks={target_blocks}: p50={managed_p50:?} p95={managed_p95:?}",
                p95_ceiling,
            );
        }
    }

    #[test]
    #[ignore = "manual crash-reopen receipt for the reported 1,045-file graph scale"]
    fn managed_startup_crash_reopen_1045_file_manual_receipt() {
        assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_startup_crash_reopen_1045_file_manual_receipt -- --ignored --nocapture"
        );
        const ADDITIONAL_PAGES: usize = 1_041;
        const EXPECTED_PAGES: usize = ADDITIONAL_PAGES + 4;
        let fixture = ActivationFixture::scaled_with_blocks(
            "managed-startup-crash-reopen-1045-file",
            0xa0e0,
            ADDITIONAL_PAGES,
            10,
        );
        let source = user_graph_bytes(&fixture.graph_root);
        assert_eq!(source.len(), EXPECTED_PAGES);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        drop(activated.handle);
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            source,
            "activation and an unclean actor stop must preserve exact graph bytes"
        );

        let workspace_id = fixture.request.identities.workspace_id;
        reset_runtime_open_instrumentation(workspace_id);
        reset_promoted_runtime_open_instrumentation(workspace_id);
        let started = Instant::now();
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        let elapsed = started.elapsed();
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let handle = reopened
            .handle
            .expect("crash takeover returns an active handle");
        assert_eq!(
            handle.status().unwrap().recovery,
            Some(SyncRuntimeRecovery::TookOverCrashedUnsafe)
        );
        let open = take_runtime_open_instrumentation(workspace_id);
        let promoted = take_promoted_runtime_open_instrumentation(workspace_id);
        let resume = handle.engine_instrumentation().unwrap().resume;
        assert!(
            resume.adopted,
            "crash reopen did not adopt its retained run"
        );
        assert!(!resume.refused, "crash reopen refused its retained run");
        assert_eq!(
            resume.replayed_generations, 0,
            "an exact-current crash reopen replayed graph-sized accepted history"
        );
        assert_eq!(
            promoted.engine.bootstrap_parts_examined, 0,
            "an exact-current crash reopen replayed bootstrap parts"
        );
        eprintln!(
            "managed_startup_crash_reopen files={EXPECTED_PAGES} elapsed_ms={:.3} open_phases: {} promoted_phases: {} resume={:?}",
            startup_ms(elapsed),
            startup_open_phase_receipt(&open),
            startup_promoted_open_phase_receipt(&promoted),
            resume,
        );

        let page = load_application_logical(&handle, "Synthetic 0", SyncPageKind::Page).0;
        assert_eq!(page.name, "Synthetic 0");
        assert_eq!(page.blocks.len(), 10);
        assert_eq!(user_graph_bytes(&fixture.graph_root), source);
        drop(handle);
    }

    fn tree_has_file_named(root: &Path, name: &str) -> bool {
        let mut pending = vec![root.to_path_buf()];
        while let Some(directory) = pending.pop() {
            for entry in fs::read_dir(directory).unwrap().map(Result::unwrap) {
                if entry.file_type().unwrap().is_dir() {
                    pending.push(entry.path());
                } else if entry.file_name() == name {
                    return true;
                }
            }
        }
        false
    }

    #[test]
    fn explicit_local_activation_preserves_nested_unicode_graph_bytes_and_proves_backup_sqlite() {
        let fixture = ActivationFixture::nested_unicode("journey", 0xa100);
        let before = user_graph_bytes(&fixture.graph_root);

        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated
            .handle
            .expect("activation must retain the runtime handle");
        assert!(fixture.request.database_path.is_file());
        assert!(tree_has_file_named(
            &fixture.request.migration_backup_root,
            "restore-proof.bin"
        ));
        assert!(tree_has_file_named(
            &fixture.request.migration_backup_root,
            "committed.bin"
        ));
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            before,
            "activation may create only the shared .tine-sync/v2 namespace, never rewrite graph bytes"
        );
        drive_initial_feed(&handle);
        assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            before,
            "aggregate bootstrap authority confirmation and the initial exact feed must remain read-only"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn fresh_activation_retains_one_bootstrap_authority_and_zero_ordinary_page_receipts() {
        let fixture = ActivationFixture::nested_unicode("aggregate-bootstrap-authority", 0xa180);
        let before = user_graph_bytes(&fixture.graph_root);

        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("activation must retain an actor");
        assert_eq!(user_graph_bytes(&fixture.graph_root), before);

        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let endpoint = ProjectionEndpointBinding {
            endpoint_id: fixture.request.identities.endpoint_id,
            device_id: fixture.request.identities.device_id,
            graph_resource_id: graph.canonical_resource_id().unwrap(),
        };
        drop(graph);
        let receipts = ProjectionReceiptStore::open_for_endpoint(
            &fixture.request.receipt_root,
            fixture.request.identities.workspace_id,
            endpoint,
        )
        .unwrap();
        let ordinary_catalog = receipts.validated_catalog().unwrap();
        assert!(
            ordinary_catalog.is_empty(),
            "activation must create zero per-page intents, attempts, completions, or completed-path transitions: {ordinary_catalog:?}"
        );
        assert!(
            !fixture
                .request
                .application_runtime_root
                .join("bootstrap-projection-receipts-v1.json")
                .exists(),
            "aggregate authority replaces the eager-receipt completion marker"
        );
        drop(handle);
    }

    #[test]
    fn uninterrupted_activation_reuses_complete_proof_but_fresh_reopen_revalidates() {
        use crate::oplog::shadow_projection::{
            aggregate_reopen_calls_for_test, complete_shadow_verification_calls_for_test,
            reset_aggregate_reopen_calls_for_test,
            reset_complete_shadow_verification_calls_for_test,
        };

        let fixture = ActivationFixture::nested_unicode("retained-complete-proof", 0xa1b0);
        let workspace = fixture.request.identities.workspace_id;
        reset_complete_shadow_verification_calls_for_test(workspace);
        reset_aggregate_reopen_calls_for_test(workspace);
        reset_activation_actor_open_instrumentation(workspace);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        assert_eq!(
            complete_shadow_verification_calls_for_test(workspace),
            1,
            "adjacent VerifiedLocal/LocalActive/promotion transitions reran full shadow proof"
        );
        assert_eq!(
            aggregate_reopen_calls_for_test(workspace),
            1,
            "uninterrupted activation must reopen the bootstrap aggregate only for promotion, not again for actor startup"
        );
        assert_eq!(
            activation_actor_open_instrumentation(workspace),
            ActivationActorOpenInstrumentation {
                cold_actor_opens: 0,
                retained_handoffs: 1,
            },
            "uninterrupted activation must hand the retained graph, receipts, SQLite, and engine directly to its actor"
        );
        let handle = activated.handle.unwrap();
        drive_initial_feed(&handle);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));

        reset_aggregate_reopen_calls_for_test(workspace);
        reset_activation_actor_open_instrumentation(workspace);
        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        assert_eq!(
            aggregate_reopen_calls_for_test(workspace),
            1,
            "fresh-process promoted open must perform one complete aggregate publication validation"
        );
        assert_eq!(
            activation_actor_open_instrumentation(workspace),
            ActivationActorOpenInstrumentation {
                cold_actor_opens: 1,
                retained_handoffs: 0,
            },
            "a fresh reopen must retain the complete recovery boundary"
        );
        drop(reopened.handle);
    }

    #[test]
    fn first_external_change_publishes_an_ordinary_receipt_that_supersedes_after_restart() {
        const PATH: &str = "Root.md";
        let fixture = ActivationFixture::nested_unicode("bootstrap-supersession", 0xa1d0);
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("activation must retain an actor");
        drive_initial_feed(&handle);

        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let endpoint = ProjectionEndpointBinding {
            endpoint_id: fixture.request.identities.endpoint_id,
            device_id: fixture.request.identities.device_id,
            graph_resource_id: graph.canonical_resource_id().unwrap(),
        };
        drop(graph);
        let completion_count = || {
            ProjectionReceiptStore::open_for_endpoint(
                &fixture.request.receipt_root,
                fixture.request.identities.workspace_id,
                endpoint,
            )
            .unwrap()
            .validated_catalog()
            .unwrap()
            .into_iter()
            .filter(|entry| entry.completion.is_some())
            .count()
        };
        assert_eq!(completion_count(), 0);

        let edited = b"title:: Root logical\r\n\r\n- externally changed exact bytes\r\n";
        fs::write(fixture.graph_root.join(PATH), edited).unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(PATH).unwrap()])
            .unwrap();
        let settled = drain_until_settled(&handle);
        assert!(
            settled
                .iter()
                .any(|tick| matches!(tick, SyncRuntimeTick::AdmittedComplete { .. })),
            "bootstrap-backed external edit did not complete: {settled:?}"
        );
        assert_eq!(fs::read(fixture.graph_root.join(PATH)).unwrap(), edited);
        let after_import = completion_count();
        assert_eq!(after_import, 1);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));

        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let reopened = reopened.handle.expect("promoted runtime must reopen");
        drive_initial_feed(&reopened);
        assert_eq!(completion_count(), after_import);
        assert_eq!(fs::read(fixture.graph_root.join(PATH)).unwrap(), edited);
        assert!(matches!(
            reopened.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn first_local_edit_uses_bootstrap_then_ordinary_receipt_supersedes_after_restart() {
        const PATH: &str =
            "notes/層/\u{017e}lu\u{0165}ou\u{010d}k\u{00fd}/nested/D\u{00e9}j\u{00e0} 計画.md";
        const FIRST_EDIT: &str = "Unicode café — edited locally";
        const SECOND_EDIT: &str = "Unicode café — accepted after restart";

        fn bootstrap_payload(root: &Path, managed_path: &str) -> PathBuf {
            let suffix = Path::new("payload").join(managed_path);
            let mut pending = vec![root.to_path_buf()];
            while let Some(directory) = pending.pop() {
                for entry in fs::read_dir(directory).unwrap().map(Result::unwrap) {
                    if entry.file_type().unwrap().is_dir() {
                        pending.push(entry.path());
                    } else if entry.path().ends_with(&suffix) {
                        return entry.path();
                    }
                }
            }
            panic!("bootstrap payload for {managed_path} was not retained");
        }

        let fixture = ActivationFixture::nested_unicode("local-bootstrap-supersession", 0xa1e0);
        fs::write(
            fixture.graph_root.join(PATH),
            "- Unicode café\r\n".as_bytes(),
        )
        .unwrap();
        let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(activated.status, SyncLocalActivationStatus::Active);
        let handle = activated.handle.expect("activation must retain an actor");
        drive_initial_feed(&handle);

        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let endpoint = ProjectionEndpointBinding {
            endpoint_id: fixture.request.identities.endpoint_id,
            device_id: fixture.request.identities.device_id,
            graph_resource_id: graph.canonical_resource_id().unwrap(),
        };
        drop(graph);
        let completed_paths = || {
            ProjectionReceiptStore::open_for_endpoint(
                &fixture.request.receipt_root,
                fixture.request.identities.workspace_id,
                endpoint,
            )
            .unwrap()
            .validated_catalog()
            .unwrap()
            .into_iter()
            .filter_map(|entry| entry.completion.map(|_| entry.intent.path().clone()))
            .collect::<Vec<_>>()
        };
        assert!(
            completed_paths().is_empty(),
            "activation must not synthesize ordinary page completions"
        );

        let pages = handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: Some(SyncPageKind::Page),
                limit: 16,
            })
            .unwrap();
        let SyncRuntimeQueryReply::Pages(pages) = pages else {
            panic!("page list returned the wrong reply variant");
        };
        let page_id = pages
            .into_iter()
            .find(|page| page.path == PATH)
            .expect("nested Unicode bootstrap page must be materialized")
            .page_id;
        let mut page = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::PageId {
                    page_id: page_id.clone(),
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::Loaded { page } => page,
            other => panic!("bootstrap page did not load for editing: {other:?}"),
        };
        assert_eq!(page.blocks[0].content, "Unicode café");
        page.blocks[0].content = FIRST_EDIT.into();
        let saved = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: page.page_id,
                    revision: page.revision,
                },
                preamble: page.preamble,
                blocks: page.blocks,
            })
            .unwrap();
        assert!(
            matches!(saved, SyncEditorSaveOutcome::Durable { .. }),
            "bootstrap-backed local edit did not publish: {saved:?}"
        );
        assert_eq!(
            fs::read(fixture.graph_root.join(PATH)).unwrap(),
            format!("- {FIRST_EDIT}\r\n").as_bytes()
        );
        assert!(completed_paths().is_empty());
        drain_managed_local(&handle);
        assert_eq!(
            completed_paths(),
            vec![ManagedPath::parse(PATH).unwrap()],
            "the first real projection must complete only the edited page"
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));

        let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
        let reopened = reopened.handle.expect("promoted runtime must reopen");
        drive_initial_feed(&reopened);
        let mut page = match reopened
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::PageId { page_id },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::Loaded { page } => page,
            other => panic!("locally edited page did not reopen: {other:?}"),
        };
        assert_eq!(page.blocks[0].content, FIRST_EDIT);

        fs::write(
            bootstrap_payload(&fixture.request.migration_backup_root, PATH),
            b"corrupt aggregate fallback",
        )
        .unwrap();
        page.blocks[0].content = SECOND_EDIT.into();
        let saved = reopened
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: page.page_id,
                    revision: page.revision,
                },
                preamble: page.preamble,
                blocks: page.blocks,
            })
            .unwrap();
        match saved {
            SyncEditorSaveOutcome::Durable { .. } => {}
            SyncEditorSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                ..
            } => {
                settle_local_mutation(&reopened);
            }
            other => {
                panic!(
                    "restart did not select the ordinary receipt over aggregate fallback: {other:?}"
                );
            }
        }
        drain_managed_local(&reopened);
        assert_eq!(
            fs::read(fixture.graph_root.join(PATH)).unwrap(),
            format!("- {SECOND_EDIT}\r\n").as_bytes()
        );
        let completed = completed_paths();
        assert_eq!(completed.len(), 2);
        assert!(completed.iter().all(|path| path.as_str() == PATH));
        assert!(matches!(
            reopened.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    fn assert_public_activation_cut_resumes(
        label: &str,
        cut: ActivationTestCut,
        expected_stage: SyncLocalActivationStage,
        seed: u128,
    ) {
        let fixture = ActivationFixture::nested_unicode(label, seed);
        let before = user_graph_bytes(&fixture.graph_root);
        fail_once_at_activation_cut(cut);
        let mut interrupted_phases = Vec::new();
        let interrupted = SyncRuntimeHandle::activate_or_resume_local_with_progress(
            fixture.request.clone(),
            |phase| interrupted_phases.push(phase),
        );
        assert!(matches!(
            interrupted.status,
            SyncLocalActivationStatus::Retryable { durable_stage, .. }
                if durable_stage == expected_stage
        ));
        assert!(interrupted.handle.is_none());
        assert_eq!(user_graph_bytes(&fixture.graph_root), before);
        assert!(interrupted_phases
            .first()
            .is_none_or(|phase| *phase == SyncLocalActivationPhase::PrivateSetup));

        let mut resumed_phases = Vec::new();
        let resumed = SyncRuntimeHandle::activate_or_resume_local_with_progress(
            fixture.request.clone(),
            |phase| resumed_phases.push(phase),
        );
        assert_eq!(resumed.status, SyncLocalActivationStatus::Active);
        let handle = resumed
            .handle
            .expect("resumed activation must become active");
        assert_eq!(
            resumed_phases.last(),
            Some(&SyncLocalActivationPhase::ReconciliationBaselineActorOpen)
        );
        assert_eq!(user_graph_bytes(&fixture.graph_root), before);
        drop(handle);
    }

